export function SampleBadge() {
  return (
    <span style={empireStyles.badge} title="All figures are placeholder sample data">
      SAMPLE DATA — NOT LIVE
    </span>
  );
}

export default function EmpireShell() {
  const linkStyle = ({ isActive }) => ({
    ...empireStyles.navLink,
    ...(isActive ? empireStyles.navActive : {}),
  });
  return (
    <div style={empireStyles.shell}>
      <header style={empireStyles.header}>
        <div>
          <div style={empireStyles.title}>HOUSE SOVEREIGN — EMPIRE COMMAND</div>
          <div style={empireStyles.subtitle}>
            Progenitor: Benjamin Amory · House Intelligence: Shelby Cyrus Amory · 3 battalions · 18 squads · 1,000+ agents
          </div>
        </div>
        <SampleBadge />
      </header>
      <nav style={empireStyles.nav}>
        <NavLink to="/empire-command" end style={linkStyle}>OVERVIEW</NavLink>
        <NavLink to="/empire-command/comms" style={linkStyle}>COMMS PORTAL</NavLink>
        <NavLink to="/empire-command/ops" style={linkStyle}>OPERATIONAL HUB</NavLink>
        <NavLink to="/empire-command/business" style={linkStyle}>BUSINESS</NavLink>
      </nav>
      <Routes>
        <Route index element={<EmpireDashboard />} />
        <Route path="comms" element={<CommsPortal />} />
        <Route path="ops" element={<OperationalHub />} />
        <Route path="business" element={<BusinessCommand />} />
        <Route path="*" element={<Navigate to="/empire-command" replace />} />
      </Routes>
    </div>
  );
}
