// ═══════════════════════════════════════════════════════════════════════════════
// KITSUNE FIELD — 48-channel spatial audio field UI
// Owner canon: KITSUNE = 48 channels = 4 rings × 12 voices.
//   RING 1 CORE · RING 2 MID-FIELD · RING 3 HIGH-FIELD · RING 4 ULTRA-FIELD
// Aesthetic: purple wireframe on black (owner's reference: neon grid field).
//
// LIVE AUDIO: controls drive the KITSUNE engine (src/lib/kitsune.js) — native
// Web Audio API, HRTF panners, per-ring air/delay modeling, 3-band crossover
// per ring (Internal Multi-Band Transducer), Web-Tuned Resonance bank.
// The engine starts silent; sources attach only on user action.
// ═══════════════════════════════════════════════════════════════════════════════

import React, { useState, useRef, useEffect, useCallback } from 'react';
import * as kitsune from '@/lib/kitsune';
import * as hitachi from '@/lib/hitachi';

const API_URL = process.env.REACT_APP_BACKEND_URL || '';
const PURPLE = '#a855f7';
const PURPLE_DIM = '#6b21a8';
const RING_NAMES = { 1: 'CORE', 2: 'MID-FIELD', 3: 'HIGH-FIELD', 4: 'ULTRA-FIELD' };
const RING_RX = { 1: 62, 2: 102, 3: 142, 4: 178 };
const RING_RY = { 1: 38, 2: 63, 3: 88, 4: 110 };
const RING_DIST = { 1: 1.5, 2: 6, 3: 16, 4: 35 };

const defaultVoices = () => {
  const v = {};
  for (let r = 1; r <= 4; r++) {
    for (let c = 1; c <= 12; c++) {
      v[`${r}:${c}`] = { azimuth: (((c - 1) * 30 + 180) % 360) - 180, elevation: 0, distance: RING_DIST[r], gain: 0.8, mute: false };
    }
  }
  return v;
};

const defaultRings = () => ({
  1: { gain: 0.8, mute: false, solo: false, bandGains: { low: 1, mid: 1, high: 1 } },
  2: { gain: 0.8, mute: false, solo: false, bandGains: { low: 1, mid: 1, high: 1 } },
  3: { gain: 0.8, mute: false, solo: false, bandGains: { low: 1, mid: 1, high: 1 } },
  4: { gain: 0.8, mute: false, solo: false, bandGains: { low: 1, mid: 1, high: 1 } },
});

function Slider({ label, min, max, step, value, onChange, testid, accent = PURPLE }) {
  return (
    <label className="flex items-center gap-2 text-[10px] text-purple-300/80 font-mono">
      <span className="w-14 shrink-0 uppercase tracking-wide">{label}</span>
      <input
        type="range" min={min} max={max} step={step} value={value}
        onChange={(e) => onChange(Number(e.target.value))}
        className="flex-1 h-1.5" style={{ accentColor: accent }}
        data-testid={testid} aria-label={label}
      />
      <span className="w-12 text-right text-purple-200">{value}</span>
    </label>
  );
}

function Toggle({ label, active, onClick, testid, activeClass }) {
  return (
    <button
      onClick={onClick} data-testid={testid} title={label}
      className={`text-[10px] font-bold px-2 py-1 rounded border transition-colors ${
        active ? activeClass : 'bg-white/5 text-gray-500 border-white/10 hover:bg-white/10'
      }`}
    >
      {label}
    </button>
  );
}

export function KitsuneField() {
  const [voices, setVoices] = useState(defaultVoices);
  const [ringState, setRingState] = useState(defaultRings);
  const [resonance, setResonanceState] = useState({ freq: 440, q: 8, gain: 0 });
  const [selected, setSelected] = useState({ ring: 1, ch: 1 });
  const [engineOn, setEngineOn] = useState(false);
  const [feedOn, setFeedOn] = useState(false);
  const [status, setStatus] = useState(kitsune.engineStatus());
  const [levels, setLevels] = useState(new Array(48).fill(0));
  const [presets, setPresets] = useState([]);
  const [presetName, setPresetName] = useState('');
  const [toneOn, setToneOn] = useState({});
  const persistTimers = useRef({});
  const ringStateRef = useRef(ringState);
  ringStateRef.current = ringState;
  const resonanceRef = useRef(resonance);
  resonanceRef.current = resonance;

  const persistRing = useCallback((ring, state) => {
    clearTimeout(persistTimers.current[`ring${ring}`]);
    persistTimers.current[`ring${ring}`] = setTimeout(() => {
      fetch(`${API_URL}/api/daw/kitsune/ring/${ring}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          gain: state.gain, mute: state.mute, solo: state.solo,
          band_gains: state.bandGains,
        }),
      }).catch(() => { /* backend optional — engine keeps running */ });
    }, 450);
  }, []);

  const liveVoice = useCallback((ring, ch, patch) => {
    setVoices((prev) => {
      const key = `${ring}:${ch}`;
      const next = { ...prev, [key]: { ...prev[key], ...patch } };
      const v = next[key];
      kitsune.setVoice(ring, ch, v);
      return next;
    });
  }, []);

  const liveRing = useCallback((ring, patch) => {
    setRingState((prev) => {
      const next = { ...prev, [ring]: { ...prev[ring], ...patch } };
      const s = next[ring];
      kitsune.setRing(ring, { gain: s.gain, mute: s.mute, solo: s.solo, bandGains: s.bandGains });
      persistRing(ring, s);
      return next;
    });
  }, [persistRing]);

  const liveResonance = useCallback((patch) => {
    setResonanceState((prev) => {
      const next = { ...prev, ...patch };
      kitsune.setResonance(next);
      return next;
    });
  }, []);

  const powerOn = useCallback(async () => {
    await kitsune.init(); // user gesture — AudioContext safe
    setVoices((prev) => {
      for (let r = 1; r <= 4; r++) {
        for (let c = 1; c <= 12; c++) kitsune.setVoice(r, c, prev[`${r}:${c}`]);
        const s = ringStateRef.current[r];
        kitsune.setRing(r, { gain: s.gain, mute: s.mute, solo: s.solo, bandGains: s.bandGains });
      }
      return prev;
    });
    kitsune.setResonance(resonanceRef.current);
    setStatus(kitsune.engineStatus());
    setEngineOn(true);
  }, []);

  const powerOff = useCallback(async () => {
    await kitsune.shutdown();
    setStatus(kitsune.engineStatus());
    setLevels(new Array(48).fill(0));
    setEngineOn(false);
    setFeedOn(false);
  }, []);

  // Feed the 24 HITACHI strips into KITSUNE voices on ONE shared context.
  const toggleFeed = useCallback(async () => {
    if (feedOn) {
      kitsune.detachHitachiFeed();
      setFeedOn(false);
      setStatus(kitsune.engineStatus());
      return;
    }
    await hitachi.init(); // user gesture; HITACHI owns the shared context
    const hctx = hitachi.getContext();
    if (!hctx) return;
    if (engineOn) await kitsune.shutdown(); // re-init on the shared context
    await kitsune.init({ context: hctx });
    const res = kitsune.attachHitachiFeed();
    if (res.ok) {
      setFeedOn(true);
      setEngineOn(true);
    }
    setStatus(kitsune.engineStatus());
  }, [feedOn, engineOn]);

  const toggleTone = useCallback((ring, ch) => {
    const res = kitsune.toggleTestTone(ring, ch, 220 + ring * 110 + ch * 15);
    setToneOn((prev) => ({ ...prev, [`${ring}:${ch}`]: res.tone }));
  }, []);

  // Meters + status while running.
  useEffect(() => {
    if (!engineOn) return;
    const id = setInterval(() => {
      setLevels(kitsune.getVoiceLevels());
      setStatus(kitsune.engineStatus());
    }, 140);
    return () => clearInterval(id);
  }, [engineOn]);

  // Preset list from backend (defensive).
  const refreshPresets = useCallback(() => {
    fetch(`${API_URL}/api/daw/kitsune/presets`)
      .then((r) => (r.ok ? r.json() : null))
      .then((d) => { if (d && Array.isArray(d.presets)) setPresets(d.presets); })
      .catch(() => { /* backend optional */ });
  }, []);
  useEffect(() => { refreshPresets(); }, [refreshPresets]);

  const savePreset = useCallback(() => {
    const name = presetName.trim() || `kitsune-field-${new Date().toISOString().slice(0, 19)}`;
    fetch(`${API_URL}/api/daw/kitsune/preset`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name, state: { voices, rings: ringState, resonance } }),
    })
      .then(() => { setPresetName(''); refreshPresets(); })
      .catch(() => { /* backend optional */ });
  }, [presetName, voices, ringState, resonance, refreshPresets]);

  useEffect(() => () => { powerOff(); }, [powerOff]);

  const sel = voices[`${selected.ring}:${selected.ch}`];
  const CX = 200; const CY = 200;

  return (
    <div className="rounded-xl border border-purple-500/30 bg-black p-4 mt-6" data-testid="kitsune-field">
      <div className="flex items-center justify-between mb-3 flex-wrap gap-2">
        <div>
          <h3 className="text-sm font-bold text-purple-200 tracking-wide">KITSUNE · 48-Channel Spatial Field</h3>
          <p className="text-[10px] text-purple-400/60 font-mono">4 rings × 12 voices · HRTF · multi-band transducer · web-tuned resonance</p>
        </div>
        <div className="flex items-center gap-3 flex-wrap">
          <span className="text-[10px] font-mono text-purple-300/80" data-testid="kitsune-status-readout">
            {status.running
              ? `● LIVE · ${(status.sampleRate / 1000).toFixed(1)}kHz · ${(status.baseLatency * 1000).toFixed(1)}ms · 48ch · CLYDE port ready`
              : '○ ENGINE OFF'}
          </span>
          <button
            onClick={toggleFeed} data-testid="kitsune-feed-toggle"
            className={`text-xs font-bold px-3 py-1.5 rounded-lg border transition-colors ${
              feedOn ? 'bg-purple-500/30 text-purple-100 border-purple-400/60'
                     : 'bg-white/5 text-purple-300 border-purple-500/40 hover:bg-purple-500/20'
            }`}
            title="Route the 24 HITACHI strips into KITSUNE voices on one shared AudioContext"
          >
            {feedOn ? '⏚ HITACHI feed live' : '⏚ Feed from HITACHI'}
          </button>
          <button
            onClick={engineOn ? powerOff : powerOn} data-testid="kitsune-power-toggle"
            className={`text-xs font-bold px-3 py-1.5 rounded-lg border transition-colors ${
              engineOn ? 'bg-red-500/20 text-red-300 border-red-500/40'
                       : 'bg-emerald-500/20 text-emerald-300 border-emerald-500/40 hover:bg-emerald-500/30'
            }`}
          >
            {engineOn ? '⏻ KITSUNE On — Power Off' : '⏻ Power On KITSUNE'}
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        {/* Wireframe field */}
        <div className="rounded-lg border border-purple-500/20 bg-black p-2">
          <svg viewBox="0 0 400 400" className="w-full h-auto select-none" role="img" aria-label="KITSUNE 48-channel wireframe field">
            {/* spokes */}
            {Array.from({ length: 12 }, (_, i) => {
              const a = ((i * 30 - 90) * Math.PI) / 180;
              return (
                <line key={i} x1={CX + 30 * Math.cos(a)} y1={CY + 19 * Math.sin(a)}
                  x2={CX + 190 * Math.cos(a)} y2={CY + 118 * Math.sin(a)}
                  stroke={PURPLE_DIM} strokeWidth="0.6" opacity="0.5" />
              );
            })}
            {/* rings */}
            {[1, 2, 3, 4].map((r) => (
              <g key={r}>
                <ellipse cx={CX} cy={CY} rx={RING_RX[r]} ry={RING_RY[r]}
                  fill="none" stroke={PURPLE} strokeWidth={r === 1 ? 1.6 : 1} opacity={0.85} />
                <text x={CX + RING_RX[r] * 0.72} y={CY - RING_RY[r] * 0.72}
                  fill={PURPLE} fontSize="9" fontFamily="monospace" opacity="0.9">
                  R{r} {RING_NAMES[r]}
                </text>
              </g>
            ))}
            {/* voice nodes */}
            {[1, 2, 3, 4].map((r) =>
              Array.from({ length: 12 }, (_, i) => {
                const c = i + 1;
                const a = (((c - 1) * 30 - 90) * Math.PI) / 180;
                const x = CX + RING_RX[r] * Math.cos(a);
                const y = CY + RING_RY[r] * Math.sin(a);
                const lvl = levels[(r - 1) * 12 + i] || 0;
                const isSel = selected.ring === r && selected.ch === c;
                const v = voices[`${r}:${c}`];
                return (
                  <g key={`${r}:${c}`} onClick={() => setSelected({ ring: r, ch: c })}
                     style={{ cursor: 'pointer' }} data-testid={`kitsune-node-r${r}c${c}`}>
                    {isSel && <circle cx={x} cy={y} r={11} fill="none" stroke="#e9d5ff" strokeWidth="1.4" />}
                    <circle cx={x} cy={y} r={4.5 + lvl * 4}
                      fill={v && v.mute ? '#3b0764' : PURPLE}
                      opacity={0.35 + lvl * 0.65}
                      stroke={isSel ? '#ffffff' : PURPLE_DIM} strokeWidth="1" />
                  </g>
                );
              })
            )}
            <text x={CX} y={CY + 4} fill={PURPLE} fontSize="10" fontFamily="monospace"
              textAnchor="middle" opacity="0.8">KITSUNE</text>
          </svg>
          <p className="text-[10px] text-purple-400/60 font-mono text-center mt-1">
            Click a node to select a voice · nodes pulse with live levels
          </p>
        </div>

        {/* Controls */}
        <div className="space-y-4">
          {/* Selected voice */}
          <div className="rounded-lg border border-purple-500/20 bg-purple-950/20 p-3">
            <div className="flex items-center justify-between mb-2">
              <h4 className="text-xs font-bold text-purple-200 font-mono">
                VOICE R{selected.ring}·C{selected.ch} <span className="text-purple-400/70">— {RING_NAMES[selected.ring]}</span>
              </h4>
              <div className="flex gap-1.5">
                <Toggle label={sel.mute ? 'UNMUTE' : 'MUTE'} active={sel.mute} testid="kitsune-voice-mute"
                  activeClass="bg-red-500/30 text-red-200 border border-red-400/50"
                  onClick={() => liveVoice(selected.ring, selected.ch, { mute: !sel.mute })} />
                <Toggle label={toneOn[`${selected.ring}:${selected.ch}`] ? 'TONE ■' : 'TONE ▸'} testid="kitsune-voice-tone"
                  active={!!toneOn[`${selected.ring}:${selected.ch}`]}
                  activeClass="bg-amber-500/30 text-amber-200 border border-amber-400/50"
                  onClick={() => toggleTone(selected.ring, selected.ch)} />
              </div>
            </div>
            <div className="space-y-1.5">
              <Slider label="Azimuth°" min={-180} max={180} step={1} value={sel.azimuth} testid="kitsune-voice-azimuth"
                onChange={(v) => liveVoice(selected.ring, selected.ch, { azimuth: v })} />
              <Slider label="Elev°" min={-90} max={90} step={1} value={sel.elevation} testid="kitsune-voice-elevation"
                onChange={(v) => liveVoice(selected.ring, selected.ch, { elevation: v })} />
              <Slider label="Dist m" min={0.5} max={80} step={0.5} value={sel.distance} testid="kitsune-voice-distance"
                onChange={(v) => liveVoice(selected.ring, selected.ch, { distance: v })} />
              <Slider label="Gain" min={0} max={1.5} step={0.01} value={sel.gain} testid="kitsune-voice-gain"
                onChange={(v) => liveVoice(selected.ring, selected.ch, { gain: v })} />
            </div>
          </div>

          {/* Ring buses */}
          <div className="grid grid-cols-2 gap-2">
            {[1, 2, 3, 4].map((r) => {
              const s = ringState[r];
              return (
                <div key={r} className="rounded-lg border border-purple-500/20 bg-black/60 p-2.5">
                  <div className="flex items-center justify-between mb-1.5">
                    <span className="text-[10px] font-bold text-purple-200 font-mono">R{r} {RING_NAMES[r]}</span>
                    <div className="flex gap-1">
                      <Toggle label="M" active={s.mute} testid={`kitsune-ring${r}-mute`}
                        activeClass="bg-red-500/30 text-red-200 border border-red-400/50"
                        onClick={() => liveRing(r, { mute: !s.mute })} />
                      <Toggle label="S" active={s.solo} testid={`kitsune-ring${r}-solo`}
                        activeClass="bg-amber-500/30 text-amber-200 border border-amber-400/50"
                        onClick={() => liveRing(r, { solo: !s.solo })} />
                    </div>
                  </div>
                  <Slider label="Gain" min={0} max={1.5} step={0.01} value={s.gain} testid={`kitsune-ring${r}-gain`}
                    onChange={(v) => liveRing(r, { gain: v })} />
                  <div className="mt-1 space-y-1">
                    <Slider label="Low" min={0} max={2} step={0.01} value={s.bandGains.low} testid={`kitsune-ring${r}-band-low`}
                      onChange={(v) => liveRing(r, { bandGains: { ...s.bandGains, low: v } })} />
                    <Slider label="Mid" min={0} max={2} step={0.01} value={s.bandGains.mid} testid={`kitsune-ring${r}-band-mid`}
                      onChange={(v) => liveRing(r, { bandGains: { ...s.bandGains, mid: v } })} />
                    <Slider label="High" min={0} max={2} step={0.01} value={s.bandGains.high} testid={`kitsune-ring${r}-band-high`}
                      onChange={(v) => liveRing(r, { bandGains: { ...s.bandGains, high: v } })} />
                  </div>
                </div>
              );
            })}
          </div>

          {/* Web-Tuned Resonance */}
          <div className="rounded-lg border border-purple-500/20 bg-purple-950/20 p-3">
            <h4 className="text-xs font-bold text-purple-200 font-mono mb-2">WEB-TUNED RESONANCE <span className="text-purple-400/60">— sympathetic bank</span></h4>
            <div className="space-y-1.5">
              <Slider label="Freq Hz" min={40} max={8000} step={1} value={resonance.freq} testid="kitsune-res-freq"
                onChange={(v) => liveResonance({ freq: v })} />
              <Slider label="Q" min={0.5} max={40} step={0.1} value={resonance.q} testid="kitsune-res-q"
                onChange={(v) => liveResonance({ q: v })} />
              <Slider label="Gain" min={0} max={1.5} step={0.01} value={resonance.gain} testid="kitsune-res-gain"
                onChange={(v) => liveResonance({ gain: v })} />
            </div>
          </div>

          {/* Presets + CLYDE */}
          <div className="rounded-lg border border-purple-500/20 bg-black/60 p-3">
            <div className="flex gap-2 mb-2">
              <input value={presetName} onChange={(e) => setPresetName(e.target.value)}
                placeholder="Preset name…" data-testid="kitsune-preset-name"
                className="flex-1 bg-white/5 border border-purple-500/30 rounded px-2 py-1 text-xs text-purple-100 placeholder-purple-400/40 font-mono" />
              <button onClick={savePreset} data-testid="kitsune-preset-save"
                className="text-xs font-bold px-3 py-1 rounded bg-purple-500/20 text-purple-200 border border-purple-500/40 hover:bg-purple-500/30">
                Save field
              </button>
            </div>
            {presets.length > 0 && (
              <div className="flex flex-wrap gap-1.5">
                {presets.map((p) => (
                  <span key={p.id} className="text-[10px] font-mono px-2 py-0.5 rounded bg-purple-500/10 text-purple-300 border border-purple-500/20">
                    {p.name}
                  </span>
                ))}
              </div>
            )}
            <p className="text-[10px] text-purple-400/60 font-mono mt-2">
              CLYDE sync port: ready · spec pending — virtual HDMI sync docks here when the external spec lands.
            </p>
          </div>
        </div>
      </div>

      <p className="text-[10px] text-purple-400/50 font-mono mt-3">
        Internal Multi-Band Transducer: 3-band crossover per ring (lows &lt;250Hz · mids 250–4kHz · highs &gt;4kHz).
        R1 near-field full band · R2 gentle air lowpass · R3 lowpass + propagation delay · R4 heavy air, reverb-dominant.
        {engineOn ? ' KITSUNE live: 48 HRTF voices, click-free smoothing.' : ' Power on KITSUNE — the field starts silent; attach test tones or the HITACHI feed.'}
      </p>
    </div>
  );
}

export default KitsuneField;
