// ═══════════════════════════════════════════════════════════════════════════════
// COLOSSUS FIELD — motion-geometry video visualizer UI
// Owner canon: COLOSSUS = stateless motion-geometry compiler. Video from
// motion math, not pixel rendering. No GPU, no hardware timing.
//
// What this renders: real-time vector geometry synthesis on canvas 2D —
// motion seeds → compiled geometry → synthesized frames. Honest labeling
// throughout: this is NOT GPU rendering and NOT video encoding.
//
// Aesthetic: dark stage, vector wireframes (owner's purple-wireframe lineage).
// Camera input is strictly opt-in (button click = user gesture).
// ═══════════════════════════════════════════════════════════════════════════════

import React, { useState, useRef, useEffect, useCallback } from 'react';
import {
  createRenderer,
  createSeed,
  startCameraFeed,
  isCameraSupported,
  COLOSSUS_FIDELITY_MODES,
  COLOSSUS_SOURCE_TYPES,
} from '@/lib/colossus';
import * as unified from '@/lib/unified_sensory';

const API_URL = process.env.REACT_APP_BACKEND_URL || '';

const FIDELITY_COLORS = {
  biological: '#34d399',
  stylized: '#fbbf24',
  abstract: '#c084fc',
};

function Toggle({ label, active, onClick, testid }) {
  return (
    <button
      onClick={onClick}
      data-testid={testid}
      title={label}
      className={`px-2 py-1 rounded text-[10px] font-mono border transition-colors ${
        active
          ? 'bg-purple-600 border-purple-400 text-white'
          : 'bg-black/40 border-purple-900 text-purple-300/70 hover:text-purple-200'
      }`}
    >
      {label}
    </button>
  );
}

export function ColossusField() {
  const canvasRef = useRef(null);
  const rendererRef = useRef(null);
  const rafRef = useRef(0);
  const cameraRef = useRef(null);

  const [powered, setPowered] = useState(false);
  const [seeds, setSeeds] = useState([]);
  const [newFidelity, setNewFidelity] = useState('stylized');
  const [newSource, setNewSource] = useState('synthetic');
  const [quality, setQuality] = useState('auto');
  const [fps, setFps] = useState(0);
  const [vectors, setVectors] = useState(0);
  const [clydeState, setClydeState] = useState('free');
  const [cameraOn, setCameraOn] = useState(false);
  const [cameraError, setCameraError] = useState('');
  const [audioReactive, setAudioReactive] = useState(false);
  const [unifiedStatus, setUnifiedStatus] = useState(null);

  // Backend seed persistence (defensive — works without backend).
  const persistSeed = useCallback(async (seed) => {
    if (!API_URL) return;
    try {
      await fetch(`${API_URL}/api/colossus/seeds`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          source_type: seed.source_type,
          fidelity_mode: seed.fidelity_mode,
          params: seed.params || {},
        }),
      });
    } catch (e) { /* backend optional */ }
  }, []);

  const unpersistSeed = useCallback(async (id) => {
    if (!API_URL) return;
    try {
      await fetch(`${API_URL}/api/colossus/seeds/${encodeURIComponent(id)}`, { method: 'DELETE' });
    } catch (e) { /* backend optional */ }
  }, []);

  const addSeed = useCallback((fidelity_mode = newFidelity, source_type = newSource, persist = true) => {
    const r = rendererRef.current;
    if (!r) return null;
    const seed = createSeed({ source_type, fidelity_mode });
    r.addSeed(seed);
    setSeeds((prev) => [...prev, { ...seed, color: FIDELITY_COLORS[fidelity_mode] }]);
    if (persist) persistSeed(seed);
    return seed;
  }, [newFidelity, newSource, persistSeed]);

  const removeSeed = useCallback((id) => {
    rendererRef.current?.removeSeed(id);
    setSeeds((prev) => prev.filter((s) => s.id !== id));
    unpersistSeed(id);
  }, [unpersistSeed]);

  // Power: renderer + rAF loop. User gesture — also unlocks camera later.
  const togglePower = useCallback(async () => {
    if (powered) {
      cancelAnimationFrame(rafRef.current);
      setPowered(false);
      return;
    }
    const canvas = canvasRef.current;
    if (!canvas) return;
    if (!rendererRef.current) {
      rendererRef.current = createRenderer(canvas);
    }
    const r = rendererRef.current;
    // Seed the stage with one seed per fidelity mode on first power-on.
    if (r.seedIds().length === 0) {
      for (const mode of COLOSSUS_FIDELITY_MODES) addSeed(mode, 'synthetic', false);
    }
    setPowered(true);
    const tick = () => {
      const info = r.renderFrame();
      if (info) {
        setFps(info.fps);
        setVectors(info.vectorsDrawn);
        setClydeState(info.clyde);
      }
      rafRef.current = requestAnimationFrame(tick);
    };
    rafRef.current = requestAnimationFrame(tick);
  }, [powered, addSeed]);

  const toggleCamera = useCallback(async () => {
    if (cameraOn) {
      try { cameraRef.current?.stop(); } catch (e) { /* noop */ }
      cameraRef.current = null;
      rendererRef.current?.setCameraFeed(null);
      setCameraOn(false);
      setCameraError('');
      return;
    }
    setCameraError('');
    try {
      const feed = await startCameraFeed(); // user gesture: this click
      cameraRef.current = feed;
      rendererRef.current?.setCameraFeed(feed);
      setCameraOn(true);
    } catch (e) {
      setCameraError(e?.message || 'Camera unavailable');
    }
  }, [cameraOn]);

  const toggleAudioReactive = useCallback(async () => {
    try {
      if (!audioReactive) {
        await unified.init({ canvas: canvasRef.current });
        unified.setAudioReactive(true);
        unified.start();
      } else {
        unified.setAudioReactive(false);
      }
      setAudioReactive(!audioReactive);
      setUnifiedStatus(unified.engineStatus());
    } catch (e) { /* audio unavailable — stay visual-only */ }
  }, [audioReactive]);

  useEffect(() => {
    setUnifiedStatus(unified.engineStatus());
    const id = setInterval(() => {
      try { setUnifiedStatus(unified.engineStatus()); } catch (e) { /* noop */ }
    }, 2000);
    return () => {
      clearInterval(id);
      cancelAnimationFrame(rafRef.current);
      try { cameraRef.current?.stop(); } catch (e) { /* noop */ }
      rendererRef.current?.destroy();
      rendererRef.current = null;
      try { unified.stop(); } catch (e) { /* noop */ }
    };
    // Mount: status ticker + teardown. No reactive deps by design.
  }, []);

  useEffect(() => {
    rendererRef.current?.setQuality(quality);
  }, [quality]);

  return (
    <section
      data-testid="colossus-field"
      className="mt-8 rounded-xl border border-purple-900/60 bg-black/60 p-4"
    >
      <div className="flex items-center justify-between mb-3">
        <h3 className="text-sm font-bold text-purple-200 font-mono tracking-wide">
          🜁 COLOSSUS <span className="text-purple-400/70 font-normal">— motion-geometry video synthesis</span>
        </h3>
        <div className="flex items-center gap-2">
          <Toggle label={powered ? '⏻ ON' : '⏻ OFF'} active={powered} onClick={togglePower} testid="colossus-power" />
        </div>
      </div>

      <p className="text-[10px] text-purple-300/50 font-mono mb-3">
        Stateless vector synthesis on canvas 2D — no GPU, no video encoding. Every frame is a pure
        function of (seed, time). Timing: CLYDE virtual-HDMI [{clydeState}].
      </p>

      <canvas
        ref={canvasRef}
        width={720}
        height={405}
        data-testid="colossus-canvas"
        className="w-full rounded-lg border border-purple-900/50 bg-[#060609]"
      />

      {/* Readouts */}
      <div className="grid grid-cols-4 gap-2 mt-3 text-center">
        {[
          ['FPS', fps, 'colossus-fps'],
          ['VECTORS', vectors, 'colossus-vectors'],
          ['SEEDS', seeds.length, 'colossus-seed-count'],
          ['QUALITY', quality.toUpperCase(), 'colossus-quality-readout'],
        ].map(([label, value, testid]) => (
          <div key={label} data-testid={testid} className="rounded bg-black/50 border border-purple-900/40 py-1.5">
            <div className="text-[9px] text-purple-400/60 font-mono">{label}</div>
            <div className="text-sm text-purple-100 font-mono">{value}</div>
          </div>
        ))}
      </div>

      {/* Seed controls */}
      <div className="flex flex-wrap items-center gap-2 mt-3">
        <select
          value={newFidelity}
          onChange={(e) => setNewFidelity(e.target.value)}
          data-testid="colossus-fidelity-select"
          className="bg-black/60 border border-purple-900 text-purple-200 text-[11px] font-mono rounded px-2 py-1"
        >
          {COLOSSUS_FIDELITY_MODES.map((m) => (
            <option key={m} value={m}>{m}</option>
          ))}
        </select>
        <select
          value={newSource}
          onChange={(e) => setNewSource(e.target.value)}
          data-testid="colossus-source-select"
          className="bg-black/60 border border-purple-900 text-purple-200 text-[11px] font-mono rounded px-2 py-1"
        >
          {COLOSSUS_SOURCE_TYPES.map((s) => (
            <option key={s} value={s}>{s}</option>
          ))}
        </select>
        <Toggle label="+ SEED" active={false} onClick={() => addSeed()} testid="colossus-add-seed" />
        <select
          value={quality}
          onChange={(e) => setQuality(e.target.value)}
          data-testid="colossus-quality-select"
          className="bg-black/60 border border-purple-900 text-purple-200 text-[11px] font-mono rounded px-2 py-1"
        >
          {['auto', 'high', 'low'].map((q) => (
            <option key={q} value={q}>{q}</option>
          ))}
        </select>
        {isCameraSupported() && (
          <Toggle
            label={cameraOn ? '📷 CAM ON' : '📷 CAMERA'}
            active={cameraOn}
            onClick={toggleCamera}
            testid="colossus-camera-toggle"
          />
        )}
        <Toggle
          label={audioReactive ? '🔊 REACTIVE' : '🔊 AUDIO-REACTIVE'}
          active={audioReactive}
          onClick={toggleAudioReactive}
          testid="colossus-audio-reactive"
        />
      </div>
      {cameraError && (
        <p data-testid="colossus-camera-error" className="text-[10px] text-red-400 font-mono mt-2">{cameraError}</p>
      )}

      {/* Seed list */}
      <div className="flex flex-wrap gap-2 mt-3" data-testid="colossus-seed-list">
        {seeds.map((s) => (
          <span
            key={s.id}
            className="inline-flex items-center gap-2 px-2 py-1 rounded border text-[10px] font-mono"
            style={{ borderColor: s.color + '66', color: s.color, background: '#00000088' }}
          >
            <span className="inline-block w-2 h-2 rounded-full" style={{ background: s.color }} />
            {s.id.slice(0, 12)}… · {s.fidelity_mode} · {s.source_type}
            <button
              onClick={() => removeSeed(s.id)}
              data-testid={`colossus-remove-seed-${s.id.slice(0, 8)}`}
              className="text-purple-300/60 hover:text-red-400 ml-1"
              aria-label={`Remove seed ${s.id}`}
            >
              ✕
            </button>
          </span>
        ))}
        {seeds.length === 0 && (
          <span className="text-[10px] text-purple-300/40 font-mono">No seeds — power on to seed the stage.</span>
        )}
      </div>

      {/* Unified Sensory Engine strip */}
      <div
        data-testid="unified-sensory-strip"
        className="mt-4 rounded-lg border border-purple-900/40 bg-black/40 px-3 py-2 flex items-center gap-4 text-[10px] font-mono"
      >
        <span className="text-purple-300/80 font-bold tracking-wide">UNIFIED SENSORY</span>
        <span className="flex items-center gap-1.5 text-purple-200">
          <span className={`inline-block w-2 h-2 rounded-full ${unifiedStatus?.audio?.running ? 'bg-green-400' : 'bg-purple-900'}`} />
          KITSUNE·audio
        </span>
        <span className="flex items-center gap-1.5 text-purple-200">
          <span className={`inline-block w-2 h-2 rounded-full ${powered ? 'bg-green-400' : 'bg-purple-900'}`} />
          COLOSSUS·video
        </span>
        <span className="flex items-center gap-1.5 text-purple-200">
          <span className="inline-block w-2 h-2 rounded-full bg-amber-400" />
          CLYDE·sync <span className="text-purple-400/50">(port ready, spec pending)</span>
        </span>
        {audioReactive && <span className="text-green-300/90">⇄ audio-reactive live</span>}
      </div>
    </section>
  );
}
