/**
 * SovereignFoundation.jsx — the sovereign engine room.
 * Airport atlas grid · route+price lab · journey feed · micro-app registry
 * with spawn button.
 *
 * Endpoints: GET /health · /atlas · /journeys · /apps
 *            POST /route · /price · /journey/launch · /apps/spawn
 *            DELETE /apps/{app_id}
 */
import React, { useState } from 'react';
import { useApiGet, apiPost, apiDelete, asArray, pick } from './emporiumApi';
import { Rivets, LoadingState, EmptyState, ErrorState, Readout, Kv } from './montiff-ui';

const AIRPORTS = ['JFK', 'LHR', 'CDG', 'NRT', 'DXB', 'SIN', 'LAX', 'MIA', 'HND', 'AMS', 'SYD', 'GRU', 'JNB'];
const HUBS = ['JFK', 'LHR', 'DXB', 'SIN'];
const APP_TEMPLATES = ['Aviation Auctions', 'Pet Cruises', 'Corp Retreats'];

export default function SovereignFoundation() {
  const health = useApiGet('/api/emporium/foundation/health');
  const atlas = useApiGet('/api/emporium/foundation/atlas');
  const journeys = useApiGet('/api/emporium/foundation/journeys');
  const apps = useApiGet('/api/emporium/foundation/apps');

  // Route + price lab
  const [lab, setLab] = useState({ origin: 'JFK', destination: 'SIN', fare_class: 'ECO' });
  const [labResult, setLabResult] = useState(null);
  const [labBusy, setLabBusy] = useState(false);
  const [labError, setLabError] = useState(null);

  // Spawn
  const [template, setTemplate] = useState(APP_TEMPLATES[0]);
  const [spawnBusy, setSpawnBusy] = useState(false);
  const [spawnError, setSpawnError] = useState(null);
  const [deleting, setDeleting] = useState(null);

  // Journey launch
  const [launchBusy, setLaunchBusy] = useState(false);
  const [launchError, setLaunchError] = useState(null);
  const [launchOk, setLaunchOk] = useState(null);

  const airports = asArray(atlas.data);
  const codes = airports.length > 0
    ? airports.map((a) => String(pick(a, ['code', 'iata', 'id'], '')).toUpperCase()).filter(Boolean)
    : AIRPORTS;
  const journeyList = asArray(journeys.data);
  const appList = asArray(apps.data);
  const h = health.data || {};

  async function runLab(e) {
    e.preventDefault();
    setLabBusy(true);
    setLabError(null);
    setLabResult(null);
    const [rRoute, rPrice] = await Promise.all([
      apiPost('/api/emporium/foundation/route', lab),
      apiPost('/api/emporium/foundation/price', lab),
    ]);
    setLabBusy(false);
    if (!rRoute.ok) { setLabError(rRoute.error); return; }
    if (!rPrice.ok) { setLabError(rPrice.error); return; }
    setLabResult({ route: rRoute.data, price: rPrice.data });
  }

  async function spawnApp() {
    setSpawnBusy(true);
    setSpawnError(null);
    const r = await apiPost('/api/emporium/foundation/apps/spawn', { template });
    setSpawnBusy(false);
    if (r.ok) apps.reload();
    else setSpawnError(r.error);
  }

  async function deleteApp(appId) {
    setDeleting(appId);
    const r = await apiDelete(`/api/emporium/foundation/apps/${appId}`);
    setDeleting(null);
    if (r.ok) apps.reload();
    else setSpawnError(r.error);
  }

  async function launchJourney() {
    setLaunchBusy(true);
    setLaunchError(null);
    setLaunchOk(null);
    const r = await apiPost('/api/emporium/foundation/journey/launch', lab);
    setLaunchBusy(false);
    if (r.ok) {
      setLaunchOk(pick(r.data, ['journey_id', 'id', 'status'], 'LAUNCHED'));
      journeys.reload();
    } else {
      setLaunchError(r.error);
    }
  }

  return (
    <div className="montiff-page montiff-stack" data-testid="sovereign-foundation">
      <section className="montiff-panel-blue" data-testid="foundation-header">
        <Rivets />
        <div className="montiff-brand" style={{ color: 'var(--montiff-orange)' }}>SOVEREIGN ENGINE</div>
        <h1 className="montiff-h" style={{ color: '#fff' }}>SOVEREIGN FOUNDATION</h1>
        <div className="montiff-grid-2" style={{ gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))', marginTop: 8 }}>
          <Readout label="ENGINE" value={String(pick(h, ['status', 'engine_status'], health.loading ? '…' : '—'))} testid="foundation-health-status" />
          <Readout label="MACH BASELINE" value={String(pick(h, ['mach_baseline', 'mach'], '2.04'))} testid="foundation-health-mach" />
          <Readout label="HUBS" value={String(pick(h, ['hubs', 'hub_count'], HUBS.length))} testid="foundation-health-hubs" />
          <Readout label="ATLAS PORTS" value={String(pick(h, ['airports', 'airport_count'], codes.length))} testid="foundation-health-airports" />
        </div>
        {health.error && <div className="montiff-readout" style={{ color: 'var(--montiff-red)', marginTop: 8 }} data-testid="foundation-health-error">⚠ {health.error}</div>}
      </section>

      {/* Airport atlas */}
      <section className="montiff-panel" data-testid="foundation-atlas">
        <Rivets />
        <div className="montiff-h-sm">AIRPORT ATLAS</div>
        {atlas.loading && <LoadingState label="CHARTING THE ATLAS…" />}
        {atlas.error && <ErrorState message={atlas.error} onRetry={atlas.reload} testid="foundation-atlas-error" />}
        {!atlas.loading && !atlas.error && (
          <div className="montiff-grid" style={{ gridTemplateColumns: 'repeat(auto-fill, minmax(110px, 1fr))' }} data-testid="foundation-atlas-grid">
            {codes.map((code) => (
              <div
                key={code}
                className={`montiff-source-tile${HUBS.includes(code) ? ' selected' : ''}`}
                data-testid={`foundation-atlas-airport-${code}`}
              >
                <div className="montiff-readout" style={{ fontWeight: 700, fontSize: 18 }}>{code}</div>
                <div className="montiff-readout montiff-muted" style={{ fontSize: 10 }}>{HUBS.includes(code) ? '★ HUB' : 'PORT'}</div>
              </div>
            ))}
          </div>
        )}
      </section>

      <section className="montiff-grid-2" data-testid="foundation-lab-row">
        {/* Route + price lab */}
        <div className="montiff-panel" data-testid="foundation-lab">
          <Rivets />
          <div className="montiff-h-sm">ROUTE + PRICE LAB</div>
          <form onSubmit={runLab} data-testid="foundation-lab-form">
            <div className="montiff-form-row">
              <div className="montiff-field">
                <label className="montiff-label">ORIGIN</label>
                <select className="montiff-select" data-testid="foundation-lab-origin" value={lab.origin} onChange={(e) => setLab({ ...lab, origin: e.target.value })}>
                  {codes.map((c) => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div className="montiff-field">
                <label className="montiff-label">DESTINATION</label>
                <select className="montiff-select" data-testid="foundation-lab-destination" value={lab.destination} onChange={(e) => setLab({ ...lab, destination: e.target.value })}>
                  {codes.map((c) => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div className="montiff-field">
                <label className="montiff-label">FARE CLASS</label>
                <select className="montiff-select" data-testid="foundation-lab-fare-class" value={lab.fare_class} onChange={(e) => setLab({ ...lab, fare_class: e.target.value })}>
                  {['ECO', 'BUS', 'FIRST', 'VIP'].map((f) => <option key={f} value={f}>{f}</option>)}
                </select>
              </div>
            </div>
            <div className="montiff-row">
              <button type="submit" className="montiff-btn small" data-testid="foundation-lab-run" disabled={labBusy}>
                {labBusy ? 'COMPUTING…' : 'RUN LAB'}
              </button>
              <button type="button" className="montiff-btn small secondary" data-testid="foundation-journey-launch" onClick={launchJourney} disabled={launchBusy}>
                {launchBusy ? 'LAUNCHING…' : 'LAUNCH JOURNEY'}
              </button>
            </div>
          </form>
          {labError && <ErrorState message={labError} testid="foundation-lab-error" />}
          {launchError && <ErrorState message={launchError} testid="foundation-journey-error" />}
          {launchOk && <div className="montiff-readout" style={{ color: 'var(--montiff-green)', marginTop: 8 }} data-testid="foundation-journey-ok">✓ JOURNEY {launchOk}</div>}
          {labResult && (
            <div style={{ marginTop: 12 }} data-testid="foundation-lab-result">
              <Kv k="DISTANCE" v={pick(labResult.route, ['distance_km', 'distance'], '—')} />
              <Kv k="DURATION" v={pick(labResult.route, ['duration', 'flight_time'], '—')} />
              <Kv k="MACH" v={pick(labResult.route, ['mach', 'cruise_mach'], '—')} />
              <Kv k="BASE FARE" v={pick(labResult.price, ['base_fare', 'base'], '—')} />
              <Kv k="TOTAL" v={pick(labResult.price, ['total', 'price'], '—')} />
              <Kv k="COMMISSION" v={pick(labResult.price, ['commission'], '—')} />
            </div>
          )}
        </div>

        {/* Journey feed */}
        <div className="montiff-panel" data-testid="foundation-journeys">
          <Rivets />
          <div className="montiff-h-sm">JOURNEY FEED</div>
          {journeys.loading && <LoadingState label="TUNING THE FEED…" />}
          {journeys.error && <ErrorState message={journeys.error} onRetry={journeys.reload} testid="foundation-journeys-error" />}
          {!journeys.loading && !journeys.error && journeyList.length === 0 && (
            <EmptyState label="NO JOURNEYS EMITTED YET" testid="foundation-journeys-empty" />
          )}
          {!journeys.loading && !journeys.error && journeyList.length > 0 && (
            <div className="montiff-stack" style={{ gap: 8 }} data-testid="foundation-journeys-list">
              {journeyList.slice(0, 12).map((j, i) => (
                <div className="montiff-kanban-card" key={pick(j, ['id', 'journey_id'], i)} data-testid={`foundation-journey-${i}`}>
                  <div className="montiff-readout" style={{ fontWeight: 700, fontSize: 13 }}>
                    {pick(j, ['origin', 'from'], '?')} → {pick(j, ['destination', 'to'], '?')}
                    <span className="montiff-chip blue" style={{ marginLeft: 8 }}>{pick(j, ['status', 'state'], '—')}</span>
                  </div>
                  <div className="montiff-readout montiff-muted" style={{ fontSize: 11 }}>
                    {pick(j, ['created_at', 'timestamp'], '')} · {pick(j, ['fare_class', 'class'], '')}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </section>

      {/* Micro-app registry */}
      <section className="montiff-panel" data-testid="foundation-apps">
        <Rivets />
        <div className="montiff-h-sm">MICRO-APP REGISTRY</div>
        <div className="montiff-row" style={{ marginBottom: 14 }} data-testid="foundation-spawn-row">
          <select className="montiff-select" data-testid="foundation-spawn-template" value={template} onChange={(e) => setTemplate(e.target.value)} style={{ maxWidth: 260 }}>
            {APP_TEMPLATES.map((t) => <option key={t} value={t}>{t}</option>)}
          </select>
          <button className="montiff-btn small" data-testid="foundation-spawn-button" onClick={spawnApp} disabled={spawnBusy}>
            {spawnBusy ? 'SPAWNING…' : '⚡ SPAWN APP'}
          </button>
        </div>
        {spawnError && <ErrorState message={spawnError} testid="foundation-spawn-error" />}
        {apps.loading && <LoadingState label="READING APP REGISTRY…" />}
        {apps.error && <ErrorState message={apps.error} onRetry={apps.reload} testid="foundation-apps-error" />}
        {!apps.loading && !apps.error && appList.length === 0 && (
          <EmptyState label="REGISTRY EMPTY — SPAWN THE FIRST MICRO-APP" testid="foundation-apps-empty" />
        )}
        {!apps.loading && !apps.error && appList.length > 0 && (
          <div className="montiff-grid" data-testid="foundation-apps-grid">
            {appList.map((a, i) => {
              const id = String(pick(a, ['app_id', 'id'], i));
              return (
                <div className="montiff-card" key={id} data-testid={`foundation-app-${i}`}>
                  <div className="montiff-h-sm" style={{ margin: 0 }}>{pick(a, ['name', 'template', 'title'], `APP ${i + 1}`)}</div>
                  <div>
                    <Kv k="STATUS" v={pick(a, ['status', 'state'], '—')} />
                    <Kv k="SPAWNED" v={pick(a, ['created_at', 'spawned_at'], '—')} />
                  </div>
                  <button
                    className="montiff-btn small ghost"
                    data-testid={`foundation-app-delete-${i}`}
                    disabled={deleting === id}
                    onClick={() => deleteApp(id)}
                    style={{ marginTop: 'auto' }}
                  >
                    {deleting === id ? '…' : 'DECOMMISSION'}
                  </button>
                </div>
              );
            })}
          </div>
        )}
      </section>
    </div>
  );
}
