/**
 * EmporiumVendors.jsx — vendor console (3 exports).
 *  EmporiumVendors (default)  overview + category links + pipeline snapshot
 *  EmporiumVendorCategory      /vendors/:category — filter + vendor list + Flip to Live
 *  EmporiumVendorDossier       /vendors/:category/:vendorId — full dossier
 *
 * Endpoints: GET /overview · /schema/{cat} · /{cat} · /vendor/{id} · /pipeline/board
 *            PATCH /vendor/{id} (pipeline_state · live_mode · credentials …)
 */
import React, { useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import { useApiGet, apiPatch, asArray, pick } from './emporiumApi';
import { Rivets, LoadingState, EmptyState, ErrorState, Kv } from './montiff-ui';

export const VENDOR_CATEGORIES = ['airlines', 'hotels', 'cruises', 'cars', 'events'];

function stateChip(state) {
  const s = String(state || 'LEAD').toUpperCase();
  const cls = s === 'LIVE' ? 'green' : s === 'SIGNED' ? 'blue' : s === 'NEGOTIATING' ? 'yellow' : s === 'CONTACTED' ? 'active' : '';
  return <span className={`montiff-chip ${cls}`} data-testid={`vendor-state-${s.toLowerCase()}`}>{s}</span>;
}

function VendorCard({ vendor, category, index, onToggleLive, toggling }) {
  const id = pick(vendor, ['id', 'vendor_id'], index);
  const name = pick(vendor, ['name', 'title'], `VENDOR ${index + 1}`);
  const live = vendor.live_mode === true || String(vendor.status || '').toUpperCase() === 'LIVE';
  return (
    <div className="montiff-card" data-testid={`vendor-card-${index}`}>
      <div className="montiff-row" style={{ justifyContent: 'space-between' }}>
        <div className="montiff-h-sm" style={{ margin: 0 }}>{name}</div>
        {stateChip(pick(vendor, ['pipeline_state', 'state', 'status'], 'LEAD'))}
      </div>
      <div>
        <Kv k="CATEGORY" v={pick(vendor, ['category'], category)} />
        <Kv k="COMMISSION" v={pick(vendor, ['commission', 'commission_rate', 'commission_structure'], '—')} />
        <Kv k="CREDENTIALS" v={pick(vendor, ['credentials', 'credential_status'], '—')} />
      </div>
      <div className="montiff-row" style={{ marginTop: 'auto' }}>
        <label className={`montiff-toggle${live ? ' on' : ''}`} data-testid={`vendor-live-toggle-${index}`}>
          <input
            type="checkbox"
            checked={!!live}
            disabled={toggling}
            onChange={(e) => onToggleLive(vendor, e.target.checked)}
            aria-label={`Flip ${name} to ${live ? 'mock' : 'live'}`}
            style={{ position: 'absolute', opacity: 0, pointerEvents: 'none' }}
          />
          <span className="montiff-toggle-track"><span className="montiff-toggle-knob" /></span>
          <span className="montiff-readout" style={{ fontSize: 12, fontWeight: 700 }}>
            {live ? 'LIVE FEED' : 'FLIP TO LIVE'}
          </span>
        </label>
        <Link
          className="montiff-btn small ghost"
          data-testid={`vendor-dossier-link-${index}`}
          to={`/emporium/vendors/${category}/${id}`}
          style={{ marginLeft: 'auto' }}
        >
          DOSSIER
        </Link>
      </div>
    </div>
  );
}

function useFlipToLive(reload) {
  const [toggling, setToggling] = useState(null);
  const [flipError, setFlipError] = useState(null);
  async function flip(vendor, toLive) {
    const id = pick(vendor, ['id', 'vendor_id'], null);
    if (!id) return;
    setToggling(id);
    setFlipError(null);
    const r = await apiPatch(`/api/emporium/vendors/vendor/${id}`, { live_mode: toLive });
    setToggling(null);
    if (r.ok) reload();
    else setFlipError(r.error);
  }
  return { toggling, flipError, flip };
}

/* ── Default export: console overview ─────────────────────── */
export default function EmporiumVendors() {
  const overview = useApiGet('/api/emporium/vendors/overview');
  const board = useApiGet('/api/emporium/vendors/pipeline/board');
  const o = overview.data || {};

  const counts = pick(o, ['by_category', 'categories', 'counts'], null);
  const total = pick(o, ['total_vendors', 'total', 'vendor_count'], '—');

  return (
    <div className="montiff-page montiff-stack" data-testid="emporium-vendors">
      <section className="montiff-panel" data-testid="vendors-console-header">
        <Rivets />
        <div className="montiff-brand" style={{ color: 'var(--montiff-cobalt)' }}>VENDOR CONSOLE</div>
        <h1 className="montiff-h">FIVE LANES, ONE COUNTER</h1>
        <div className="montiff-row">
          {VENDOR_CATEGORIES.map((c) => (
            <Link key={c} className="montiff-btn small secondary" data-testid={`vendors-category-link-${c}`} to={`/emporium/vendors/${c}`}>
              {c.toUpperCase()}
            </Link>
          ))}
        </div>
      </section>

      {overview.loading && <LoadingState label="TALLYING VENDOR LANES…" />}
      {overview.error && <ErrorState message={overview.error} onRetry={overview.reload} testid="vendors-overview-error" />}
      {!overview.loading && !overview.error && (
        <section className="montiff-grid" data-testid="vendors-overview-grid">
          <div className="montiff-panel" data-testid="vendors-overview-total">
            <Rivets />
            <div className="montiff-h-sm">TOTAL VENDORS</div>
            <div className="montiff-readout" style={{ fontSize: 40, fontWeight: 700 }}>{total}</div>
          </div>
          {counts && typeof counts === 'object' && Object.entries(counts).map(([cat, n]) => (
            <Link key={cat} to={`/emporium/vendors/${cat}`} data-testid={`vendors-overview-${cat}`} style={{ textDecoration: 'none', color: 'inherit' }}>
              <div className="montiff-source-tile">
                <div className="montiff-h-sm" style={{ margin: 0 }}>{String(cat).toUpperCase()}</div>
                <div className="montiff-readout" style={{ fontSize: 30, fontWeight: 700 }}>{n}</div>
              </div>
            </Link>
          ))}
        </section>
      )}

      <section className="montiff-panel" data-testid="vendors-pipeline-snapshot">
        <Rivets />
        <div className="montiff-h-sm">PIPELINE SNAPSHOT</div>
        {board.loading && <LoadingState label="READING PIPELINE BOARD…" />}
        {board.error && <ErrorState message={board.error} onRetry={board.reload} />}
        {!board.loading && !board.error && (
          <PipelineBoard board={board.data} compact />
        )}
        <div style={{ marginTop: 12 }}>
          <Link className="montiff-btn small" data-testid="vendors-open-claudette" to="/emporium/claudette">
            OPEN CLAUDETTE COCKPIT →
          </Link>
        </div>
      </section>
    </div>
  );
}

/* ── Category list ────────────────────────────────────────── */
export function EmporiumVendorCategory() {
  const { category } = useParams();
  const cat = (category || '').toLowerCase();
  const { data, loading, error, reload } = useApiGet(`/api/emporium/vendors/${cat}`, [cat]);
  const vendors = asArray(data);
  const { toggling, flipError, flip } = useFlipToLive(reload);

  return (
    <div className="montiff-page montiff-stack" data-testid="emporium-vendor-category">
      <Link className="montiff-btn small ghost" data-testid="vendor-category-back-link" to="/emporium/vendors">← VENDOR CONSOLE</Link>
      <section className="montiff-panel" data-testid="vendor-category-header">
        <Rivets />
        <div className="montiff-brand" style={{ color: 'var(--montiff-cobalt)' }}>VENDOR LANE</div>
        <h1 className="montiff-h">{cat.toUpperCase()}</h1>
        <div className="montiff-tabs" data-testid="vendor-category-filter" role="tablist" aria-label="Vendor categories">
          {VENDOR_CATEGORIES.map((c) => (
            <Link
              key={c}
              to={`/emporium/vendors/${c}`}
              role="tab"
              aria-selected={c === cat}
              data-testid={`vendor-category-filter-${c}`}
              className={`montiff-tab${c === cat ? ' active' : ''}`}
            >
              {c.toUpperCase()}
            </Link>
          ))}
        </div>
      </section>

      {loading && <LoadingState label={`RAIDING THE ${cat.toUpperCase()} LANE…`} />}
      {error && <ErrorState message={error} onRetry={reload} testid="vendor-category-error" />}
      {!loading && !error && vendors.length === 0 && (
        <EmptyState label={`NO ${cat.toUpperCase()} VENDORS ONBOARD YET`} testid="vendor-category-empty" />
      )}
      {!loading && !error && vendors.length > 0 && (
        <div className="montiff-grid" data-testid="vendor-category-grid">
          {vendors.map((v, i) => (
            <VendorCard key={pick(v, ['id', 'vendor_id'], i)} vendor={v} category={cat} index={i} onToggleLive={flip} toggling={toggling} />
          ))}
        </div>
      )}
      {flipError && <ErrorState message={flipError} testid="vendor-flip-error" />}
    </div>
  );
}

/* ── Dossier ──────────────────────────────────────────────── */
export function EmporiumVendorDossier() {
  const { category, vendorId } = useParams();
  const { data, loading, error, reload } = useApiGet(`/api/emporium/vendors/vendor/${vendorId}`, [vendorId]);
  const v = data && typeof data === 'object' && !Array.isArray(data) ? data : {};
  const notes = asArray(v.notes || v.note_stream);

  return (
    <div className="montiff-page montiff-stack" data-testid="emporium-vendor-dossier">
      <Link className="montiff-btn small ghost" data-testid="vendor-dossier-back-link" to={`/emporium/vendors/${category}`}>← {String(category).toUpperCase()} LANE</Link>

      {loading && <LoadingState label="PULLING VENDOR DOSSIER…" />}
      {error && <ErrorState message={error} onRetry={reload} testid="vendor-dossier-error" />}
      {!loading && !error && (
        <>
          <section className="montiff-panel" data-testid="vendor-dossier-panel">
            <Rivets />
            <div className="montiff-row" style={{ justifyContent: 'space-between' }}>
              <div>
                <div className="montiff-brand" style={{ color: 'var(--montiff-cobalt)' }}>VENDOR DOSSIER</div>
                <h1 className="montiff-h">{pick(v, ['name', 'title'], `VENDOR ${vendorId}`)}</h1>
              </div>
              {stateChip(pick(v, ['pipeline_state', 'state', 'status'], 'LEAD'))}
            </div>
            <div className="montiff-grid-2">
              <div>
                <Kv k="CATEGORY" v={pick(v, ['category'], category)} />
                <Kv k="CONTACT" v={pick(v, ['contact', 'contact_name'], '—')} />
                <Kv k="IATA / ARC / CLIA" v={pick(v, ['iata', 'arc', 'clia', 'accreditation'], '—')} />
                <Kv k="CREDENTIALS" v={pick(v, ['credentials', 'credential_status'], '—')} />
              </div>
              <div>
                <Kv k="COMMISSION" v={pick(v, ['commission', 'commission_structure', 'commission_rate'], '—')} />
                <Kv k="CAPABILITIES" v={Array.isArray(v.capabilities) ? v.capabilities.join(', ') : pick(v, ['capabilities'], '—')} />
                <Kv k="LIVE MODE" v={v.live_mode ? 'ON — REAL FEED' : 'OFF — MOCK'} />
                <Kv k="OWNER" v={pick(v, ['owner', 'assignee', 'rep'], 'Claudette (SST-CLAUDETTE)')} />
              </div>
            </div>
            {pick(v, ['notes', 'description'], '') !== '' && typeof pick(v, ['notes'], '') === 'string' && (
              <p style={{ marginTop: 12 }}>{v.notes}</p>
            )}
          </section>

          <section className="montiff-panel-flat" data-testid="vendor-dossier-notes">
            <div className="montiff-h-sm">NOTE STREAM</div>
            {notes.length === 0 ? (
              <EmptyState label="NO NOTES FILED — ADD SOME FROM THE CLAUDETTE COCKPIT" testid="vendor-dossier-notes-empty" />
            ) : (
              <div className="montiff-stack" style={{ gap: 10 }}>
                {notes.map((n, i) => (
                  <div className="montiff-kanban-card" key={i} data-testid={`vendor-dossier-note-${i}`}>
                    <div className="montiff-readout" style={{ fontSize: 12, color: 'var(--montiff-steel-600)' }}>
                      {pick(n, ['created_at', 'timestamp', 'date'], '')} · {pick(n, ['author', 'by'], 'Claudette')}
                    </div>
                    <div style={{ fontSize: 14 }}>{typeof n === 'string' ? n : pick(n, ['note', 'text', 'body'], '')}</div>
                  </div>
                ))}
              </div>
            )}
          </section>
        </>
      )}
    </div>
  );
}

/* ── Shared pipeline board renderer ───────────────────────── */
const PIPELINE_STATES = ['LEAD', 'CONTACTED', 'NEGOTIATING', 'SIGNED', 'LIVE'];

export function PipelineBoard({ board, compact = false }) {
  const columns = normalizeBoard(board);
  return (
    <div className="montiff-kanban" data-testid="pipeline-board">
      {PIPELINE_STATES.map((state) => {
        const cards = columns[state] || [];
        return (
          <div className="montiff-kanban-col" key={state} data-testid={`pipeline-column-${state.toLowerCase()}`}>
            <div className="montiff-kanban-head">
              <span>{state}</span>
              <span className="montiff-readout">{cards.length}</span>
            </div>
            <div className="montiff-kanban-body">
              {cards.length === 0 && (
                <div className="montiff-readout montiff-muted" style={{ fontSize: 12 }} data-testid={`pipeline-column-empty-${state.toLowerCase()}`}>
                  {compact ? '—' : 'No vendors parked here.'}
                </div>
              )}
              {cards.map((v, i) => (
                <div className="montiff-kanban-card" key={pick(v, ['id', 'vendor_id'], i)} data-testid={`pipeline-card-${state.toLowerCase()}-${i}`}>
                  <div style={{ fontWeight: 700, fontSize: 14 }}>{pick(v, ['name', 'title'], `VENDOR ${i + 1}`)}</div>
                  <div className="montiff-readout montiff-muted" style={{ fontSize: 11 }}>
                    {pick(v, ['category'], '')} {v.live_mode ? '· LIVE FEED' : ''}
                  </div>
                </div>
              ))}
            </div>
          </div>
        );
      })}
    </div>
  );
}

function normalizeBoard(board) {
  const cols = { LEAD: [], CONTACTED: [], NEGOTIATING: [], SIGNED: [], LIVE: [] };
  if (!board) return cols;
  // Shape A: { columns: { LEAD: [...] } } or { board: {...} }
  const src = board.columns || board.board || board.states || null;
  if (src && typeof src === 'object') {
    for (const s of PIPELINE_STATES) {
      const arr = src[s] || src[s.toLowerCase()];
      if (Array.isArray(arr)) cols[s] = arr;
    }
    return cols;
  }
  // Shape B: flat vendor list with pipeline_state
  const list = asArray(board, ['vendors', 'items', 'results', 'data']);
  for (const v of list) {
    const s = String(pick(v, ['pipeline_state', 'state', 'status'], 'LEAD')).toUpperCase();
    (cols[s] || cols.LEAD).push(v);
  }
  return cols;
}
