// ═══════════════════════════════════════════════════════════════════════════════
// CLYDE SYNC CONSOLE — virtual HDMI synchronization UI
// Owner canon: CLYDE = "Crystallized Loop Yarn Desolation Emergence", the
// virtual-HDMI sync spine. Phone as master clock (browser's best clock).
//
// Honest labeling throughout: the HDMI profile is a SOFTWARE TIMING MODEL —
// browsers cannot access real EDID hardware or emit real HDMI. The console
// says so wherever timing parameters appear.
// ═══════════════════════════════════════════════════════════════════════════════

import React, { useState, useEffect, useCallback, useRef } from 'react';
import {
  init as clydeInit,
  shutdown as clydeShutdown,
  isRunning,
  now as clydeNow,
  getPhases,
  getMetrics,
  getSessions,
  setTarget,
  getTarget,
  setAvOffsetMs,
  getAvOffsetMs,
  setHdmiProfile,
  getHdmiProfile,
  virtualHandshake,
  closeSession,
  scheduleAt,
  engineStatus,
  CLYDE_PHASES,
  CLYDE_TARGETS,
  // Session-Negotiated Timing Contract (Option 2, Variation 3)
  negotiateTiming,
  sealTimeline,
  ignitePulse,
  heartbeat,
  softRenew,
  getTimeline,
  getUptime,
  formatContractUptime,
  senseRupture,
  renegotiate,
  realignEngines,
  resumeTimeline,
  reportStall,
} from '@/lib/clyde';

const PHASE_DESCRIPTIONS = {
  Crystallized: 'Clock conditioning — jitter measured, smoothed, drift tracked',
  Loop: 'Closed feedback — callback error feeds the next schedule',
  Yarn: 'Unified scheduler — one timeline for audio + video callbacks',
  Desolation: 'Hardware independence — pure software clock, headless-capable',
  Emergence: 'Adaptive behavior — watches timing health, adapts the scheduler',
};

const HEALTH_COLORS = {
  EXCELLENT: 'text-emerald-400 border-emerald-500',
  GOOD: 'text-amber-300 border-amber-500',
  STRAINED: 'text-red-400 border-red-500',
};

const PHASE_KEYS = ['Crystallized', 'Loop', 'Yarn', 'Desolation', 'Emergence'];

function PhaseCard({ name, state }) {
  const active = state?.active;
  return (
    <div
      data-testid={`clyde-phase-${name.toLowerCase()}`}
      className={`rounded-lg border p-3 bg-black/50 transition-colors ${active ? 'border-cyan-500/70' : 'border-gray-800'}`}
    >
      <div className="flex items-center gap-2 mb-1">
        <span
          className={`inline-block w-2 h-2 rounded-full ${active ? 'bg-cyan-400 shadow-[0_0_6px_#22d3ee]' : 'bg-gray-700'}`}
        />
        <span className="text-xs font-mono font-bold text-cyan-200 tracking-wider">{name.toUpperCase()}</span>
      </div>
      <p className="text-[10px] text-gray-500 mb-2 leading-snug">{PHASE_DESCRIPTIONS[name]}</p>
      <PhaseDetails name={name} state={state} />
    </div>
  );
}

function PhaseDetails({ name, state }) {
  if (!state) return <span className="text-[10px] font-mono text-gray-600">standby</span>;
  const kv = (k, v) => (
    <div key={k} className="flex justify-between text-[10px] font-mono">
      <span className="text-gray-500">{k}</span>
      <span className="text-gray-200">{v}</span>
    </div>
  );
  switch (name) {
    case 'Crystallized':
      return <>{kv('jitter', `${state.jitterMs} ms`)}{kv('drift', `${state.driftMs} ms`)}{kv('window', `${state.windowSize} ticks`)}</>;
    case 'Loop':
      return <>{kv('last error', `${state.lastErrorMs} ms`)}{kv('correction', `${state.correctionMs} ms`)}{kv('corrections', state.corrections)}</>;
    case 'Yarn':
      return <>{kv('pending audio', state.pendingAudio)}{kv('pending video', state.pendingVideo)}{kv('fired', state.firedTotal)}{kv('missed', state.missedDeadlines)}</>;
    case 'Desolation':
      return <>{kv('hardware-free', 'yes')}{kv('clock', state.clockSource?.includes('AudioContext') ? 'AudioContext' : 'performance.now()')}{kv('vsync assumed', 'no')}</>;
    case 'Emergence':
      return (
        <>
          {kv('health', state.health)}
          <div className="text-[10px] font-mono text-gray-500 mt-1">adaptations: {state.adaptationCount}</div>
          {state.adaptations?.slice(-2).map((a, i) => (
            <div key={i} className="text-[10px] font-mono text-amber-300/80 truncate" title={a.detail ? JSON.stringify(a.detail) : ''}>
              → {a.action}
            </div>
          ))}
        </>
      );
    default:
      return null;
  }
}

export function ClydeSync() {
  const [running, setRunning] = useState(false);
  const [status, setStatus] = useState(null);
  const [phases, setPhases] = useState(null);
  const [metrics, setMetrics] = useState(null);
  const [sessions, setSessions] = useState([]);
  const [target, setTargetState] = useState(getTarget());
  const [avOffset, setAvOffset] = useState(getAvOffsetMs());
  const [profileName, setProfileName] = useState('1080p60');
  const [profile, setProfile] = useState(getHdmiProfile());
  const [consumer, setConsumer] = useState('DAW-Console');
  const [clock, setClock] = useState(0);
  const pollRef = useRef(0);
  const beatRef = useRef(0);
  // ── Contract lifecycle (Option 2, Variation 3) ──
  const [timelineId, setTimelineId] = useState(null);
  const [contract, setContract] = useState(null);
  const [lastBeat, setLastBeat] = useState(null);
  const [negForm, setNegForm] = useState({ frameRates: '60', granularityMs: '16.67', useAudioClock: true });

  const refreshContract = useCallback((tid) => {
    if (!tid) { setContract(null); return; }
    try {
      // Self-healing: sense rupture on every poll; run the recovery chain.
      const sensed = senseRupture(tid);
      if (sensed.ruptured) {
        renegotiate(tid, sensed.trigger);
        realignEngines(tid);
        resumeTimeline(tid);
      }
      setContract(getTimeline(tid));
    } catch (err) { /* timeline gone — leave last state */ }
  }, []);

  const sealNewTimeline = useCallback((overrides = {}) => {
    const rates = String(negForm.frameRates).split(',').map((s) => Number(s.trim())).filter((n) => Number.isFinite(n) && n > 0);
    const neg = negotiateTiming({
      frameRates: rates.length ? rates : [60],
      granularityMs: Number(negForm.granularityMs) || 1000 / 60,
      useAudioClock: !!negForm.useAudioClock,
      hdmiProfile: profileName,
      target,
      ...overrides,
    });
    const base = sealTimeline(neg);
    ignitePulse(base.timelineId);
    setTimelineId(base.timelineId);
    refreshContract(base.timelineId);
    return base.timelineId;
  }, [negForm, profileName, target, refreshContract]);

  const refresh = useCallback(() => {
    if (!isRunning()) return;
    setStatus(engineStatus());
    setPhases(getPhases());
    setMetrics(getMetrics());
    setSessions(getSessions());
    setClock(clydeNow());
    if (timelineId) refreshContract(timelineId);
  }, [timelineId, refreshContract]);

  useEffect(() => {
    if (running) {
      refresh();
      pollRef.current = setInterval(refresh, 500);
      // Active Contract heartbeat: cheap liveness ping every 2 s.
      beatRef.current = setInterval(() => {
        if (timelineId) {
          try { setLastBeat(heartbeat(timelineId)); } catch (err) { /* not active — recovery handles */ }
        }
      }, 2000);
    }
    return () => {
      if (pollRef.current) clearInterval(pollRef.current);
      if (beatRef.current) clearInterval(beatRef.current);
    };
  }, [running, refresh, timelineId]);

  const power = () => {
    if (running) {
      clydeShutdown();
      setRunning(false);
      setStatus(null); setPhases(null); setMetrics(null); setSessions([]);
      setTimelineId(null); setContract(null);
    } else {
      // User gesture: a real AudioContext becomes the sample-accurate master.
      let ac = null;
      try {
        const AC = window.AudioContext || window.webkitAudioContext;
        if (AC) ac = new AC();
      } catch (err) { /* software clock fallback */ }
      clydeInit({ audioContext: ac });
      setRunning(true);
      try {
        const neg = negotiateTiming({
          frameRates: [60],
          granularityMs: 1000 / 60,
          useAudioClock: !!ac,
          hdmiProfile: profileName,
          target,
        });
        const base = sealTimeline(neg);
        ignitePulse(base.timelineId);
        setTimelineId(base.timelineId);
      } catch (err) { /* contract failure never breaks power-on */ }
      refresh();
    }
  };

  const changeTarget = (t) => { setTarget(t); setTargetState(t); refresh(); };
  const changeOffset = (ms) => { setAvOffset(ms); setAvOffsetMs(ms); };
  const changeProfile = (name) => { setProfileName(name); setProfile(setHdmiProfile(name)); refresh(); };
  const handshake = () => { virtualHandshake(consumer || 'DAW-Console'); refresh(); };
  const dropSession = (id) => { closeSession(id); refresh(); };
  const pingTest = () => {
    // Fires one audio + one video callback on the unified timeline to prove
    // Yarn phase alignment end-to-end.
    const t = clydeNow() + 0.1;
    scheduleAt(t, () => {}, 'audio');
    scheduleAt(t, () => {}, 'video');
    setTimeout(refresh, 300);
  };

  const health = metrics?.health || '—';
  const healthCls = HEALTH_COLORS[health] || 'text-gray-400 border-gray-700';

  return (
    <div data-testid="clyde-console" className="mt-6 bg-black/40 rounded-xl border border-gray-800 p-6">
      <div className="flex items-center justify-between mb-1 flex-wrap gap-2">
        <div>
          <h3 className="text-sm font-mono font-bold text-cyan-200 tracking-widest">CLYDE — SYNC SPINE</h3>
          <p className="text-[10px] text-gray-500 font-mono">Crystallized Loop Yarn Desolation Emergence · virtual HDMI timing (software model)</p>
        </div>
        <div className="flex items-center gap-2">
          <span data-testid="clyde-health" className={`text-[10px] font-mono px-2 py-1 rounded border ${healthCls}`}>
            {health}
          </span>
          <button
            data-testid="clyde-power"
            onClick={power}
            className={`px-3 py-1 rounded text-[11px] font-mono border transition-colors ${running ? 'border-red-500 text-red-300 hover:bg-red-950' : 'border-cyan-500 text-cyan-200 hover:bg-cyan-950'}`}
          >
            {running ? '■ STOP' : '▶ START'}
          </button>
        </div>
      </div>

      {/* Five phases */}
      <div className="grid grid-cols-2 md:grid-cols-5 gap-2 mt-3">
        {PHASE_KEYS.map((p) => (
          <PhaseCard key={p} name={p} state={phases?.[p]} />
        ))}
      </div>

      {/* Controls */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-3 mt-4">
        <div className="rounded-lg border border-gray-800 bg-black/50 p-3">
          <div className="text-[10px] font-mono text-gray-500 mb-2">SYNC TARGET</div>
          <div className="flex gap-1">
            {CLYDE_TARGETS.map((t) => (
              <button
                key={t}
                data-testid={`clyde-target-${t}`}
                onClick={() => changeTarget(t)}
                className={`flex-1 px-2 py-1 rounded text-[10px] font-mono border transition-colors ${target === t ? 'border-cyan-500 text-cyan-200 bg-cyan-950/50' : 'border-gray-700 text-gray-400 hover:border-gray-500'}`}
              >
                {t}
              </button>
            ))}
          </div>
          <div className="text-[10px] font-mono text-gray-600 mt-2 leading-snug">
            monitor: display-paced · headset: audio-clock · internal: pure software
          </div>
        </div>

        <div className="rounded-lg border border-gray-800 bg-black/50 p-3">
          <div className="text-[10px] font-mono text-gray-500 mb-2">VIRTUAL HDMI PROFILE <span className="text-gray-600">(software model — not real EDID)</span></div>
          <div className="flex gap-1 mb-2">
            {['1080p60', '4K60', '720p60'].map((p) => (
              <button
                key={p}
                data-testid={`clyde-profile-${p}`}
                onClick={() => changeProfile(p)}
                className={`flex-1 px-2 py-1 rounded text-[10px] font-mono border transition-colors ${profileName === p ? 'border-cyan-500 text-cyan-200 bg-cyan-950/50' : 'border-gray-700 text-gray-400 hover:border-gray-500'}`}
              >
                {p}
              </button>
            ))}
          </div>
          <div className="text-[10px] font-mono text-gray-400" data-testid="clyde-profile-readout">
            {profile.width}×{profile.height} · {profile.refreshHz.toFixed(2)} Hz · {profile.pixelClockMHz} MHz pixel clock
          </div>
        </div>

        <div className="rounded-lg border border-gray-800 bg-black/50 p-3">
          <div className="text-[10px] font-mono text-gray-500 mb-2">A/V OFFSET <span className="text-cyan-300">{avOffset} ms</span></div>
          <input
            data-testid="clyde-av-offset"
            type="range"
            min={-500}
            max={500}
            step={5}
            value={avOffset}
            onChange={(e) => changeOffset(Number(e.target.value))}
            className="w-full accent-cyan-400"
          />
          <div className="text-[10px] font-mono text-gray-600 mt-1">lip-sync · + delays audio vs video</div>
          <button
            data-testid="clyde-ping"
            onClick={pingTest}
            disabled={!running}
            className="mt-2 px-2 py-1 rounded text-[10px] font-mono border border-gray-700 text-gray-300 hover:border-cyan-500 disabled:opacity-40"
          >
            ◉ ping A/V callbacks
          </button>
        </div>

        <div className="rounded-lg border border-gray-800 bg-black/50 p-3">
          <div className="text-[10px] font-mono text-gray-500 mb-2">VIRTUAL CABLE HANDSHAKE</div>
          <div className="flex gap-1">
            <input
              data-testid="clyde-consumer-input"
              value={consumer}
              onChange={(e) => setConsumer(e.target.value)}
              placeholder="consumer name"
              className="flex-1 min-w-0 bg-black border border-gray-700 rounded px-2 py-1 text-[10px] font-mono text-gray-200"
            />
            <button
              data-testid="clyde-handshake"
              onClick={handshake}
              disabled={!running}
              className="px-2 py-1 rounded text-[10px] font-mono border border-gray-700 text-gray-300 hover:border-cyan-500 disabled:opacity-40"
            >
              shake
            </button>
          </div>
          <div className="mt-2 space-y-1 max-h-20 overflow-y-auto">
            {sessions.length === 0 && <div className="text-[10px] font-mono text-gray-600">no sessions</div>}
            {sessions.map((s) => (
              <div key={s.sessionId} data-testid="clyde-session" className="flex items-center justify-between text-[10px] font-mono">
                <span className="text-gray-300 truncate">{s.sessionId} <span className="text-gray-600">· {s.consumer}</span></span>
                <button data-testid={`clyde-session-close-${s.sessionId}`} onClick={() => dropSession(s.sessionId)} className="text-gray-600 hover:text-red-400 ml-2">✕</button>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* ── Session-Negotiated Timing Contract (Option 2, Variation 3) ── */}
      <div className="mt-4">
        <div className="text-[10px] font-mono text-gray-500 tracking-widest mb-2">
          TIMING CONTRACT <span className="text-gray-600">· base → active → recovery · Option 2, Variation 3</span>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
          {/* BASE — handshake layer */}
          <div data-testid="clyde-contract-base" className="rounded-lg border border-gray-800 bg-black/50 p-3">
            <div className="text-[10px] font-mono text-cyan-300 mb-2 tracking-wider">① BASE · HANDSHAKE</div>
            <div className="space-y-2">
              <label className="flex justify-between items-center text-[10px] font-mono text-gray-500">
                frame rates
                <input
                  data-testid="clyde-contract-framerates"
                  value={negForm.frameRates}
                  onChange={(e) => setNegForm({ ...negForm, frameRates: e.target.value })}
                  className="w-24 bg-black border border-gray-700 rounded px-2 py-1 text-[10px] font-mono text-gray-200 text-right"
                />
              </label>
              <label className="flex justify-between items-center text-[10px] font-mono text-gray-500">
                granularity ms
                <input
                  data-testid="clyde-contract-granularity"
                  value={negForm.granularityMs}
                  onChange={(e) => setNegForm({ ...negForm, granularityMs: e.target.value })}
                  className="w-24 bg-black border border-gray-700 rounded px-2 py-1 text-[10px] font-mono text-gray-200 text-right"
                />
              </label>
              <label className="flex justify-between items-center text-[10px] font-mono text-gray-500">
                audio clock master
                <input
                  data-testid="clyde-contract-audioclock"
                  type="checkbox"
                  checked={!!negForm.useAudioClock}
                  onChange={(e) => setNegForm({ ...negForm, useAudioClock: e.target.checked })}
                  className="accent-cyan-400"
                />
              </label>
              <button
                data-testid="clyde-contract-seal"
                onClick={() => sealNewTimeline()}
                disabled={!running}
                className="w-full px-2 py-1 rounded text-[10px] font-mono border border-cyan-700 text-cyan-200 hover:bg-cyan-950 disabled:opacity-40"
              >
                ✦ negotiate + seal timeline
              </button>
            </div>
            <div className="mt-2 space-y-1 text-[10px] font-mono">
              <div className="flex justify-between"><span className="text-gray-500">timeline</span><span data-testid="clyde-contract-timeline" className="text-gray-200">{contract?.timelineId || '—'}</span></div>
              <div className="flex justify-between"><span className="text-gray-500">sync mode</span><span data-testid="clyde-contract-syncmode" className="text-cyan-300">{contract?.base?.syncMode || '—'}</span></div>
              <div className="flex justify-between"><span className="text-gray-500">state</span><span className="text-gray-200">{contract?.state || '—'}</span></div>
            </div>
            <div className="text-[10px] font-mono text-gray-600 mt-2 leading-snug">runs once · seals the shared timeline ID · HDMI profile is a software model, never hardware EDID</div>
          </div>

          {/* ACTIVE — long-run layer */}
          <div data-testid="clyde-contract-active" className="rounded-lg border border-gray-800 bg-black/50 p-3">
            <div className="text-[10px] font-mono text-cyan-300 mb-2 tracking-wider">② ACTIVE · LONG RUN</div>
            <div className="space-y-1 text-[10px] font-mono">
              <div className="flex justify-between"><span className="text-gray-500">uptime</span><span data-testid="clyde-contract-uptime" className="text-cyan-300 text-sm">{contract ? formatContractUptime(contract.uptimeSec || 0) : '—'}</span></div>
              <div className="flex justify-between"><span className="text-gray-500">heartbeats</span><span data-testid="clyde-contract-heartbeat" className="text-gray-200">{contract?.active?.heartbeats ?? 0}{lastBeat?.ageMs != null ? ` · ${lastBeat.ageMs.toFixed(0)} ms ago` : ''}</span></div>
              <div className="flex justify-between"><span className="text-gray-500">drift</span><span data-testid="clyde-contract-drift" className="text-gray-200">{lastBeat ? `${lastBeat.driftMs} ms` : '—'}</span></div>
              <div className="flex justify-between"><span className="text-gray-500">soft renewals</span><span data-testid="clyde-contract-renewals" className="text-gray-200">{contract?.active?.renewals ?? 0}</span></div>
              <div className="flex justify-between"><span className="text-gray-500">anchor</span><span className="text-gray-600 truncate max-w-[140px]">{contract?.active ? `${contract.active.anchorClock.toFixed(3)}s (absolute)` : '—'}</span></div>
            </div>
            <button
              data-testid="clyde-contract-renew"
              onClick={() => { if (timelineId) { try { softRenew(timelineId); refreshContract(timelineId); } catch (err) {} } }}
              disabled={!running || !timelineId}
              className="w-full mt-2 px-2 py-1 rounded text-[10px] font-mono border border-gray-700 text-gray-300 hover:border-cyan-500 disabled:opacity-40"
            >
              ⟳ soft renew (no hard reset)
            </button>
            <div className="text-[10px] font-mono text-gray-600 mt-2 leading-snug">3,000 h+ timeline · time derived from the absolute clock, never accumulated · soft corrections only</div>
          </div>

          {/* RECOVERY — self-healing layer */}
          <div data-testid="clyde-contract-recovery" className="rounded-lg border border-gray-800 bg-black/50 p-3">
            <div className="text-[10px] font-mono text-cyan-300 mb-2 tracking-wider">③ RECOVERY · SELF-HEALING</div>
            <div className="space-y-1 text-[10px] font-mono">
              <div className="flex justify-between"><span className="text-gray-500">status</span><span className={contract?.recovery?.state === 'recovering' ? 'text-amber-300' : 'text-emerald-400'}>{contract?.recovery ? `armed · ${contract.recovery.state}` : '—'}</span></div>
              <div className="flex justify-between"><span className="text-gray-500">renegotiations</span><span data-testid="clyde-contract-renegotiations" className="text-gray-200">{contract?.recovery?.renegotiations ?? 0}</span></div>
              <div className="flex justify-between"><span className="text-gray-500">resumes</span><span className="text-gray-200">{contract?.recovery?.resumes ?? 0}</span></div>
            </div>
            <div data-testid="clyde-contract-ruptures" className="mt-2 space-y-1 max-h-16 overflow-y-auto">
              {(!contract?.recovery?.ruptures || contract.recovery.ruptures.length === 0) && (
                <div className="text-[10px] font-mono text-gray-600">rupture log empty — timeline clean</div>
              )}
              {contract?.recovery?.ruptures?.slice(-4).map((r, i) => (
                <div key={i} className="text-[10px] font-mono text-amber-300/80 truncate" title={r.detail || ''}>
                  ⚠ {r.trigger} <span className="text-gray-600">{r.at?.slice(11, 19)}</span>
                </div>
              ))}
            </div>
            <button
              data-testid="clyde-contract-stall-sim"
              onClick={() => { if (timelineId) { try { reportStall(timelineId, 'DAW-Console'); refreshContract(timelineId); } catch (err) {} } }}
              disabled={!running || !timelineId}
              className="w-full mt-2 px-2 py-1 rounded text-[10px] font-mono border border-gray-700 text-gray-300 hover:border-amber-500 disabled:opacity-40"
            >
              ⚠ simulate consumer stall
            </button>
            <div className="text-[10px] font-mono text-gray-600 mt-2 leading-snug">always armed · re-negotiates under the SAME timeline ID · realigns KITSUNE + COLOSSUS · resumes without teardown</div>
          </div>
        </div>
      </div>

      {/* Metrics strip */}
      <div data-testid="clyde-metrics" className="mt-3 flex flex-wrap gap-x-5 gap-y-1 text-[10px] font-mono text-gray-400">
        <span>clock <span className="text-cyan-300">{clock.toFixed(3)}s</span></span>
        <span>jitter <span className="text-cyan-300">{metrics?.jitterMs ?? '—'} ms</span></span>
        <span>drift <span className="text-cyan-300">{metrics?.driftMs ?? '—'} ms</span></span>
        <span>scheduled <span className="text-gray-200">{metrics?.callbacksScheduled ?? 0}</span></span>
        <span>fired <span className="text-gray-200">{metrics?.callbacksFired ?? 0}</span></span>
        <span>missed <span className={metrics?.missedDeadlines ? 'text-red-400' : 'text-gray-200'}>{metrics?.missedDeadlines ?? 0}</span></span>
        <span>lookahead <span className="text-gray-200">{metrics?.lookaheadMs ?? '—'} ms</span></span>
        <span className="text-gray-600">master clock: {status?.masterClock || '—'}</span>
      </div>
    </div>
  );
}

export default ClydeSync;
