// ── Pure core (DOM-free, node-tested) ─────────────────────────────────────────

export const CLYDE_PHASES = [
  'Crystallized',
  'Loop',
  'Yarn',
  'Desolation',
  'Emergence',
];

export const CLYDE_TARGETS = ['monitor', 'headset', 'internal'];

export const CLYDE_HEALTH = ['EXCELLENT', 'GOOD', 'STRAINED'];

/**
 * Tick statistics over a sliding window of raw intervals (ms).
 * Pure + deterministic: same tick sequence → same values. (node-tested)
 */
export function computeTickStats(deltasMs) {
  const n = deltasMs.length;
  if (n === 0) return { count: 0, meanMs: 0, jitterMs: 0, minMs: 0, maxMs: 0 };
  let sum = 0, min = Infinity, max = -Infinity;
  for (const d of deltasMs) { sum += d; if (d < min) min = d; if (d > max) max = d; }
  const mean = sum / n;
  let v = 0;
  for (const d of deltasMs) v += (d - mean) * (d - mean);
  return { count: n, meanMs: mean, jitterMs: Math.sqrt(v / n), minMs: min, maxMs: max };
}

/** One-pole low-pass smoother (PLL-style correction element). Pure. */
export function onePole(prev, next, alpha) {
  const a = Math.max(0, Math.min(1, alpha));
  return prev + a * (next - prev);
}

/** Timing-health classifier. Pure. Thresholds documented in code. */
export function classifyHealth(jitterMs, driftMs) {
  if (jitterMs < 1.5 && driftMs < 2) return 'EXCELLENT';
  if (jitterMs < 6 && driftMs < 12) return 'GOOD';
  return 'STRAINED';
}

/**
 * Virtual HDMI profile — SOFTWARE TIMING MODEL.
 * Browsers cannot read EDID or drive HDMI hardware; these are the standard
 * HDMI timing parameters computed in code and used to derive the frame
 * clock. Labeled as a model everywhere it surfaces (UI + backend).
 * Pure + deterministic. (node-tested)
 */
const HDMI_TABLE = {
  '1080p60': { width: 1920, height: 1080, hTotal: 2200, vTotal: 1125, pixelClockMHz: 148.5 },
  '4K60':    { width: 3840, height: 2160, hTotal: 4400, vTotal: 2250, pixelClockMHz: 594.0 },
  '720p60':  { width: 1280, height: 720,  hTotal: 1650, vTotal: 750,  pixelClockMHz: 74.25 },
};

export function createHdmiProfile(nameOrCustom) {
  let base;
  let timingName;
  if (typeof nameOrCustom === 'string') {
    base = HDMI_TABLE[nameOrCustom];
    if (!base) throw new RangeError(`unknown HDMI profile '${nameOrCustom}' (known: ${Object.keys(HDMI_TABLE).join(', ')})`);
    timingName = nameOrCustom;
  } else if (nameOrCustom && typeof nameOrCustom === 'object') {
    const { width, height, hTotal, vTotal, pixelClockMHz } = nameOrCustom;
    for (const [k, v] of Object.entries({ width, height, hTotal, vTotal, pixelClockMHz })) {
      if (!Number.isFinite(v) || v <= 0) throw new RangeError(`custom profile: ${k} must be a positive number`);
    }
    base = { width, height, hTotal, vTotal, pixelClockMHz };
    timingName = nameOrCustom.timingName || 'custom';
  } else {
    throw new TypeError('createHdmiProfile expects a profile name or a custom timing object');
  }
  const refreshHz = (base.pixelClockMHz * 1e6) / (base.hTotal * base.vTotal);
  return {
    ...base,
    timingName,
    refreshHz,
    frameIntervalMs: 1000 / refreshHz,
    model: 'software', // NOT hardware EDID — see module header
  };
}

/** Session id format shared with the backend mirror: CLYDE-XXXXXX. Pure. */
const SID_CHARS = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
export function makeSessionId(rand = Math.random) {
  let s = '';
  for (let i = 0; i < 6; i++) s += SID_CHARS[Math.floor(rand() * SID_CHARS.length)];
  return `CLYDE-${s}`;
}

// ── Engine state ─────────────────────────────────────────────────────────────

const TICK_WINDOW = 64;

let audioCtx = null;
let running = false;
let target = 'internal';
let profile = createHdmiProfile('1080p60');
let avOffsetMs = 0;

let timerId = 0;      // setTimeout / setInterval handle
let rafId = 0;        // rAF handle (monitor target)
let lastTickAt = 0;   // seconds, engine clock
let tickDeltas = [];  // raw intervals, ms (Crystallized window)
let smoothedJitterMs = 0;
let driftMs = 0;

// Loop phase: closed feedback circuit state
let loopCorrectionMs = 0;
let lastErrorMs = 0;
let loopCorrections = 0;

// Yarn phase: unified scheduler
let nextCbId = 1;
let scheduled = []; // {id, when, cb, kind, enqueuedAt}
let callbacksScheduled = 0;
let callbacksFired = 0;
let missedDeadlines = 0;
// EMERGENCE-tunable: how far ahead of the clock callbacks may fire, so
// consumers (KITSUNE voices) can place sample-accurate audio events early.
let scheduleAheadSec = 0.12;

// Emergence phase: adaptive behavior
let tickIntervalMs = profile.frameIntervalMs;
let maxCallbacksPerTick = Infinity;
let goodStreak = 0;
let adaptations = []; // capped at 32: {at, action, detail}

const sessions = new Map(); // sessionId → session

function recordAdaptation(action, detail) {
  adaptations.push({ at: now(), action, detail });
  if (adaptations.length > 32) adaptations.shift();
}

// ── Master clock ─────────────────────────────────────────────────────────────
// "Phone as master clock" = the best clock a browser offers. AudioContext's
// clock is sample-accurate and driven by the audio hardware thread (lowest
// jitter); performance.now() is the fallback. now() returns seconds.

export function now() {
  if (audioCtx && typeof audioCtx.currentTime === 'number') return audioCtx.currentTime;
  if (typeof performance !== 'undefined') return performance.now() / 1000;
  return Date.now() / 1000;
}

export function isRunning() {
  return running;
}

/** Port-compat timestamp (matches the kitsune.js / colossus.js clock shape). */
export function getTimestamp() {
  return now();
}

// ── Scheduler core (Yarn + Loop + Crystallized + Emergence run here) ──────────

function fireDue(tNow) {
  // Fire in time order; audio callbacks get the A/V offset (lip-sync).
  scheduled.sort((a, b) => a.when - b.when);
  let processed = 0;
  const remaining = [];
  for (const item of scheduled) {
    if (processed >= maxCallbacksPerTick) { remaining.push(item); continue; }
    const fireAt = item.when + (item.kind === 'audio' ? avOffsetMs / 1000 : 0);
    // YARN horizon: callbacks within the schedule-ahead window fire now so
    // consumers can place sample-accurate events ahead of the clock.
    if (tNow + scheduleAheadSec < fireAt) { remaining.push(item); continue; }
    processed++;
    const latenessMs = (tNow - fireAt) * 1000;
    // EMERGENCE shed rule: video frames >50ms late are dropped, never stacked.
    if (item.kind === 'video' && latenessMs > 50) {
      missedDeadlines++;
      recordAdaptation('shed-late-video', { id: item.id, latenessMs: +latenessMs.toFixed(2) });
      continue;
    }
    try {
      item.cb({ scheduledFor: item.when, firedAt: tNow, latenessMs, kind: item.kind });
      callbacksFired++;
    } catch (err) { /* a consumer callback must never kill the clock */ }
    // LOOP phase: closed feedback — actual-vs-target error feeds the next schedule.
    lastErrorMs = latenessMs;
    loopCorrectionMs = onePole(loopCorrectionMs, Math.max(-8, Math.min(8, -latenessMs * 0.5)), 0.25);
    loopCorrections++;
    if (latenessMs > 25) missedDeadlines++;
  }
  scheduled = remaining;
}

function tick(rafTimestamp) {
  if (!running) return;
  const tNow = now();
  // CRYSTALLIZED phase: condition the raw clock — sliding jitter window.
  if (lastTickAt > 0) {
    let intervalMs;
    if (typeof rafTimestamp === 'number' && target === 'monitor') {
      intervalMs = rafTimestamp - tick._lastRaf || tickIntervalMs;
      tick._lastRaf = rafTimestamp;
    } else {
      intervalMs = (tNow - lastTickAt) * 1000;
    }
    tickDeltas.push(intervalMs);
    if (tickDeltas.length > TICK_WINDOW) tickDeltas.shift();
    const stats = computeTickStats(tickDeltas);
    smoothedJitterMs = onePole(smoothedJitterMs, stats.jitterMs, 0.2);
    driftMs = Math.abs(stats.meanMs - profile.frameIntervalMs);
  }
  lastTickAt = tNow;

  // LOOP correction shifts the effective timeline for this tick's firings.
  fireDue(tNow + loopCorrectionMs / 1000);

  // EMERGENCE phase: watch timing health, adapt the scheduler.
  const health = classifyHealth(smoothedJitterMs, driftMs);
  if (health === 'STRAINED') {
    goodStreak = 0;
    let adapted = false;
    if (scheduleAheadSec < 0.5) {
      scheduleAheadSec = Math.min(0.5, scheduleAheadSec + 0.06);
      recordAdaptation('increase-lookahead', { scheduleAheadSec: +scheduleAheadSec.toFixed(3), reason: `jitter ${smoothedJitterMs.toFixed(2)}ms` });
      adapted = true;
    }
    if (tickIntervalMs > 4) {
      tickIntervalMs = Math.max(4, tickIntervalMs / 2);
      maxCallbacksPerTick = 8;
      recordAdaptation('increase-tempo', { tickIntervalMs: +tickIntervalMs.toFixed(2), reason: `jitter ${smoothedJitterMs.toFixed(2)}ms` });
      adapted = true;
    }
    if (adapted) restartDriver();
  } else {
    goodStreak++;
    if (goodStreak >= 90 && (tickIntervalMs < profile.frameIntervalMs || scheduleAheadSec > 0.12)) {
      tickIntervalMs = profile.frameIntervalMs;
      scheduleAheadSec = 0.12;
      maxCallbacksPerTick = Infinity;
      goodStreak = 0;
      recordAdaptation('recover', { tickIntervalMs: +tickIntervalMs.toFixed(2), scheduleAheadSec });
      restartDriver();
    }
  }

  if (target === 'monitor' && typeof requestAnimationFrame === 'function') {
    rafId = requestAnimationFrame(tick);
  }
}

function restartDriver() {
  if (timerId) { clearTimeout(timerId); clearInterval(timerId); timerId = 0; }
  if (rafId && typeof cancelAnimationFrame === 'function') { cancelAnimationFrame(rafId); rafId = 0; }
  if (!running) return;
  if (target === 'monitor' && typeof requestAnimationFrame === 'function') {
    rafId = requestAnimationFrame(tick);
  } else if (target === 'headset') {
    // Headset: paced off the audio clock domain (setInterval; the clock
    // itself is AudioContext.currentTime via now()).
    timerId = setInterval(() => tick(), tickIntervalMs);
  } else {
    // Internal / Desolation: pure software clock, headless-capable.
    const step = () => { if (!running) return; tick(); timerId = setTimeout(step, tickIntervalMs); };
    timerId = setTimeout(step, tickIntervalMs);
  }
}

// ── Public API ───────────────────────────────────────────────────────────────

/**
 * Init the CLYDE engine. Pass an AudioContext for the sample-accurate master
 * clock; otherwise performance.now() is used. Safe to call repeatedly.
 */
export function init({ audioContext } = {}) {
  if (audioContext && typeof audioContext.currentTime === 'number') audioCtx = audioContext;
  if (running) return engineStatus();
  running = true;
  lastTickAt = 0;
  tickDeltas = [];
  smoothedJitterMs = 0;
  driftMs = 0;
  tickIntervalMs = profile.frameIntervalMs;
  maxCallbacksPerTick = Infinity;
  scheduleAheadSec = 0.12;
  goodStreak = 0;
  restartDriver();
  return engineStatus();
}

export function shutdown() {
  running = false;
  if (timerId) { clearTimeout(timerId); clearInterval(timerId); timerId = 0; }
  if (rafId && typeof cancelAnimationFrame === 'function') { cancelAnimationFrame(rafId); rafId = 0; }
  scheduled = [];
}

/**
 * Schedule a callback on the unified timeline.
 * @param {number} when — engine-clock seconds (see now())
 * @param {function} cb — invoked as cb({scheduledFor, firedAt, latenessMs, kind})
 * @param {'audio'|'video'} kind — audio callbacks receive the A/V offset
 */
export function scheduleAt(when, cb, kind = 'video') {
  if (!Number.isFinite(when)) throw new TypeError('scheduleAt: when must be a finite engine-clock time');
  if (typeof cb !== 'function') throw new TypeError('scheduleAt: cb must be a function');
  if (kind !== 'audio' && kind !== 'video') throw new RangeError("scheduleAt: kind must be 'audio' or 'video'");
  const id = nextCbId++;
  scheduled.push({ id, when, cb, kind, enqueuedAt: now() });
  callbacksScheduled++;
  return id;
}

export function cancelScheduled(id) {
  const before = scheduled.length;
  scheduled = scheduled.filter((s) => s.id !== id);
  return scheduled.length < before;
}

/** Sync target: 'monitor' (display-paced), 'headset' (audio-clock), 'internal' (software). */
export function setTarget(t) {
  if (!CLYDE_TARGETS.includes(t)) throw new RangeError(`target must be one of ${CLYDE_TARGETS.join(', ')}`);
  target = t;
  restartDriver();
  return target;
}

export function getTarget() {
  return target;
}

/** Lip-sync offset, ±500ms. Positive delays audio relative to video. */
export function setAvOffsetMs(ms) {
  avOffsetMs = Math.max(-500, Math.min(500, Number(ms) || 0));
  return avOffsetMs;
}

export function getAvOffsetMs() {
  return avOffsetMs;
}

export function setHdmiProfile(nameOrCustom) {
  profile = createHdmiProfile(nameOrCustom);
  tickIntervalMs = profile.frameIntervalMs;
  restartDriver();
  return { ...profile };
}

export function getHdmiProfile() {
  return { ...profile };
}

export function closeSession(sessionId) {
  return sessions.delete(sessionId);
}

export function getSessions() {
  return [...sessions.values()].map((s) => ({ ...s }));
}

// ── Live phase state ─────────────────────────────────────────────────────────

export function getPhases() {
  const stats = computeTickStats(tickDeltas);
  const pendingAudio = scheduled.filter((s) => s.kind === 'audio').length;
  const pendingVideo = scheduled.filter((s) => s.kind === 'video').length;
  return {
    Crystallized: {
      active: running,
      jitterMs: +smoothedJitterMs.toFixed(3),
      driftMs: +driftMs.toFixed(3),
      windowSize: stats.count,
      rawJitterMs: +stats.jitterMs.toFixed(3),
    },
    Loop: {
      active: running,
      lastErrorMs: +lastErrorMs.toFixed(3),
      correctionMs: +loopCorrectionMs.toFixed(3),
      corrections: loopCorrections,
      feedback: 'closed',
    },
    Yarn: {
      active: running,
      pendingAudio,
      pendingVideo,
      scheduledTotal: callbacksScheduled,
      firedTotal: callbacksFired,
      missedDeadlines,
      frameIntervalMs: +tickIntervalMs.toFixed(3),
      scheduleAheadMs: +(scheduleAheadSec * 1000).toFixed(1),
      maxCallbacksPerTick: maxCallbacksPerTick === Infinity ? 'unlimited' : maxCallbacksPerTick,
    },
    Desolation: {
      active: true, // hardware independence is structural, not toggled
      hardwareFree: true,
      clockSource: audioCtx ? 'AudioContext.currentTime (sample-accurate)' : 'performance.now() (fallback)',
      headlessCapable: true,
      vsyncAssumed: false,
    },
    Emergence: {
      active: running,
      health: classifyHealth(smoothedJitterMs, driftMs),
      adaptations: adaptations.slice(-8),
      adaptationCount: adaptations.length,
    },
  };
}

export function getMetrics() {
  return {
    jitterMs: +smoothedJitterMs.toFixed(3),
    driftMs: +driftMs.toFixed(3),
    health: classifyHealth(smoothedJitterMs, driftMs),
    callbacksScheduled,
    callbacksFired,
    missedDeadlines,
    lookaheadMs: +(scheduleAheadSec * 1000).toFixed(1),
    tickIntervalMs: +tickIntervalMs.toFixed(3),
    sessions: sessions.size,
  };
}

// ── Session-Negotiated Timing Contract (Option 2, Variation 3) ───────────────
// Owner canon. Conforms to src/lib/clyde-contracts.d.ts (ClydeContractEngine).
//
// RELATIONSHIP TO THE FIVE PHASES: the phases (Crystallized → Loop → Yarn →
// Desolation → Emergence) are the RUNTIME PIPELINE — they run code every
// scheduler tick (see tick()). The three contracts are the SESSION LIFECYCLE
// around that pipeline:
//   BASE     — negotiate the timing model once, seal a shared timeline ID.
//   ACTIVE   — ignite the 3,000+ hour timeline on the phone audio clock.
//   RECOVERY — sense rupture, re-negotiate under the SAME timeline ID,
//              realign the engines, resume. Never tears the timeline down.
//
// THE NO-ACCUMULATION INVARIANT (this is what makes 3,000 hours real):
// time is NEVER accumulated by addition. Every timestamp derives from the
// absolute master clock: pulseAt(n) = anchorClock + n·interval + correction
// — a single multiplication, so float error stays O(eps) at pulse
// 648,000,000. Heartbeats are cheap pings; soft renewals re-derive the
// correction term instead of moving the anchor. Uptime is derived, never
// summed. Background-tab throttling just makes heartbeats sparse — the
// Recovery Contract treats the gap as drift and heals it.

export const CONTRACT_VERSION = 'Option 2 Variation 3';
export const RECOVERY_TRIGGERS = ['missed-heartbeat', 'drift-exceeded', 'consumer-stall'];

const HEARTBEAT_TIMEOUT_MS = 5000; // missed-heartbeat rupture threshold
const RUPTURE_DRIFT_MS = 50;       // drift-exceeded rupture threshold

const timelines = new Map(); // timelineId → { base, active, recovery, state, stallReport, opts }

function getTimelineEntry(timelineId) {
  const t = timelines.get(timelineId);
  if (!t) throw new RangeError(`unknown timeline '${timelineId}'`);
  return t;
}

function deriveSyncMode(useAudioClock, target) {
  if (useAudioClock) return 'audiomaster+framefollower';
  if (target === 'monitor') return 'monitor+framefollower';
  return 'internal+framefollower';
}

function masterClockSource() {
  return audioCtx ? 'AudioContext.currentTime' : 'performance.now()';
}

function effectiveDriftMs(entry) {
  // Test/monitor seam: an injected drift overrides the engine measurement.
  // Heartbeats report the ENGINE's measured drift — never invented.
  if (entry.active && typeof entry.active.injectedDriftMs === 'number') {
    return entry.active.injectedDriftMs;
  }
  return driftMs;
}

// ── Contract 1 · Base (Handshake Layer) ─────────────────────────────────────

/**
 * Propose timing terms. Pure validation — throws on bad terms.
 * opts: { heartbeatTimeoutMs, ruptureDriftMs } — thresholds (tests use small ones).
 */
export function negotiateTiming(
  { frameRates, granularityMs, useAudioClock, hdmiProfile, target } = {},
  opts = {}
) {
  if (!Array.isArray(frameRates) || frameRates.length === 0) {
    throw new RangeError('negotiateTiming: frameRates must be a non-empty array');
  }
  for (const r of frameRates) {
    if (!Number.isFinite(r) || r <= 0) throw new RangeError(`negotiateTiming: frame rate ${r} must be a positive number`);
  }
  if (!Number.isFinite(granularityMs) || granularityMs <= 0 || granularityMs > 1000) {
    throw new RangeError('negotiateTiming: granularityMs must be in (0, 1000]');
  }
  if (!CLYDE_TARGETS.includes(target)) {
    throw new RangeError(`negotiateTiming: target must be one of ${CLYDE_TARGETS.join(', ')}`);
  }
  const profileObj = createHdmiProfile(hdmiProfile); // throws on unknown profile
  const useClock = !!useAudioClock;
  return {
    timelineId: makeSessionId(),
    syncMode: deriveSyncMode(useClock, target),
    hdmiProfile: profileObj,
    negotiation: {
      frameRates: [...frameRates],
      granularityMs,
      useAudioClock: useClock,
      hdmiProfile: typeof hdmiProfile === 'string' ? hdmiProfile : { ...profileObj },
      target,
    },
    _opts: {
      heartbeatTimeoutMs: Number.isFinite(opts.heartbeatTimeoutMs) ? opts.heartbeatTimeoutMs : HEARTBEAT_TIMEOUT_MS,
      ruptureDriftMs: Number.isFinite(opts.ruptureDriftMs) ? opts.ruptureDriftMs : RUPTURE_DRIFT_MS,
    },
  };
}

/**
 * Freeze a negotiation into an immutable Base Contract. One shot per timeline.
 */
export function sealTimeline(negotiation) {
  if (!negotiation || typeof negotiation.timelineId !== 'string' || !negotiation.hdmiProfile) {
    throw new TypeError('sealTimeline: requires a negotiation from negotiateTiming()');
  }
  const { timelineId } = negotiation;
  if (timelines.has(timelineId)) throw new Error(`timeline '${timelineId}' is already sealed (one shot)`);
  const entry = {
    base: {
      timelineId,
      syncMode: negotiation.syncMode,
      hdmiProfile: { ...negotiation.hdmiProfile },
      negotiation: JSON.parse(JSON.stringify(negotiation.negotiation)),
      sealedAt: new Date().toISOString(),
      state: 'sealed',
    },
    active: null,
    recovery: { timelineId, ruptures: [], renegotiations: 0, resumes: 0, state: 'active', lastRealignment: null },
    state: 'sealed',
    stallReport: null,
    opts: { ...negotiation._opts },
  };
  delete entry.base.negotiation._opts;
  timelines.set(timelineId, entry);
  return { ...entry.base };
}

// ── Contract 2 · Active (Long-Run Layer) ────────────────────────────────────

/**
 * Anchor the timeline to the ABSOLUTE master clock and start frame pulses.
 * The anchor is immutable afterwards — this is the no-accumulation invariant.
 */
export function ignitePulse(timelineId) {
  const entry = getTimelineEntry(timelineId);
  if (entry.state !== 'sealed') throw new Error(`ignitePulse: timeline '${timelineId}' is ${entry.state}, must be sealed`);
  entry.active = {
    timelineId,
    anchorClock: now(), // absolute master-clock seconds — never moved again
    frameIntervalMs: entry.base.hdmiProfile.frameIntervalMs,
    heartbeats: 0,
    renewals: 0,
    softCorrectionMs: 0,
    lastHeartbeatAt: null,
    injectedDriftMs: null,
    state: 'active',
  };
  entry.state = 'active';
  if (!running) {
    running = true;
    lastTickAt = 0;
    tickDeltas = [];
    smoothedJitterMs = 0;
    driftMs = 0;
    tickIntervalMs = entry.active.frameIntervalMs;
    maxCallbacksPerTick = Infinity;
    scheduleAheadSec = 0.12;
    goodStreak = 0;
    restartDriver();
  }
  const { injectedDriftMs, ...publicActive } = entry.active;
  return publicActive;
}

/**
 * Cheap liveness ping. Reports the ENGINE's measured drift — never invents it.
 */
export function heartbeat(timelineId) {
  const entry = getTimelineEntry(timelineId);
  if (!entry.active || entry.state !== 'active') {
    throw new Error(`heartbeat: timeline '${timelineId}' is not active`);
  }
  const t = now();
  const ageMs = entry.active.lastHeartbeatAt == null ? null : (t - entry.active.lastHeartbeatAt) * 1000;
  entry.active.lastHeartbeatAt = t;
  entry.active.heartbeats++;
  return { ok: true, driftMs: +effectiveDriftMs(entry).toFixed(3), ageMs: ageMs == null ? null : +ageMs.toFixed(1), heartbeats: entry.active.heartbeats };
}

/**
 * Soft renewal: re-derive the correction term toward canceling measured
 * drift. The anchor is NOT moved — no hard reset, no accumulation.
 */
export function softRenew(timelineId) {
  const entry = getTimelineEntry(timelineId);
  if (!entry.active || entry.state !== 'active') {
    throw new Error(`softRenew: timeline '${timelineId}' is not active`);
  }
  entry.active.softCorrectionMs = -effectiveDriftMs(entry);
  entry.active.renewals++;
  return { renewals: entry.active.renewals, correctionMs: +entry.active.softCorrectionMs.toFixed(3) };
}

/**
 * Feed a measured drift into the contract (seam for tests and monitors).
 */
export function correctDrift(timelineId, measuredDriftMs) {
  const entry = getTimelineEntry(timelineId);
  if (!entry.active) throw new Error(`correctDrift: timeline '${timelineId}' has no active contract`);
  if (!Number.isFinite(measuredDriftMs)) throw new TypeError('correctDrift: measuredDriftMs must be finite');
  entry.active.injectedDriftMs = measuredDriftMs;
  return { driftMs: +effectiveDriftMs(entry).toFixed(3), jitterMs: +smoothedJitterMs.toFixed(3), at: now() };
}

/**
 * Frame pulse n — DERIVED from the absolute clock, never accumulated:
 *   pulseAt(n) = anchorClock + n·interval + softCorrection
 * One multiplication: float error stays O(eps) at pulse 648,000,000
 * (≈3,000 h at 60 fps). Iterative addition would drift ~seconds there.
 */
export function pulseAt(timelineId, pulseIndex) {
  const entry = getTimelineEntry(timelineId);
  if (!entry.active) throw new Error(`pulseAt: timeline '${timelineId}' has no active contract`);
  if (!Number.isInteger(pulseIndex) || pulseIndex < 0) {
    throw new RangeError('pulseAt: pulseIndex must be a non-negative integer');
  }
  return entry.active.anchorClock
    + (pulseIndex * entry.active.frameIntervalMs) / 1000
    + entry.active.softCorrectionMs / 1000;
}

/** Uptime in seconds — derived from the absolute clock, never summed. */
export function getUptime(timelineId) {
  const entry = getTimelineEntry(timelineId);
  if (!entry.active) return 0;
  return Math.max(0, now() - entry.active.anchorClock);
}

// ── Contract 3 · Recovery (Self-Healing Layer) ──────────────────────────────

/**
 * Check the three rupture triggers. Pure read — sensing never heals by itself.
 */
export function senseRupture(timelineId) {
  const entry = getTimelineEntry(timelineId);
  if (entry.state !== 'active' || !entry.active) {
    return { ruptured: false, trigger: null };
  }
  const t = now();
  const lastBeat = entry.active.lastHeartbeatAt == null ? entry.active.anchorClock : entry.active.lastHeartbeatAt;
  // Trigger 1: consumer stall (latched report).
  if (entry.stallReport) {
    return rupture(entry, 'consumer-stall', `consumer '${entry.stallReport.consumer}' reported stall`);
  }
  // Trigger 2: missed heartbeats (sparse ticks — e.g. background-tab throttling).
  if ((t - lastBeat) * 1000 > entry.opts.heartbeatTimeoutMs) {
    return rupture(entry, 'missed-heartbeat', `no heartbeat for ${((t - lastBeat) * 1000).toFixed(0)} ms (timeout ${entry.opts.heartbeatTimeoutMs} ms)`);
  }
  // Trigger 3: drift beyond threshold.
  const d = Math.abs(effectiveDriftMs(entry));
  if (d > entry.opts.ruptureDriftMs) {
    return rupture(entry, 'drift-exceeded', `drift ${d.toFixed(2)} ms exceeds ${entry.opts.ruptureDriftMs} ms`);
  }
  return { ruptured: false, trigger: null };
}

function rupture(entry, trigger, detail) {
  entry.state = 'ruptured';
  entry.recovery.state = 'recovering';
  entry.recovery.ruptures.push({ at: new Date().toISOString(), trigger, detail });
  return { ruptured: true, trigger, detail };
}

/** A consumer reports it has stalled. Latches until renegotiated. */
export function reportStall(timelineId, consumer) {
  const entry = getTimelineEntry(timelineId);
  if (!consumer || typeof consumer !== 'string') throw new TypeError('reportStall: consumer name required');
  entry.stallReport = { consumer, at: new Date().toISOString() };
}

/**
 * Re-negotiate the timing mode. The TIMELINE ID IS UNCHANGED — that is the
 * contract. The mode is the only thing allowed to move.
 */
export function renegotiate(timelineId, trigger) {
  const entry = getTimelineEntry(timelineId);
  if (!RECOVERY_TRIGGERS.includes(trigger)) {
    throw new RangeError(`renegotiate: trigger must be one of ${RECOVERY_TRIGGERS.join(', ')}`);
  }
  if (entry.state !== 'ruptured' && entry.state !== 'recovering') {
    throw new Error(`renegotiate: timeline '${timelineId}' is ${entry.state} — nothing to recover`);
  }
  const oldMode = entry.base.syncMode;
  const newMode = deriveSyncMode(!!audioCtx, entry.base.negotiation.target);
  entry.base.syncMode = newMode; // the ONE mutable field of the sealed base
  entry.stallReport = null;
  entry.recovery.renegotiations++;
  entry.recovery.ruptures.push({
    at: new Date().toISOString(),
    trigger,
    detail: `renegotiated ${oldMode} → ${newMode} (timeline ID unchanged)`,
  });
  entry.state = 'recovering';
  return { timelineId, oldMode, newMode };
}

/**
 * Record realignment of KITSUNE + COLOSSUS to the audio clock. The actual
 * consumer re-attach is performed by unified_sensory.js (it owns the engine
 * handles); CLYDE records the directive so the timeline history is complete.
 */
export function realignEngines(timelineId) {
  const entry = getTimelineEntry(timelineId);
  if (entry.state !== 'recovering') {
    throw new Error(`realignEngines: timeline '${timelineId}' is ${entry.state} — renegotiate first`);
  }
  entry.recovery.lastRealignment = {
    at: new Date().toISOString(),
    alignedTo: masterClockSource(),
    engines: ['kitsune', 'colossus'],
  };
  return { ...entry.recovery.lastRealignment };
}

/**
 * Resume the Active Contract. No teardown, no new timeline, anchor untouched —
 * only the soft correction is re-derived from current drift.
 */
export function resumeTimeline(timelineId) {
  const entry = getTimelineEntry(timelineId);
  if (entry.state !== 'recovering') {
    throw new Error(`resumeTimeline: timeline '${timelineId}' is ${entry.state} — renegotiate first`);
  }
  entry.active.injectedDriftMs = null; // back to the engine's live measurement
  entry.active.softCorrectionMs = -effectiveDriftMs(entry);
  entry.active.lastHeartbeatAt = now();
  entry.state = 'active';
  entry.recovery.state = 'active';
  entry.recovery.resumes++;
  const { injectedDriftMs, ...publicActive } = entry.active;
  return publicActive;
}

// ── Inspection ──────────────────────────────────────────────────────────────

export function getTimeline(timelineId) {
  const entry = getTimelineEntry(timelineId);
  const { injectedDriftMs, ...active } = entry.active || {};
  return {
    timelineId,
    state: entry.state,
    base: JSON.parse(JSON.stringify(entry.base)),
    active: entry.active ? active : null,
    recovery: JSON.parse(JSON.stringify(entry.recovery)),
    uptimeSec: entry.active ? +getUptime(timelineId).toFixed(1) : 0,
  };
}

export function getRuptureLog(timelineId) {
  return getTimelineEntry(timelineId).recovery.ruptures.slice();
}

export function getTimelines() {
  return [...timelines.keys()];
}

/** HH:MM:SS — hours keep growing past 99 (3000:00:00 is a valid uptime). */
export function formatContractUptime(totalSeconds) {
  const s = Math.max(0, Math.floor(totalSeconds || 0));
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const sec = s % 60;
  const p = (n) => String(n).padStart(2, '0');
  return `${h}:${p(m)}:${p(sec)}`;
}

// ── Sessions map onto contract triples ──────────────────────────────────────
// virtualHandshake seals a Base Contract under the hood: every session
// carries a timelineId, so the legacy session API keeps working while the
// contract lifecycle owns the timing. A contract failure never breaks the
// handshake itself.

export function virtualHandshake(consumerName, negotiationOverrides = {}) {
  if (!consumerName || typeof consumerName !== 'string') throw new TypeError('virtualHandshake: consumerName required');
  const session = {
    sessionId: makeSessionId(),
    consumer: consumerName,
    profile: { ...profile },
    target,
    negotiatedAt: new Date().toISOString(),
    avOffsetMs,
  };
  try {
    const neg = negotiateTiming({
      frameRates: [60],
      granularityMs: session.profile.frameIntervalMs,
      useAudioClock: !!audioCtx,
      hdmiProfile: session.profile.timingName,
      target: session.target,
    }, negotiationOverrides);
    // Reuse the session id as the timeline id: one identity, both surfaces.
    neg.timelineId = session.sessionId;
    const base = sealTimeline(neg);
    session.timelineId = base.timelineId;
    session.syncMode = base.syncMode;
  } catch (err) { /* a contract failure must never break the legacy handshake */ }
  sessions.set(session.sessionId, session);
  return { ...session };
}

export function engineStatus() {
  return {
    name: 'CLYDE',
    fullName: 'Crystallized Loop Yarn Desolation Emergence',
    protocol: 'CLYDE-1',
    phases: 5,
    phaseNames: [...CLYDE_PHASES],
    contracts: { version: CONTRACT_VERSION, timelines: timelines.size },
    masterClock: audioCtx ? 'AudioContext.currentTime' : 'performance.now()',
    masterClockNote: 'phone-as-master-clock = the best clock a browser offers (sample-accurate when AudioContext is present)',
    running,
    target,
    hdmiProfile: { timingName: profile.timingName, refreshHz: +profile.refreshHz.toFixed(2), model: 'software' },
    hdmiNote: 'virtual HDMI profile is a software timing model — browsers cannot access real EDID hardware',
    sessions: sessions.size,
    metrics: getMetrics(),
  };
}
