import React, { useState, useMemo } from 'react';
import * as Tone from 'tone';
import { Play, Music2, Globe2, SlidersHorizontal, UploadCloud } from 'lucide-react';
import { PIANO_STYLES, PIANO_CATEGORIES, createPianoVoice } from '@/lib/pianoStyles';
