const TABS = [
  { id: 'piano', label: 'Piano Styles', count: PIANO_STYLES.length, icon: Music2 },
  { id: 'instruments', label: 'Instrument Pack', count: COVENANT_INSTRUMENTS.length, icon: Globe2 },
  { id: 'mixer', label: 'Spatial Mixer', count: 24, icon: SlidersHorizontal },
];

async function previewPiano(style) {
  await Tone.start();
  const voice = createPianoVoice(style);
  const now = Tone.now();
  const seq = ['C4', 'E4', 'G4', 'C5'];
  try {
    if (voice.node.triggerAttackRelease) {
      seq.forEach((n, i) => voice.node.triggerAttackRelease(n, '8n', now + i * 0.22));
    }
  } catch (e) { /* noop */ }
  setTimeout(() => voice.dispose(), 4000);
}

async function previewInstrument(inst) {
  await Tone.start();
  const v = buildInstrumentVoice(inst);
  try {
    v.node.triggerAttackRelease('C4', '4n');
  } catch (e) { /* noop */ }
  setTimeout(() => v.dispose(), 3000);
}

