function audioBufferToWavBase64(buffer) {
  const numCh = Math.min(2, buffer.numberOfChannels);
  const sr = buffer.sampleRate;
  const len = buffer.length;
  const blockAlign = numCh * 2;
  const dataSize = len * blockAlign;
  const ab = new ArrayBuffer(44 + dataSize);
  const v = new DataView(ab);
  const writeStr = (o, s) => { for (let i = 0; i < s.length; i++) v.setUint8(o + i, s.charCodeAt(i)); };
  writeStr(0, 'RIFF'); v.setUint32(4, 36 + dataSize, true); writeStr(8, 'WAVE');
  writeStr(12, 'fmt '); v.setUint32(16, 16, true); v.setUint16(20, 1, true);
  v.setUint16(22, numCh, true); v.setUint32(24, sr, true);
  v.setUint32(28, sr * blockAlign, true); v.setUint16(32, blockAlign, true);
  v.setUint16(34, 16, true); writeStr(36, 'data'); v.setUint32(40, dataSize, true);
  const chans = [];
  for (let c = 0; c < numCh; c++) chans.push(buffer.getChannelData(c));
  let off = 44;
  for (let i = 0; i < len; i++) {
    for (let c = 0; c < numCh; c++) {
      const s = Math.max(-1, Math.min(1, chans[c][i]));
      v.setInt16(off, s < 0 ? s * 0x8000 : s * 0x7fff, true);
      off += 2;
    }
  }
  const bytes = new Uint8Array(ab);
  let bin = '';
  for (let i = 0; i < bytes.length; i += 0x8000) {
    bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
  }
  return btoa(bin);
}

// Renders a representative phrase with the library's REAL loaded voices
// (first piano style + first covenant instrument), bounced via Tone.Offline.
async function bouncePhrase() {
  const usedNames = [];
  const buffer = await Tone.Offline(async () => {
    const voices = [];
    const tryVoice = (builder, arg, label) => {
      try {
        const v = builder(arg);
        voices.push(v);
        usedNames.push(label);
        return v;
      } catch (e) { return null; }
    };
    const piano = tryVoice(createPianoVoice, PIANO_STYLES[0], `piano:${PIANO_STYLES[0]?.name || 'piano'}`);
    const lead = tryVoice(buildInstrumentVoice, COVENANT_INSTRUMENTS[0], `lead:${COVENANT_INSTRUMENTS[0]?.name || 'lead'}`);
    // Let convolution reverbs build their impulses before notes land
    // (offline clock doesn't advance during this await).
    await new Promise((r) => setTimeout(r, 400));
    const t0 = Tone.now() + 0.1;
    const chords = [['C3', 'E3', 'G3'], ['G2', 'B2', 'D3'], ['A2', 'C3', 'E3'], ['F2', 'A2', 'C3']];
    chords.forEach((chord, i) => {
      if (piano && piano.node.triggerAttackRelease) {
        chord.forEach((n) => piano.node.triggerAttackRelease(n, '2n', t0 + i * 2));
      }
    });
    const melody = ['C5', 'D5', 'E5', 'G5', 'A5', 'G5', 'E5', 'D5'];
    melody.forEach((n, i) => {
      if (lead && lead.node.triggerAttackRelease) lead.node.triggerAttackRelease(n, '4n', t0 + i * 1);
    });
  }, 8.6);
  return { buffer, usedNames };
}

function BandcampExport() {
  const [open, setOpen] = useState(false);
  const [title, setTitle] = useState('Sovereign Sketch');
  const [artist, setArtist] = useState("Benny's Studio");
  const [bpm, setBpm] = useState(120);
  const [status, setStatus] = useState('idle'); // idle|rendering|uploading|done|error
  const [error, setError] = useState('');
  const [fileName, setFileName] = useState('');

  const runExport = async () => {
    const API = process.env.REACT_APP_BACKEND_URL || '';
    setError('');
    setStatus('rendering');
    try {
      const { buffer, usedNames } = await bouncePhrase();
      const wavBase64 = audioBufferToWavBase64(buffer);
      setStatus('uploading');
      const res = await fetch(`${API}/api/daw/export/bandcamp`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: title.trim() || 'Untitled',
          artist: artist.trim() || 'Unknown Artist',
          bpm: Number(bpm) || 120,
          tracks: [{ name: `${title.trim() || 'Untitled'} (${usedNames.join(' + ') || 'sovereign voices'})` }],
          audio_wav_base64: wavBase64,
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Export failed');
      setFileName(data.file_name);
      setStatus('done');
      const a = document.createElement('a');
      a.href = `${API}${data.download_url}`;
      a.download = data.file_name;
      document.body.appendChild(a);
      a.click();
      a.remove();
    } catch (e) {
      setError(e.message || 'Export failed');
      setStatus('error');
    }
  };

  return (
    <div className="relative">
      <button
        onClick={() => setOpen((o) => !o)}
        data-testid="bandcamp-export-open"
        className="flex items-center gap-1.5 text-xs font-bold px-3 py-1.5 rounded-lg border border-amber-500/40 bg-amber-500/15 text-amber-200 hover:bg-amber-500/25"
      >
        <UploadCloud className="h-3.5 w-3.5" />
        Export to Bandcamp
      </button>
      {open && (
        <div className="absolute right-0 top-full mt-2 z-20 w-80 rounded-xl border border-white/15 bg-[#14101f] p-4 shadow-2xl" data-testid="bandcamp-export-panel">
          <h4 className="text-xs font-bold text-white mb-1">Bandcamp project bundle</h4>
          <p className="text-[10px] text-gray-500 mb-3 leading-snug">
            Bounces the library's real voices via Tone.Offline to WAV, then packages
            track.wav + cover.png + metadata.json into a downloadable .zip.
          </p>
          <label className="block text-[10px] font-bold text-gray-400 mb-1">Title</label>
          <input value={title} onChange={(e) => setTitle(e.target.value)} data-testid="bandcamp-export-title"
            className="w-full text-xs bg-black/60 border border-white/15 rounded-lg px-2 py-1.5 text-white mb-2" />
          <label className="block text-[10px] font-bold text-gray-400 mb-1">Artist</label>
          <input value={artist} onChange={(e) => setArtist(e.target.value)} data-testid="bandcamp-export-artist"
            className="w-full text-xs bg-black/60 border border-white/15 rounded-lg px-2 py-1.5 text-white mb-2" />
          <label className="block text-[10px] font-bold text-gray-400 mb-1">BPM</label>
          <input type="number" value={bpm} onChange={(e) => setBpm(e.target.value)} data-testid="bandcamp-export-bpm"
            className="w-full text-xs bg-black/60 border border-white/15 rounded-lg px-2 py-1.5 text-white mb-3" />
          <button
            onClick={runExport}
            disabled={status === 'rendering' || status === 'uploading'}
            data-testid="bandcamp-export-render"
            className="w-full text-xs font-bold px-3 py-2 rounded-lg bg-amber-500/80 text-black hover:bg-amber-400 disabled:opacity-50"
          >
            {status === 'rendering' && 'Rendering audio…'}
            {status === 'uploading' && 'Packaging ZIP…'}
            {(status === 'idle' || status === 'done' || status === 'error') && 'Render & Download ZIP'}
          </button>
          {status === 'done' && (
            <p className="text-[10px] text-emerald-400 mt-2" data-testid="bandcamp-export-done">Downloaded {fileName}</p>
          )}
          {status === 'error' && (
            <p className="text-[10px] text-red-400 mt-2" data-testid="bandcamp-export-error">{error}</p>
          )}
        </div>
      )}
    </div>
  );
}

export function ForgeSoundLibrary() {
  const [tab, setTab] = useState('piano');
  return (
    <div className="mt-8 rounded-xl border border-gray-800 bg-black/40 p-5">
      <div className="flex items-center justify-between flex-wrap gap-3 mb-4">
        <div className="flex gap-1.5">
          {TABS.map((t) => {
            const Icon = t.icon;
            return (
              <button
                key={t.id}
                onClick={() => setTab(t.id)}
                className={`flex items-center gap-1.5 text-xs font-bold px-3 py-1.5 rounded-lg border transition-colors ${
                  tab === t.id
                    ? 'bg-amber-500/20 border-amber-500/50 text-amber-200'
                    : 'border-white/10 text-gray-400 hover:border-white/25'
                }`}
              >
                <Icon className="h-3.5 w-3.5" />
                {t.label}
                <span className="text-[10px] opacity-70">{t.count}</span>
              </button>
            );
          })}
        </div>
        <BandcampExport />
      </div>

      {tab === 'piano' && <PianoTab />}
      {tab === 'instruments' && <InstrumentTab />}
      {tab === 'mixer' && <SpatialMixer />}
    </div>
  );
}

export default ForgeSoundLibrary;
