// ═══════════════════════════════════════════════════════════════════════════════
// HITACHI — real-time spatial audio processing engine
// Sovereign Core Matrix pillar. Owner canon: HITACHI is a real-time spatial
// audio processing engine.
//
// Architecture (honest for a website): ALL DSP runs in the browser on the
// native Web Audio API — this file is the engine. The backend
// (services/sovereign_daw_backend.py) only holds layer state and presets;
// it never renders audio.
//
// Split of responsibilities:
//   • Tone.js  → instrument previews (src/components/ForgeSoundLibrary.jsx,
//     src/lib/pianoStyles.js, src/lib/covenantInstruments.js)
//   • HITACHI  → the 24-strip spatial mix bus (src/components/SpatialMixer.jsx)
// No new npm dependencies — Web Audio is native.
// ═══════════════════════════════════════════════════════════════════════════════

const STRIP_COUNT = 24;
const SMOOTH_TC = 0.03; // setTargetAtTime constant — click-free real-time moves
const SPACE_SCALE = 8; // layer x/y/z (-1..1) → metres in the HRTF field

let ctx = null;
let master = null;
let reverbSend = null;
let strips = []; // [{ input, panner, stripGain, analyser, send, state }]
let meterScratch = null;

export const HITACHI_GROUPS = {
  ambient: [1, 6],
  melodic: [7, 12],
  harmonic: [13, 18],
  sub_kick: [19, 20],
  mid: [21, 22],
  high: [23, 24],
};

// Generated impulse response — no external audio files, ever.
function makeImpulse(context, seconds = 1.8, decay = 2.8) {
  const rate = context.sampleRate;
  const len = Math.floor(rate * seconds);
  const buf = context.createBuffer(2, len, rate);
  for (let c = 0; c < 2; c++) {
    const data = buf.getChannelData(c);
    for (let i = 0; i < len; i++) {
      data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, decay);
    }
  }
  return buf;
}

function applyStrip(strip) {
  const { panner, stripGain, state } = strip;
  const t = ctx.currentTime;
  panner.positionX.setTargetAtTime(state.x * SPACE_SCALE, t, SMOOTH_TC);
  panner.positionY.setTargetAtTime(state.y * SPACE_SCALE, t, SMOOTH_TC);
  panner.positionZ.setTargetAtTime(-state.z * SPACE_SCALE, t, SMOOTH_TC);
  stripGain.gain.setTargetAtTime(state.audible ? Math.max(state.gain, 0.0001) : 0.0001, t, SMOOTH_TC);
}

// Recompute audibility across all strips after any mute/solo change.
function recomputeAudibility() {
  const anySolo = strips.some((s) => s.state.solo);
  for (const s of strips) {
    s.state.audible = !s.state.mute && (!anySolo || s.state.solo);
    applyStrip(s);
  }
}

/**
 * Create/resume the engine. MUST be called from a user gesture (click/tap)
 * — browsers block AudioContext creation otherwise.
 */
export async function init() {
  if (ctx && ctx.state !== 'closed') {
    if (ctx.state === 'suspended') await ctx.resume();
    return engineStatus();
  }
  ctx = new (window.AudioContext || window.webkitAudioContext)();

  master = ctx.createGain();
  master.gain.value = 0.9;
  master.connect(ctx.destination);

  // Shared generated-impulse reverb on a send bus.
  const convolver = ctx.createConvolver();
  convolver.buffer = makeImpulse(ctx);
  reverbSend = ctx.createGain();
  reverbSend.gain.value = 0.22;
  convolver.connect(reverbSend);
  reverbSend.connect(master);

  strips = [];
  for (let n = 1; n <= STRIP_COUNT; n++) {
    const input = ctx.createGain(); // insert point for future sources
    const panner = ctx.createPanner();
    panner.panningModel = 'HRTF';
    panner.distanceModel = 'inverse';
    panner.refDistance = 1;
    const stripGain = ctx.createGain();
    const analyser = ctx.createAnalyser();
    analyser.fftSize = 256;
    const send = ctx.createGain();
    send.gain.value = 0.5;

    input.connect(panner);
    panner.connect(stripGain);
    stripGain.connect(analyser);
    analyser.connect(master);
    stripGain.connect(send);
    send.connect(convolver);

    strips.push({
      input, panner, stripGain, analyser, send,
      state: { x: 0, y: 0, z: 0, gain: 0.72, mute: false, solo: false, audible: true },
    });
  }
  meterScratch = new Uint8Array(256); // matches analyser fftSize below
  if (ctx.state === 'suspended') await ctx.resume();
  return engineStatus();
}

/**
 * Live-update one strip. n = 1..24.
 * {x,y,z} in -1..1 (HRTF position), gain 0..1.5, mute/solo booleans.
 * No-op (but state-safe) when the engine is off.
 */
export function setLayer(n, { x, y, z, gain, mute, solo } = {}) {
  const strip = strips[n - 1];
  if (!strip) return;
  const s = strip.state;
  if (x !== undefined) s.x = Math.max(-1, Math.min(1, x));
  if (y !== undefined) s.y = Math.max(-1, Math.min(1, y));
  if (z !== undefined) s.z = Math.max(-1, Math.min(1, z));
  if (gain !== undefined) s.gain = Math.max(0, Math.min(1.5, gain));
  const soloChanged = solo !== undefined && solo !== s.solo;
  if (mute !== undefined) s.mute = !!mute;
  if (solo !== undefined) s.solo = !!solo;
  if (!ctx) return;
  if (soloChanged || mute !== undefined) recomputeAudibility();
  else applyStrip(strip);
}

/** RMS level per strip, 0..1. Zeros when the engine is off. */
export function getStripLevels() {
  const out = new Array(STRIP_COUNT).fill(0);
  if (!ctx || ctx.state === 'closed') return out;
  const buf = meterScratch;
  for (let i = 0; i < STRIP_COUNT; i++) {
    strips[i].analyser.getByteTimeDomainData(buf);
    let sum = 0;
    for (let j = 0; j < buf.length; j++) {
      const v = (buf[j] - 128) / 128;
      sum += v * v;
    }
    out[i] = Math.min(1, Math.sqrt(sum / buf.length) * 2.2);
  }
  return out;
}

/** Insert point for a strip's audio source (oscillator, buffer, Tone.js tap…). */
export function getStripInput(n) {
  const strip = strips[n - 1];
  return strip ? strip.input : null;
}

/**
 * Shared-context access for KITSUNE interop (additive export — the existing
 * API is untouched). Returns the live AudioContext, or null when the engine
 * is off. KITSUNE feeds HITACHI strip nodes only when both engines share
 * this exact context (Web Audio forbids cross-context connections).
 */
export function getContext() {
  return ctx;
}

export function engineStatus() {
  const running = !!ctx && ctx.state === 'running';
  return {
    running,
    sampleRate: ctx ? ctx.sampleRate : 0,
    baseLatency: ctx && ctx.baseLatency != null ? Number(ctx.baseLatency.toFixed(4)) : 0,
    strips: STRIP_COUNT,
    hrtf: true,
    name: 'HITACHI',
  };
}

export async function shutdown() {
  if (ctx) {
    try { await ctx.close(); } catch (e) { /* noop */ }
  }
  ctx = null; master = null; reverbSend = null; strips = []; meterScratch = null;
  return engineStatus();
}
