// ── helpers ──────────────────────────────────────────────────────────────────

export function getInstrument(id) {
  return COVENANT_INSTRUMENTS.find((i) => i.id === id) || COVENANT_INSTRUMENTS[0];
}

export function instrumentsByClass(hsClass) {
  return COVENANT_INSTRUMENTS.filter((i) => i.hsClass === hsClass);
}

export function instrumentsByRegion(region) {
  return COVENANT_INSTRUMENTS.filter((i) => i.region === region);
}

export function instrumentPackStats() {
  const byClass = {};
  const byRegion = {};
  for (const i of COVENANT_INSTRUMENTS) {
    byClass[i.hsClass] = (byClass[i.hsClass] || 0) + 1;
    byRegion[i.region] = (byRegion[i.region] || 0) + 1;
  }
  return { total: COVENANT_INSTRUMENTS.length, byClass, byRegion };
}

// Build a live Tone.js voice from an instrument recipe.
// One-shot engines (Membrane/Metal/Noise) trigger via triggerAttackRelease(note, dur).
export function buildInstrumentVoice(recipeOrId) {
  const inst = typeof recipeOrId === 'string' ? getInstrument(recipeOrId) : recipeOrId;
  const recipe = inst.recipe || inst;
  const engine = recipe.engine || 'FMSynth';
  const opts = recipe.options || {};
  let node;
  if (engine === 'MembraneSynth') node = new Tone.MembraneSynth(opts);
  else if (engine === 'MetalSynth') node = new Tone.MetalSynth(opts);
  else if (engine === 'NoiseSynth') node = new Tone.NoiseSynth(opts);
  else if (engine === 'FMSynth') node = new Tone.PolySynth(Tone.FMSynth, opts);
  else if (engine === 'AMSynth') node = new Tone.PolySynth(Tone.AMSynth, opts);
  else if (engine === 'MonoSynth') node = new Tone.MonoSynth(opts);
  else if (engine === 'DuoSynth') node = new Tone.DuoSynth(opts);
  else node = new Tone.PolySynth(Tone.Synth, opts);
  node.volume.value = -8;
  const verb = new Tone.Reverb({ decay: 2.2, wet: 0.22 });
  node.connect(verb);
  verb.toDestination();
  return { instrument: inst, node, dispose() { try { node.dispose(); verb.dispose(); } catch (e) { /* noop */ } } };
}

export default COVENANT_INSTRUMENTS;
