/**
 * EmporiumShell.jsx — the Emporium commerce realm shell.
 * Separate from <SovereignShell> (Forge). Wraps every Emporium route in
 * .montiff-scope, renders the 12-tab Montiff nav + live status bar, and
 * outlets the active page. Imports montiff.css exactly once.
 */
import React, { useEffect, useState } from 'react';
import { NavLink, Outlet } from 'react-router-dom';
import '../../styles/montiff.css';
import { apiGet, pick } from './emporiumApi';
import { Rivets, StatusDot } from './montiff-ui';

const TABS = [
  { to: '/emporium', label: 'DASHBOARD', end: true, testid: 'emporium-tab-dashboard' },
  { to: '/emporium/booking', label: 'BOOKING', testid: 'emporium-tab-booking' },
  { to: '/emporium/hotels', label: 'HOTELS', testid: 'emporium-tab-hotels' },
  { to: '/emporium/cruises', label: 'CRUISES', testid: 'emporium-tab-cruises' },
  { to: '/emporium/cars', label: 'CARS', testid: 'emporium-tab-cars' },
  { to: '/emporium/events', label: 'EVENTS', testid: 'emporium-tab-events' },
  { to: '/emporium/route', label: 'ROUTE', testid: 'emporium-tab-route' },
  { to: '/emporium/vendors', label: 'VENDORS', testid: 'emporium-tab-vendors' },
  { to: '/emporium/claudette', label: 'CLAUDETTE', testid: 'emporium-tab-claudette' },
  { to: '/emporium/ledger', label: 'LEDGER', testid: 'emporium-tab-ledger' },
  { to: '/emporium/trading', label: 'TRADING', testid: 'emporium-tab-trading' },
  { to: '/emporium/foundation', label: 'FOUNDATION', testid: 'emporium-tab-foundation' },
];

function fmtMoney(v) {
  const n = Number(v);
  if (!Number.isFinite(n)) return '—';
  return '$' + n.toLocaleString('en-US', { maximumFractionDigits: 0 });
}

export default function EmporiumShell() {
  const [health, setHealth] = useState('down');
  const [welds, setWelds] = useState(null);
  const [ledgerTotal, setLedgerTotal] = useState(null);

  useEffect(() => {
    let alive = true;
    async function poll() {
      const [h, core, ledger] = await Promise.all([
        apiGet('/api/emporium/travel/health'),
        apiGet('/api/emporium/core/status'),
        apiGet('/api/emporium/ledger/summary'),
      ]);
      if (!alive) return;
      setHealth(h.ok ? 'ok' : 'down');
      if (core.ok) {
        const w = pick(core.data, ['total_welds', 'weld_count', 'welds', 'count'], null);
        setWelds(w === null ? null : w);
      }
      if (ledger.ok) {
        const t = pick(ledger.data, ['total_commission', 'total', 'lifetime_commission', 'net_total'], null);
        setLedgerTotal(t === null ? null : t);
      }
    }
    poll();
    const id = setInterval(poll, 30000);
    return () => { alive = false; clearInterval(id); };
  }, []);

  return (
    <div className="montiff-scope" data-testid="emporium-shell">
      {/* Brand header */}
      <header className="montiff-panel-blue" data-testid="emporium-header" style={{ borderLeft: 'none', borderRight: 'none', borderTop: 'none', boxShadow: 'none' }}>
        <Rivets />
        <div className="montiff-row" style={{ justifyContent: 'space-between' }}>
          <div>
            <div className="montiff-brand" data-testid="emporium-brand">MONTIFF AEROSUPERSONIC</div>
            <div className="montiff-h" style={{ margin: '6px 0 0', color: '#fff' }}>THE EMPORIUM · COMMERCE REALM</div>
          </div>
          <div className="montiff-readout" style={{ color: 'var(--montiff-steel-400)', fontSize: 12, textAlign: 'right' }}>
            SOVEREIGN CORE LINK<br />16-BIT PIXEL BUS · ONLINE
          </div>
        </div>
      </header>

      {/* 12-tab nav */}
      <nav className="montiff-tabs" data-testid="emporium-nav" style={{ padding: '14px 22px 4px' }} aria-label="Emporium sections">
        {TABS.map((t) => (
          <NavLink
            key={t.to}
            to={t.to}
            end={t.end}
            data-testid={t.testid}
            className={({ isActive }) => `montiff-tab${isActive ? ' active' : ''}`}
          >
            {t.label}
          </NavLink>
        ))}
      </nav>

      {/* Status bar */}
      <div className="montiff-status-bar" data-testid="emporium-status-bar" style={{ marginTop: 14 }}>
        <StatusDot
          testid="emporium-status-api-health"
          state={health}
          label={health === 'ok' ? 'API · ONLINE' : 'API · OFFLINE'}
        />
        <span className="montiff-status-item" data-testid="emporium-status-welds">
          WELDS&nbsp;<strong>{welds === null ? '—' : welds}</strong>
        </span>
        <span className="montiff-status-item" data-testid="emporium-status-ledger">
          LEDGER&nbsp;<strong>{ledgerTotal === null ? '—' : fmtMoney(ledgerTotal)}</strong>
        </span>
        <span className="montiff-status-item" style={{ marginLeft: 'auto', color: 'var(--montiff-steel-400)' }}>
          MONTIFF v.86
        </span>
      </div>

      {/* Active page */}
      <main data-testid="emporium-main">
        <Outlet />
      </main>

      <footer style={{ padding: '18px 22px 26px' }} data-testid="emporium-footer">
        <div className="montiff-readout montiff-muted" style={{ fontSize: 11 }}>
          MONTIFF AEROSUPERSONIC · THE EMPORIUM · SOVEREIGN COMMERCE REALM — mock travel data until live welds land.
        </div>
      </footer>
    </div>
  );
}
