import React, { useState } from 'react';
import { empireStyles as s, SampleBadge } from './EmpireShell';
import { COMMS_LEADERS, KPIS } from './empireData';

const TABS = ['CONVERSATION', 'MAPS', 'REPORTS', 'OPERATIONAL HUB', 'ANALYSIS'];

export default function CommsPortal() {
  const [tab, setTab] = useState('OPERATIONAL HUB');
  const [leaderId, setLeaderId] = useState('shelby');
  const [draft, setDraft] = useState('');
  const [thread, setThread] = useState(() => {
    const shelby = COMMS_LEADERS.find((l) => l.id === 'shelby');
    return shelby.thread.map((t, i) => ({ ...t, id: `init-${i}` }));
  });

  const leader = COMMS_LEADERS.find((l) => l.id === leaderId);

  const send = () => {
    const text = draft.trim();
    if (!text) return;
    setThread((t) => [...t, { id: `u-${Date.now()}`, from: 'you', text }]);
    setDraft('');
    // Sample-data mode: the leader auto-acknowledges. No backend, no LLM.
    setTimeout(() => {
      setThread((t) => [...t, {
        id: `a-${Date.now()}`, from: 'shelby',
        text: 'Acknowledged. House Intelligence is routing your message. (sample response — connect the backend for live comms)',
      }]);
    }, 800);
  };

  return (
    <div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 14 }}>
        <div style={{ ...s.title, fontSize: 16 }}>DIRECT COMMUNICATIONS PORTAL</div>
        <SampleBadge />
      </div>
      <div style={{ display: 'flex', gap: 8, marginBottom: 14 }}>
        {TABS.map((t) => (
          <button key={t} onClick={() => setTab(t)} style={{
            ...s.navLink, cursor: 'pointer', fontFamily: 'inherit',
            ...(tab === t ? s.navActive : {}),
          }}>
            {t}
          </button>
        ))}
      </div>

      <div style={{ ...s.grid3, gridTemplateColumns: '240px 1.4fr 1fr' }}>
        {/* Leader select */}
        <div style={s.panel}>
          <div style={s.panelTitle}>SELECT LEADER</div>
          <input placeholder="Search…" style={{
            width: '100%', padding: 8, marginBottom: 10, background: '#0a0e14',
            border: '1px solid #1c2530', borderRadius: 4, color: '#d7dee9', fontFamily: 'inherit',
          }} />
          {COMMS_LEADERS.map((l) => (
            <button key={l.id} onClick={() => setLeaderId(l.id)} style={{
              display: 'block', width: '100%', textAlign: 'left', padding: 10, marginBottom: 6,
              borderRadius: 4, cursor: 'pointer', fontFamily: 'inherit',
              background: leaderId === l.id ? '#1c2530' : '#141b26',
              border: leaderId === l.id ? '1px solid #e8b34b' : '1px solid transparent',
              color: '#d7dee9',
            }}>
              <div style={{ fontSize: 13, fontWeight: 700 }}>{l.name}</div>
              <div style={{ fontSize: 11, color: '#8b98a9' }}>{l.role}</div>
            </button>
          ))}
        </div>

        {/* Conversation */}
        <div style={s.panel}>
          <div style={s.panelTitle}>LEADER: {leader.name.toUpperCase()}</div>
          {leader.bio && <div style={{ fontSize: 12, color: '#8b98a9', marginBottom: 10 }}>Bio — {leader.bio}</div>}
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8, maxHeight: 380, overflowY: 'auto', marginBottom: 10 }}>
            {thread.map((m) => (
              <div key={m.id} style={{
                alignSelf: m.from === 'you' ? 'flex-end' : 'flex-start',
                background: m.from === 'you' ? '#1c2530' : '#141b26',
                border: m.from === 'you' ? '1px solid #7dd3fc' : '1px solid #1c2530',
                borderRadius: 6, padding: 10, maxWidth: '85%', fontSize: 12, lineHeight: 1.5,
              }}>
                <div style={{ fontSize: 10, color: '#5b6b7f', marginBottom: 4 }}>
                  {m.from === 'you' ? 'YOU' : m.from === 'shelby' ? 'SHELBY C. AMORY' : m.from.toUpperCase()}
                </div>
                {m.text}
              </div>
            ))}
          </div>
          <div style={{ display: 'flex', gap: 8 }}>
            <input
              value={draft}
              onChange={(e) => setDraft(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter') send(); }}
              placeholder="Type your prompt for next message."
              style={{
                flex: 1, padding: 10, background: '#0a0e14', border: '1px solid #1c2530',
                borderRadius: 4, color: '#d7dee9', fontFamily: 'inherit',
              }}
            />
            <button onClick={send} style={{
              padding: '10px 18px', background: '#e8b34b', color: '#0a0e14', border: 'none',
              borderRadius: 4, fontWeight: 800, cursor: 'pointer', fontFamily: 'inherit',
            }}>
              ➤
            </button>
          </div>
        </div>

        {/* KPIs */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
          {KPIS.slice(2).map((k) => (
            <div key={k.id} style={s.panel}>
              <div style={{ fontSize: 11, letterSpacing: 2, color: '#8b98a9' }}>{k.label}</div>
              <div style={{ display: 'flex', alignItems: 'baseline', gap: 10, marginTop: 6 }}>
                <span style={{ fontSize: 26, fontWeight: 800, color: '#e8b34b' }}>{k.value}</span>
                <span style={{
                  fontSize: 12, fontWeight: 700, padding: '3px 8px', borderRadius: 10,
                  background: k.up ? '#12351f' : '#3a1414', color: k.up ? '#4ade80' : '#f87171',
                }}>
                  {k.up ? '↑' : '↓'} {k.delta}
                </span>
              </div>
            </div>
          ))}
          <div style={s.panel}>
            <div style={s.panelTitle}>COMMAND PROTOCOLS</div>
            <div style={{ fontSize: 11, lineHeight: 1.7, color: '#8b98a9' }}>
              1. AUTHENTICATION — validate 'PROGENITOR' (B. AMORY) direct override.<br />
              2. ROUTING — primary inputs via 'SHELBY C. AMORY' AI core.<br />
              3. VERIFICATION — human sign-off on non-routine actions.
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
