// ═══════════════════════════════════════════════════════════════════════════════
// KITSUNE — 48-channel spatial audio engine
// Sovereign Core Matrix pillar (third, after HITACHI and TIGA).
// Owner canon (diagram): 48 channels = 4 rings × 12 voices.
//   RING 1 CORE · RING 2 MID-FIELD · RING 3 HIGH-FIELD · RING 4 ULTRA-FIELD
// Features: Internal Multi-Band Transducer · Web-Tuned Resonance ·
//           Virtual HDMI Sync via CLYDE.
//
// Architecture (honest for a website): ALL DSP runs in the browser on the
// native Web Audio API — this file is the engine. The backend
// (services/sovereign_daw_backend.py, /daw/kitsune/*) only holds ring state
// and presets; it never renders audio.
//
// HITACHI interop: kitsune.init({ context: hitachi.getContext() }) lets both
// engines share ONE AudioContext so HITACHI strip insert nodes (pre-panner,
// dry source taps — correct, KITSUNE does its own spatialization) can feed
// KITSUNE voices via attachHitachiFeed(). Cross-context node connections
// throw in Web Audio, so the feed requires the shared context; the function
// refuses otherwise instead of failing silently.
//
// The engine starts SILENT: voices have insert points but no sources.
// Sources attach only on explicit user action (test tone toggle, HITACHI
// feed, or future source wiring). Nothing auto-plays. No new npm deps.
// ═══════════════════════════════════════════════════════════════════════════════

import * as hitachi from './hitachi';
import { now as clydeNow, isRunning as clydeRunning } from './clyde.js';

const RING_COUNT = 4;
const VOICES_PER_RING = 12;
export const KITSUNE_CHANNELS = RING_COUNT * VOICES_PER_RING; // 48
const SMOOTH_TC = 0.03; // click-free real-time moves
const SPEED_OF_SOUND = 343; // m/s — ring 3/4 propagation delay

// Ring acoustic modeling (native nodes only).
const RING_DEFS = {
  1: { name: 'CORE',       distRange: [0.5, 3],  defDist: 1.5,  lpHz: 20000, delay: false, send: 0.12 },
  2: { name: 'MID-FIELD',  distRange: [3, 10],   defDist: 6,    lpHz: 12000, delay: false, send: 0.25 },
  3: { name: 'HIGH-FIELD', distRange: [10, 25],  defDist: 16,   lpHz: 6000,  delay: true,  send: 0.45 },
  4: { name: 'ULTRA-FIELD',distRange: [25, 80],  defDist: 35,   lpHz: 3000,  delay: true,  send: 0.80 },
};
export const KITSUNE_RINGS = Object.fromEntries(
  Object.entries(RING_DEFS).map(([k, v]) => [k, v.name])
);

let ctx = null;
let ownContext = true;
let master = null;
let masterAnalyser = null;
let convolver = null;
let reverbReturn = null;
let resBank = null; // Web-Tuned Resonance: { filters:[3 bandpass], resGain, state }
let rings = {};     // ring -> { nodes..., state }
let voices = {};    // "ring:ch" -> { nodes..., state }
let meterScratch = null;
let hitachiFeed = []; // [{ stripNode, voiceInput }] live connections
let testTones = {};   // "ring:ch" -> { osc, oscGain }

function makeImpulse(context, seconds = 2.2, decay = 3.0) {
  const rate = context.sampleRate;
  const len = Math.floor(rate * seconds);
  const buf = context.createBuffer(2, len, rate);
  for (let c = 0; c < 2; c++) {
    const data = buf.getChannelData(c);
    for (let i = 0; i < len; i++) {
      data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, decay);
    }
  }
  return buf;
}

function azElDistToXYZ(azDeg, elDeg, dist) {
  const az = (azDeg * Math.PI) / 180;
  const el = (elDeg * Math.PI) / 180;
  return {
    x: dist * Math.cos(el) * Math.sin(az),
    y: dist * Math.sin(el),
    z: -dist * Math.cos(el) * Math.cos(az),
  };
}

function applyVoice(v) {
  if (!ctx) return;
  const t = ctx.currentTime;
  const { x, y, z } = azElDistToXYZ(v.state.azimuth, v.state.elevation, v.state.distance);
  v.panner.positionX.setTargetAtTime(x, t, SMOOTH_TC);
  v.panner.positionY.setTargetAtTime(y, t, SMOOTH_TC);
  v.panner.positionZ.setTargetAtTime(z, t, SMOOTH_TC);
  if (v.delay) v.delay.delayTime.setTargetAtTime(
    Math.min(0.5, v.state.distance / SPEED_OF_SOUND), t, SMOOTH_TC
  );
  v.voiceGain.gain.setTargetAtTime(v.state.audible ? Math.max(v.state.gain, 0.0001) : 0.0001, t, SMOOTH_TC);
}

function applyRing(r) {
  if (!ctx) return;
  const t = ctx.currentTime;
  r.ringGain.gain.setTargetAtTime(r.state.audible ? Math.max(r.state.gain, 0.0001) : 0.0001, t, SMOOTH_TC);
  r.lowTrim.gain.setTargetAtTime(Math.max(r.state.bandGains.low, 0.0001), t, SMOOTH_TC);
  r.midTrim.gain.setTargetAtTime(Math.max(r.state.bandGains.mid, 0.0001), t, SMOOTH_TC);
  r.highTrim.gain.setTargetAtTime(Math.max(r.state.bandGains.high, 0.0001), t, SMOOTH_TC);
  r.send.gain.setTargetAtTime(r.state.audible ? RING_DEFS[r.n].send : 0.0001, t, SMOOTH_TC);
}

function recomputeAudibility() {
  const anySolo = Object.values(rings).some((r) => r.state.solo);
  for (const key of Object.keys(rings)) {
    const r = rings[key];
    r.state.audible = !r.state.mute && (!anySolo || r.state.solo);
    applyRing(r);
    for (let ch = 1; ch <= VOICES_PER_RING; ch++) {
      const v = voices[`${key}:${ch}`];
      v.state.audible = r.state.audible && !v.state.mute;
      applyVoice(v);
    }
  }
}

/**
 * Create/resume the engine. MUST be called from a user gesture.
 * Pass { context } to share an AudioContext (e.g. hitachi.getContext() for
 * the HITACHI feed); otherwise KITSUNE creates and owns its own.
 */
export async function init({ context } = {}) {
  if (ctx && ctx.state !== 'closed') {
    if (ctx.state === 'suspended') await ctx.resume();
    return engineStatus();
  }
  if (context && context.state !== 'closed') {
    ctx = context;
    ownContext = false;
  } else {
    ctx = new (window.AudioContext || window.webkitAudioContext)();
    ownContext = true;
  }

  master = ctx.createGain();
  master.gain.value = 0.9;
  masterAnalyser = ctx.createAnalyser();
  masterAnalyser.fftSize = 256;
  master.connect(masterAnalyser);
  masterAnalyser.connect(ctx.destination);

  // Shared generated-impulse reverb (no external audio files, ever).
  convolver = ctx.createConvolver();
  convolver.buffer = makeImpulse(ctx);
  reverbReturn = ctx.createGain();
  reverbReturn.gain.value = 0.9;
  convolver.connect(reverbReturn);
  reverbReturn.connect(master);

  // Web-Tuned Resonance: parallel sympathetic bandpass bank on the master.
  // 3 harmonically-stacked resonators; freq/Q/gain set live from the web UI.
  const resIn = ctx.createGain();
  resIn.gain.value = 1;
  master.connect(resIn);
  const resGain = ctx.createGain();
  resGain.gain.value = 0;
  const filters = [1, 2, 3].map((mult) => {
    const f = ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.frequency.value = 440 * mult;
    f.Q.value = 8;
    const g = ctx.createGain();
    g.gain.value = 0.33;
    resIn.connect(f);
    f.connect(g);
    g.connect(resGain);
    return { f, mult };
  });
  resGain.connect(master); // parallel sympathetic path
  resBank = { filters, resGain, state: { freq: 440, q: 8, gain: 0 } };

  // Ring buses: 3-band crossover (Internal Multi-Band Transducer) per ring.
  rings = {};
  for (let r = 1; r <= RING_COUNT; r++) {
    const xoverIn = ctx.createGain();
    const lowF = ctx.createBiquadFilter();  lowF.type = 'lowpass';  lowF.frequency.value = 250;
    const midHP = ctx.createBiquadFilter(); midHP.type = 'highpass'; midHP.frequency.value = 250;
    const midLP = ctx.createBiquadFilter(); midLP.type = 'lowpass';  midLP.frequency.value = 4000;
    const highF = ctx.createBiquadFilter(); highF.type = 'highpass'; highF.frequency.value = 4000;
    const lowTrim = ctx.createGain();
    const midTrim = ctx.createGain();
    const highTrim = ctx.createGain();
    const ringGain = ctx.createGain();
    const analyser = ctx.createAnalyser();
    analyser.fftSize = 256;
    const send = ctx.createGain();
    send.gain.value = RING_DEFS[r].send;

    xoverIn.connect(lowF);  lowF.connect(lowTrim);  lowTrim.connect(ringGain);
    xoverIn.connect(midHP); midHP.connect(midLP);   midLP.connect(midTrim); midTrim.connect(ringGain);
    xoverIn.connect(highF); highF.connect(highTrim); highTrim.connect(ringGain);
    ringGain.connect(analyser);
    analyser.connect(master);
    ringGain.connect(send);
    send.connect(convolver);

    rings[r] = {
      n: r, xoverIn, lowTrim, midTrim, highTrim, ringGain, analyser, send,
      state: { gain: 0.8, mute: false, solo: false, audible: true,
               bandGains: { low: 1.0, mid: 1.0, high: 1.0 } },
    };
  }

  // 48 voices: input (insert point) → panner (HRTF) → ring air/delay modeling
  // → voice gain → analyser → ring crossover input. Silent until a source
  // attaches — nothing auto-plays.
  voices = {};
  for (let r = 1; r <= RING_COUNT; r++) {
    const def = RING_DEFS[r];
    for (let ch = 1; ch <= VOICES_PER_RING; ch++) {
      const input = ctx.createGain();
      const panner = ctx.createPanner();
      panner.panningModel = 'HRTF';
      panner.distanceModel = 'inverse';
      panner.refDistance = 1;
      const lp = ctx.createBiquadFilter();
      lp.type = 'lowpass';
      lp.frequency.value = def.lpHz;
      const delay = def.delay ? ctx.createDelay(1.0) : null;
      const voiceGain = ctx.createGain();
      voiceGain.gain.value = 0.0001;
      const analyser = ctx.createAnalyser();
      analyser.fftSize = 256;

      input.connect(panner);
      panner.connect(lp);
      if (delay) { lp.connect(delay); delay.connect(voiceGain); }
      else { lp.connect(voiceGain); }
      voiceGain.connect(analyser);
      analyser.connect(rings[r].xoverIn);

      const state = {
        azimuth: (((ch - 1) * 30 + 180) % 360) - 180, elevation: 0, distance: def.defDist,
        gain: 0.8, mute: false, audible: true,
      };
      const v = { ring: r, ch, input, panner, lp, delay, voiceGain, analyser, state };
      voices[`${r}:${ch}`] = v;
      applyVoice(v);
    }
  }

  meterScratch = new Uint8Array(256);
  if (ctx.state === 'suspended') await ctx.resume();
  return engineStatus();
}

function getVoice(ring, ch) {
  return voices[`${ring}:${ch}`] || null;
}

/**
 * Live-update one voice. ring 1..4, ch 1..12.
 * azimuth −180..180°, elevation −90..90°, distance clamped to the ring field.
 */
export function setVoice(ring, ch, { azimuth, elevation, distance, gain, mute } = {}) {
  const v = getVoice(ring, ch);
  if (!v) return;
  const s = v.state;
  const def = RING_DEFS[ring];
  if (azimuth !== undefined) s.azimuth = Math.max(-180, Math.min(180, azimuth));
  if (elevation !== undefined) s.elevation = Math.max(-90, Math.min(90, elevation));
  if (distance !== undefined) s.distance = Math.max(def.distRange[0], Math.min(def.distRange[1], distance));
  if (gain !== undefined) s.gain = Math.max(0, Math.min(1.5, gain));
  if (mute !== undefined) {
    s.mute = !!mute;
    const r = rings[ring];
    s.audible = r.state.audible && !s.mute;
  }
  if (ctx) applyVoice(v);
}

/**
 * Flat channel addressing per the KITSUNE spec sheet channel roles:
 *   channels 1–12  → Ring 1 (Core Resonance)
 *   channels 13–24 → Ring 2 (Mid-Field)
 *   channels 25–36 → Ring 3 (High-Field)
 *   channels 37–48 → Ring 4 (Ultra-Field)
 */
export function channelToVoice(n) {
  if (!Number.isInteger(n) || n < 1 || n > KITSUNE_CHANNELS) {
    throw new RangeError(`channel must be 1..${KITSUNE_CHANNELS}`);
  }
  return {
    ring: 1 + Math.floor((n - 1) / VOICES_PER_RING),
    ch: ((n - 1) % VOICES_PER_RING) + 1,
  };
}

/**
 * Live-update one channel by flat number (1..48). Same params as setVoice.
 */
export function setChannel(n, params = {}) {
  const { ring, ch } = channelToVoice(n);
  return setVoice(ring, ch, params);
}

/**
 * Insert node for one channel by flat number (1..48).
 */
export function getChannelInput(n) {
  const { ring, ch } = channelToVoice(n);
  return getVoiceInput(ring, ch);
}

/**
 * Ring-level control. bandGains: { low, mid, high } trims 0..2.
 */
export function setRing(ring, { gain, mute, solo, bandGains } = {}) {
  const r = rings[ring];
  if (!r) return;
  const s = r.state;
  if (gain !== undefined) s.gain = Math.max(0, Math.min(1.5, gain));
  let audChanged = false;
  if (mute !== undefined && !!mute !== s.mute) { s.mute = !!mute; audChanged = true; }
  if (solo !== undefined && !!solo !== s.solo) { s.solo = !!solo; audChanged = true; }
  if (bandGains) {
    for (const band of ['low', 'mid', 'high']) {
      if (bandGains[band] !== undefined) {
        s.bandGains[band] = Math.max(0, Math.min(2, bandGains[band]));
      }
    }
  }
  if (!ctx) return;
  if (audChanged) recomputeAudibility();
  else applyRing(r);
}

/** Web-Tuned Resonance: sympathetic bandpass bank on the master. */
export function setResonance({ freq, q, gain } = {}) {
  if (!resBank) return;
  const s = resBank.state;
  if (freq !== undefined) s.freq = Math.max(40, Math.min(12000, freq));
  if (q !== undefined) s.q = Math.max(0.5, Math.min(40, q));
  if (gain !== undefined) s.gain = Math.max(0, Math.min(1.5, gain));
  if (!ctx) return;
  const t = ctx.currentTime;
  for (const { f, mult } of resBank.filters) {
    f.frequency.setTargetAtTime(Math.min(20000, s.freq * mult), t, SMOOTH_TC);
    f.Q.setTargetAtTime(s.q, t, SMOOTH_TC);
  }
  resBank.resGain.gain.setTargetAtTime(s.gain, t, SMOOTH_TC);
}

/** RMS per ring, 0..1. Zeros when the engine is off. */
export function getRingLevels() {
  const out = [0, 0, 0, 0];
  if (!ctx || ctx.state === 'closed') return out;
  const buf = meterScratch;
  for (let r = 1; r <= RING_COUNT; r++) {
    rings[r].analyser.getByteTimeDomainData(buf);
    let sum = 0;
    for (let j = 0; j < buf.length; j++) {
      const v = (buf[j] - 128) / 128;
      sum += v * v;
    }
    out[r - 1] = Math.min(1, Math.sqrt(sum / buf.length) * 2.2);
  }
  return out;
}

/** RMS per voice (48, ring-major order), 0..1. Zeros when off. */
export function getVoiceLevels() {
  const out = new Array(KITSUNE_CHANNELS).fill(0);
  if (!ctx || ctx.state === 'closed') return out;
  const buf = meterScratch;
  let i = 0;
  for (let r = 1; r <= RING_COUNT; r++) {
    for (let ch = 1; ch <= VOICES_PER_RING; ch++) {
      voices[`${r}:${ch}`].analyser.getByteTimeDomainData(buf);
      let sum = 0;
      for (let j = 0; j < buf.length; j++) {
        const v = (buf[j] - 128) / 128;
        sum += v * v;
      }
      out[i++] = Math.min(1, Math.sqrt(sum / buf.length) * 2.2);
    }
  }
  return out;
}

/** Insert point for a voice's audio source (HITACHI tap, oscillator…). */
export function getVoiceInput(ring, ch) {
  const v = getVoice(ring, ch);
  return v ? v.input : null;
}

/**
 * Feed HITACHI's 24 strip insert nodes into KITSUNE voices.
 * Requires the shared AudioContext (init via the HITACHI feed toggle);
 * refuses with a reason otherwise — cross-context connects throw.
 * Default map: strip n → ring 1+floor((n−1)/12), ch ((n−1)%12)+1.
 */
export function attachHitachiFeed(map) {
  if (!ctx) return { ok: false, reason: 'kitsune-off' };
  const hctx = hitachi.getContext ? hitachi.getContext() : null;
  if (!hctx || hctx !== ctx) {
    return {
      ok: false,
      reason: 'context-mismatch',
      hint: 'Power KITSUNE via the HITACHI feed toggle so both engines share one AudioContext.',
    };
  }
  detachHitachiFeed();
  const routes = map || Array.from({ length: 24 }, (_, i) => ({
    strip: i + 1,
    ring: 1 + Math.floor(i / 12),
    ch: (i % 12) + 1,
  }));
  let connected = 0;
  for (const { strip, ring, ch } of routes) {
    const src = hitachi.getStripInput(strip);
    const dst = getVoiceInput(ring, ch);
    if (src && dst) {
      try {
        src.connect(dst);
        hitachiFeed.push({ src, dst });
        connected++;
      } catch (e) { /* skip unroutable strip */ }
    }
  }
  return { ok: true, connected, total: routes.length };
}

export function detachHitachiFeed() {
  for (const { src, dst } of hitachiFeed) {
    try { src.disconnect(dst); } catch (e) { /* already gone */ }
  }
  hitachiFeed = [];
  return { detached: true };
}

/**
 * Test tone on a voice — explicit user action only (the engine never
 * auto-plays). Toggles: call again to silence.
 */
export function toggleTestTone(ring, ch, freq = 440) {
  const key = `${ring}:${ch}`;
  if (testTones[key]) {
    try { testTones[key].osc.stop(); } catch (e) { /* noop */ }
    try { testTones[key].osc.disconnect(); } catch (e) { /* noop */ }
    delete testTones[key];
    return { tone: false };
  }
  if (!ctx) return { tone: false, reason: 'kitsune-off' };
  const v = getVoice(ring, ch);
  if (!v) return { tone: false };
  const osc = ctx.createOscillator();
  osc.type = 'sine';
  osc.frequency.value = freq;
  const g = ctx.createGain();
  g.gain.value = 0.25;
  osc.connect(g);
  g.connect(v.input);
  osc.start();
  testTones[key] = { osc, gain: g };
  return { tone: true, freq };
}

export function engineStatus() {
  const running = !!ctx && ctx.state === 'running';
  return {
    running,
    sampleRate: ctx ? ctx.sampleRate : 0,
    baseLatency: ctx && ctx.baseLatency != null ? Number(ctx.baseLatency.toFixed(4)) : 0,
    channels: KITSUNE_CHANNELS,
    rings: RING_COUNT,
    hrtf: true,
    hitachiFeed: hitachiFeed.length > 0,
    sharedContext: ctx ? !ownContext : false,
    clyde: { port: 'ready', spec: 'pending' },
    name: 'KITSUNE',
  };
}

export async function shutdown() {
  detachHitachiFeed();
  for (const key of Object.keys(testTones)) {
    try { testTones[key].osc.stop(); } catch (e) { /* noop */ }
  }
  testTones = {};
  // Only close contexts KITSUNE owns — never kill a shared HITACHI context.
  if (ctx && ownContext) {
    try { await ctx.close(); } catch (e) { /* noop */ }
  }
  ctx = null; ownContext = true;
  master = null; masterAnalyser = null; convolver = null; reverbReturn = null;
  resBank = null; rings = {}; voices = {}; meterScratch = null;
  return engineStatus();
}

// ═══════════════════════════════════════════════════════════════════════════════
// CLYDE sync port — Virtual HDMI Sync interface.
//
// CLYDE sync port — LIVE (src/lib/clyde.js).
// The port shape is unchanged ({protocol, channelMap, avOffsetMs,
// getTimestamp()}) so every consumer keeps working. getTimestamp() now
// prefers the real CLYDE master clock when the engine is running, falling
// back to the engine-local AudioContext clock otherwise.
// ═══════════════════════════════════════════════════════════════════════════════
export const clydeSync = {
  protocol: 'CLYDE-1',
  channelMap: Array.from({ length: KITSUNE_CHANNELS }, (_, i) => ({
    index: i,
    ring: 1 + Math.floor(i / VOICES_PER_RING),
    ch: (i % VOICES_PER_RING) + 1,
  })),
  _avOffsetMs: 0,
  get avOffsetMs() { return this._avOffsetMs; },
  set avOffsetMs(ms) { this._avOffsetMs = Math.max(-500, Math.min(500, Number(ms) || 0)); },
  /** CLYDE master-clock timestamp (seconds). Falls back to engine-local clock. */
  getTimestamp() {
    try {
      if (clydeRunning()) return clydeNow();
    } catch (err) { /* fall through to local clock */ }
    return ctx ? ctx.currentTime : 0;
  },
};
