export const HOME_SEAL = { id: 'home', label: 'Home', icon: Home, home: '/', routes: ['/'] };

const JEWEL_STYLES = {
  gold:     { text: 'text-gold-400',  bg: 'bg-gold-500/10',  ring: 'ring-gold-500/30' },
  amethyst: { text: 'text-amethyst-400', bg: 'bg-amethyst-500/10', ring: 'ring-amethyst-500/30' },
  ruby:     { text: 'text-ruby-500',  bg: 'bg-ruby-500/10',  ring: 'ring-ruby-500/30' },
  rose:     { text: 'text-rosequartz-300', bg: 'bg-rosequartz-500/10', ring: 'ring-rosequartz-500/30' },
  sapphire: { text: 'text-sapphire-400', bg: 'bg-sapphire-500/10', ring: 'ring-sapphire-500/30' },
};

export function jewelStyle(jewel = 'gold') {
  return JEWEL_STYLES[jewel] || JEWEL_STYLES.gold;
}

// ── Wordmark ──────────────────────────────────────────────────────────────
export function Wordmark({ compact = false }) {
  return (
    <span className="flex flex-col leading-none select-none">
      <span
        className={cn(
          'font-display font-bold tracking-wide text-gold-400',
          compact ? 'text-lg' : 'text-2xl'
        )}
        style={{ fontFamily: 'var(--sv-font-display)' }}
      >
        Benny&rsquo;s Studio
      </span>
      {!compact && (
        <span className="mt-1 text-[10px] font-semibold uppercase tracking-[0.28em] text-ink-mute">
          Sovereign Creative Forge
        </span>
      )}
    </span>
  );
}

// ── PageHeader — the one header pattern for every page ─────────────────────
export function PageHeader({ icon: Icon, kicker, title, description, actions, jewel = 'gold' }) {
  const j = jewelStyle(jewel);
  return (
    <header className="mb-8">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div className="flex items-start gap-4 min-w-0">
          {Icon && (
            <span className={cn('mt-1 inline-flex h-11 w-11 shrink-0 items-center justify-center rounded-svlg ring-1', j.bg, j.ring, j.text)}>
              <Icon className="h-5 w-5" aria-hidden />
            </span>
          )}
          <div className="min-w-0">
            {kicker && (
              <p className="text-xs font-semibold uppercase tracking-[0.22em] text-ink-mute">{kicker}</p>
            )}
            <h1
              className="mt-1 text-3xl font-bold tracking-tight text-ink"
              style={{ fontFamily: 'var(--sv-font-display)' }}
            >
              {title}
            </h1>
            {description && (
              <p className="mt-2 max-w-2xl text-sm leading-relaxed text-ink-dim">{description}</p>
            )}
          </div>
        </div>
        {actions && <div className="flex shrink-0 items-center gap-2">{actions}</div>}
      </div>
    </header>
  );
}
