/**
 * EmporiumCruisesCarsEvents.jsx — three result sections in one file.
 * Route determines the section: /emporium/cruises | /cars | /events.
 * Each pulls its own endpoint: /api/emporium/travel/{cruises|cars|events}.
 */
import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { useApiGet, asArray, pick } from './emporiumApi';
import { Rivets, LoadingState, EmptyState, ErrorState, Kv } from './montiff-ui';

const SECTIONS = [
  { key: 'cruises', path: '/emporium/cruises', label: 'CRUISES', headline: 'SALT, STEEL & SEVEN SEAS', testid: 'cce-tab-cruises' },
  { key: 'cars', path: '/emporium/cars', label: 'CARS', headline: 'EV + PETROL · KEYS IN HAND', testid: 'cce-tab-cars' },
  { key: 'events', path: '/emporium/events', label: 'EVENTS', headline: 'FRONT ROW, EVERY NIGHT', testid: 'cce-tab-events' },
];

function cardFields(section, item) {
  if (section === 'cruises') {
    return [
      ['SHIP', pick(item, ['ship', 'name', 'title'], '—')],
      ['LINE', pick(item, ['line', 'cruise_line', 'vendor'], '—')],
      ['ITINERARY', pick(item, ['itinerary', 'route', 'ports'], '—')],
      ['SAILING', pick(item, ['sailing_date', 'departure', 'date'], '—')],
      ['FARE', pick(item, ['fare', 'price', 'amount'], '—')],
    ];
  }
  if (section === 'cars') {
    return [
      ['VEHICLE', pick(item, ['vehicle', 'name', 'model', 'title'], '—')],
      ['AGENCY', pick(item, ['agency', 'vendor', 'provider'], '—')],
      ['POWERTRAIN', pick(item, ['powertrain', 'fuel', 'type'], '—')],
      ['PICKUP', pick(item, ['pickup', 'location', 'city'], '—')],
      ['DAILY', pick(item, ['daily_rate', 'price', 'rate'], '—')],
    ];
  }
  return [
    ['EVENT', pick(item, ['event', 'name', 'title'], '—')],
    ['VENUE', pick(item, ['venue', 'location'], '—')],
    ['DATE', pick(item, ['date', 'event_date'], '—')],
    ['CATEGORY', pick(item, ['category', 'kind'], '—')],
    ['TICKET', pick(item, ['ticket_price', 'price', 'amount'], '—')],
  ];
}

export default function EmporiumCruisesCarsEvents() {
  const { pathname } = useLocation();
  const section = SECTIONS.find((s) => pathname.startsWith(s.path)) || SECTIONS[0];
  const { data, loading, error, reload } = useApiGet(`/api/emporium/travel/${section.key}`, [section.key]);
  const items = asArray(data);

  return (
    <div className="montiff-page montiff-stack" data-testid={`emporium-${section.key}`}>
      <section className="montiff-panel" data-testid="cce-header">
        <Rivets />
        <div className="montiff-tabs" data-testid="cce-section-tabs" role="tablist" aria-label="Travel sections">
          {SECTIONS.map((s) => (
            <Link
              key={s.key}
              to={s.path}
              role="tab"
              aria-selected={s.key === section.key}
              data-testid={s.testid}
              className={`montiff-tab${s.key === section.key ? ' active' : ''}`}
            >
              {s.label}
            </Link>
          ))}
        </div>
        <h1 className="montiff-h" style={{ marginTop: 12 }}>{section.headline}</h1>
        <p className="montiff-muted" style={{ margin: 0 }}>
          Sovereign-mocked inventory — live vendor welds flip these to real availability.
        </p>
      </section>

      {loading && <LoadingState label={`LOADING ${section.label} MANIFEST…`} />}
      {error && <ErrorState message={error} onRetry={reload} testid={`cce-error-${section.key}`} />}
      {!loading && !error && items.length === 0 && (
        <EmptyState label={`NO ${section.label} ON THE WIRE YET`} testid={`cce-empty-${section.key}`} />
      )}
      {!loading && !error && items.length > 0 && (
        <div className="montiff-grid" data-testid={`cce-grid-${section.key}`}>
          {items.map((item, i) => {
            const fields = cardFields(section.key, item);
            return (
              <div className="montiff-card" key={pick(item, ['id'], i)} data-testid={`cce-card-${section.key}-${i}`}>
                <div className="montiff-h-sm" style={{ margin: 0 }}>{fields[0][1]}</div>
                <div>
                  {fields.slice(1).map(([k, v]) => (
                    <Kv key={k} k={k} v={String(v)} />
                  ))}
                </div>
                <Link
                  className="montiff-btn small"
                  data-testid={`cce-book-link-${section.key}-${i}`}
                  to="/emporium/booking"
                  style={{ marginTop: 'auto', textAlign: 'center' }}
                >
                  BOOK VIA COMMAND CENTER
                </Link>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
