/**
 * EmporiumLedger.jsx — commission dashboard.
 * GET /api/emporium/ledger/summary + /entries · simulate form → POST /simulate.
 */
import React, { useState } from 'react';
import { useApiGet, apiPost, asArray, pick } from './emporiumApi';
import { Rivets, LoadingState, EmptyState, ErrorState, Readout, Kv } from './montiff-ui';

const COMMISSION_DEFAULTS = { airlines: 5, hotels: 10, cruises: 14, cars: 7, events: 8 };
const KINDS = Object.keys(COMMISSION_DEFAULTS);

export default function EmporiumLedger() {
  const summary = useApiGet('/api/emporium/ledger/summary');
  const entries = useApiGet('/api/emporium/ledger/entries');
  const [sim, setSim] = useState({ kind: 'hotels', amount: 1000, tier: 'BRONZE' });
  const [simResult, setSimResult] = useState(null);
  const [simBusy, setSimBusy] = useState(false);
  const [simError, setSimError] = useState(null);

  const s = summary.data || {};
  const rows = asArray(entries.data);

  async function runSimulation(e) {
    e.preventDefault();
    setSimBusy(true);
    setSimError(null);
    setSimResult(null);
    const r = await apiPost('/api/emporium/ledger/simulate', {
      kind: sim.kind,
      amount: Number(sim.amount) || 0,
      tier: sim.tier,
    });
    setSimBusy(false);
    if (r.ok) setSimResult(r.data);
    else setSimError(r.error);
  }

  const totals = [
    { label: 'LIFETIME COMMISSION', value: fmt(pick(s, ['total_commission', 'total', 'lifetime_commission'], '—')), testid: 'ledger-stat-total' },
    { label: 'PENDING PAYOUT', value: fmt(pick(s, ['pending', 'pending_payout', 'unpaid'], '—')), testid: 'ledger-stat-pending' },
    { label: 'PAID OUT', value: fmt(pick(s, ['paid', 'paid_out', 'disbursed'], '—')), testid: 'ledger-stat-paid' },
    { label: 'ENTRIES', value: pick(s, ['entry_count', 'count', 'entries'], rows.length || '—'), testid: 'ledger-stat-entries' },
  ];

  return (
    <div className="montiff-page montiff-stack" data-testid="emporium-ledger">
      <section className="montiff-panel" data-testid="ledger-header">
        <Rivets />
        <div className="montiff-brand" style={{ color: 'var(--montiff-green)' }}>EVERY COIN ACCOUNTED</div>
        <h1 className="montiff-h">COMMISSION LEDGER</h1>
        <p className="montiff-muted" style={{ margin: 0 }}>
          Bookings auto-sync here. House rates — airlines 5% · hotels 10% · cruises 14% · cars 7% · events 8%.
        </p>
      </section>

      {summary.loading ? (
        <LoadingState label="AUDITING THE BOOKS…" />
      ) : summary.error ? (
        <ErrorState message={summary.error} onRetry={summary.reload} testid="ledger-summary-error" />
      ) : (
        <section className="montiff-grid" data-testid="ledger-totals" style={{ gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))' }}>
          {totals.map((t) => (
            <div className="montiff-panel" key={t.label} data-testid={t.testid}>
              <Rivets />
              <Readout label={t.label} value={t.value} />
            </div>
          ))}
        </section>
      )}

      <section className="montiff-grid-2" data-testid="ledger-lower">
        {/* Entries */}
        <div className="montiff-panel" data-testid="ledger-entries-panel">
          <Rivets />
          <div className="montiff-h-sm">LEDGER ENTRIES</div>
          {entries.loading && <LoadingState label="PULLING ENTRIES…" />}
          {entries.error && <ErrorState message={entries.error} onRetry={entries.reload} testid="ledger-entries-error" />}
          {!entries.loading && !entries.error && rows.length === 0 && (
            <EmptyState label="LEDGER IS CLEAN — NO ENTRIES YET" testid="ledger-entries-empty" />
          )}
          {!entries.loading && !entries.error && rows.length > 0 && (
            <div className="montiff-table-wrap" data-testid="ledger-entries-table-wrap">
              <table className="montiff-table" data-testid="ledger-entries-table">
                <thead><tr><th>ID</th><th>KIND</th><th>AMOUNT</th><th>COMMISSION</th><th>STATUS</th></tr></thead>
                <tbody>
                  {rows.slice(0, 25).map((r, i) => (
                    <tr key={pick(r, ['id', 'entry_id'], i)} data-testid={`ledger-entry-${i}`}>
                      <td className="montiff-readout" style={{ fontSize: 12 }}>{String(pick(r, ['id', 'entry_id'], i)).slice(0, 10)}</td>
                      <td>{pick(r, ['kind', 'type', 'category'], '—')}</td>
                      <td className="montiff-readout">{fmt(pick(r, ['amount', 'total', 'gross'], '—'))}</td>
                      <td className="montiff-readout" style={{ color: 'var(--montiff-green)', fontWeight: 700 }}>{fmt(pick(r, ['commission', 'commission_earned'], '—'))}</td>
                      <td>{pick(r, ['status', 'state'], '—')}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {/* Simulator */}
        <div className="montiff-panel-blue" data-testid="ledger-simulator">
          <Rivets />
          <div className="montiff-h-sm" style={{ color: '#fff' }}>COMMISSION SIMULATOR</div>
          <p className="montiff-readout" style={{ fontSize: 12, color: 'var(--montiff-steel-400)' }}>
            Dry-run a booking through the house rates before it welds.
          </p>
          <form onSubmit={runSimulation} data-testid="ledger-simulate-form">
            <div className="montiff-form-row">
              <div className="montiff-field">
                <label className="montiff-label" style={{ color: '#fff' }}>KIND</label>
                <select className="montiff-select" data-testid="ledger-sim-kind-select" value={sim.kind} onChange={(e) => setSim({ ...sim, kind: e.target.value })}>
                  {KINDS.map((k) => <option key={k} value={k}>{k.toUpperCase()} · {COMMISSION_DEFAULTS[k]}%</option>)}
                </select>
              </div>
              <div className="montiff-field">
                <label className="montiff-label" style={{ color: '#fff' }}>AMOUNT ($)</label>
                <input type="number" min="0" className="montiff-input" data-testid="ledger-sim-amount-input" value={sim.amount} onChange={(e) => setSim({ ...sim, amount: e.target.value })} />
              </div>
              <div className="montiff-field">
                <label className="montiff-label" style={{ color: '#fff' }}>TIER</label>
                <select className="montiff-select" data-testid="ledger-sim-tier-select" value={sim.tier} onChange={(e) => setSim({ ...sim, tier: e.target.value })}>
                  {['BRONZE', 'GOLD', 'PLATINUM'].map((t) => <option key={t} value={t}>{t}</option>)}
                </select>
              </div>
            </div>
            <button type="submit" className="montiff-btn" data-testid="ledger-simulate-button" disabled={simBusy}>
              {simBusy ? 'CRUNCHING…' : 'SIMULATE'}
            </button>
          </form>
          {simError && <ErrorState message={simError} testid="ledger-simulate-error" />}
          {simResult && (
            <div style={{ marginTop: 14, background: '#fff', border: '3px solid var(--montiff-green)', padding: 12 }} data-testid="ledger-simulate-result">
              <Kv k="BOOKING VALUE" v={fmt(pick(simResult, ['amount', 'gross', 'total'], sim.amount))} />
              <Kv k="HOUSE RATE" v={pick(simResult, ['rate', 'commission_rate', 'pct'], `${COMMISSION_DEFAULTS[sim.kind]}%`)} />
              <Kv k="COMMISSION" v={fmt(pick(simResult, ['commission', 'commission_earned', 'payout'], '—'))} />
              <Kv k="TIER" v={pick(simResult, ['tier'], sim.tier)} />
            </div>
          )}
        </div>
      </section>
    </div>
  );
}

function fmt(v) {
  const n = Number(v);
  if (!Number.isFinite(n)) return v === '—' ? '—' : String(v);
  return '$' + n.toLocaleString('en-US', { maximumFractionDigits: 2 });
}
