/**
 * EmporiumDashboard.jsx — "Flight Desk v.86" hero.
 * Stat readouts from /api/emporium/travel/dashboard + foundation health.
 */
import React from 'react';
import { Link } from 'react-router-dom';
import { useApiGet, pick, asArray } from './emporiumApi';
import { Rivets, LoadingState, EmptyState, ErrorState, Readout } from './montiff-ui';

function StatPanel({ title, stats, testid }) {
  return (
    <div className="montiff-panel" data-testid={testid}>
      <Rivets />
      <div className="montiff-h-sm">{title}</div>
      <div className="montiff-grid-2" style={{ gridTemplateColumns: 'repeat(auto-fit, minmax(140px, 1fr))' }}>
        {stats.map((s) => (
          <Readout key={s.label} label={s.label} value={s.value} testid={s.testid} />
        ))}
      </div>
    </div>
  );
}

export default function EmporiumDashboard() {
  const dash = useApiGet('/api/emporium/travel/dashboard');
  const health = useApiGet('/api/emporium/foundation/health');
  const sources = useApiGet('/api/emporium/travel/sources');

  const d = dash.data || {};
  const h = health.data || {};
  const srcList = asArray(sources.data);

  const travelStats = [
    { label: 'BOOKINGS', value: pick(d, ['bookings', 'total_bookings', 'booking_count'], '—'), testid: 'dashboard-stat-bookings' },
    { label: 'REVENUE', value: pick(d, ['revenue', 'total_revenue', 'gross'], '—'), testid: 'dashboard-stat-revenue' },
    { label: 'SEARCHES', value: pick(d, ['searches', 'total_searches'], '—'), testid: 'dashboard-stat-searches' },
    { label: 'MANIFESTS', value: pick(d, ['manifests', 'total_manifests'], '—'), testid: 'dashboard-stat-manifests' },
  ];
  const foundationStats = [
    { label: 'MACH BASELINE', value: pick(h, ['mach_baseline', 'mach', 'baseline_mach'], '2.04'), testid: 'dashboard-stat-mach' },
    { label: 'HUBS', value: pick(h, ['hubs', 'hub_count'], '—'), testid: 'dashboard-stat-hubs' },
    { label: 'ATLAS PORTS', value: pick(h, ['airports', 'airport_count', 'atlas_size'], '—'), testid: 'dashboard-stat-airports' },
    { label: 'ENGINE', value: pick(h, ['status', 'engine_status'], '—'), testid: 'dashboard-stat-engine' },
  ];

  return (
    <div className="montiff-page montiff-stack" data-testid="emporium-dashboard">
      {/* Hero */}
      <section className="montiff-hero" data-testid="flight-desk-hero">
        <Rivets />
        <div className="montiff-brand">FLIGHT DESK v.86</div>
        <h1 className="montiff-h" style={{ color: '#fff', fontSize: 44, marginTop: 10 }}>
          COMMAND THE SKIES, SAILOR.
        </h1>
        <p style={{ color: 'var(--montiff-steel-300)', maxWidth: 620, fontSize: 15 }}>
          The Emporium commerce realm routes every journey through the Sovereign Foundation —
          search, book, assemble itineraries, and watch commissions weld into the ledger.
        </p>
        <div className="montiff-row" style={{ marginTop: 16 }}>
          <Link className="montiff-btn" data-testid="dashboard-book-now-button" to="/emporium/booking">BOOK NOW</Link>
          <Link className="montiff-btn secondary" data-testid="dashboard-route-lab-button" to="/emporium/route">ROUTE LAB</Link>
          <Link className="montiff-btn ghost" data-testid="dashboard-vendors-button" to="/emporium/vendors">VENDOR CONSOLE</Link>
        </div>
      </section>
      <div className="montiff-hero-stripes" aria-hidden="true" />

      {/* Stats */}
      {dash.loading ? (
        <LoadingState label="PULLING FLIGHT DESK TELEMETRY…" />
      ) : dash.error ? (
        <ErrorState message={dash.error} onRetry={dash.reload} testid="dashboard-error" />
      ) : (
        <StatPanel title="TRAVEL DESK" stats={travelStats} testid="dashboard-travel-stats" />
      )}

      {health.loading ? (
        <LoadingState label="PINGING SOVEREIGN FOUNDATION…" />
      ) : health.error ? (
        <ErrorState message={health.error} onRetry={health.reload} testid="dashboard-foundation-error" />
      ) : (
        <StatPanel title="FOUNDATION HEALTH" stats={foundationStats} testid="dashboard-foundation-stats" />
      )}

      {/* Sources */}
      <div className="montiff-panel" data-testid="dashboard-sources">
        <Rivets />
        <div className="montiff-h-sm">BOOKING SOURCES</div>
        {sources.loading ? (
          <LoadingState label="LISTING SOURCES…" />
        ) : sources.error ? (
          <ErrorState message={sources.error} onRetry={sources.reload} />
        ) : srcList.length === 0 ? (
          <EmptyState label="NO SOURCES ON THE WIRE YET" testid="dashboard-sources-empty" />
        ) : (
          <div className="montiff-grid" style={{ gridTemplateColumns: 'repeat(auto-fill, minmax(180px, 1fr))' }}>
            {srcList.map((s, i) => (
              <div className="montiff-source-tile" key={pick(s, ['id', 'name'], i)} data-testid={`dashboard-source-${i}`}>
                <div className="montiff-h-sm" style={{ margin: 0 }}>{pick(s, ['name', 'source', 'id'], `SOURCE ${i + 1}`)}</div>
                <div className="montiff-readout montiff-muted" style={{ fontSize: 12 }}>{pick(s, ['kind', 'type', 'category'], '')}</div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
