// Serpent Strike war room — SIMULATION engine.
//
// Used ONLY when the live battalion backend (/api/serpent-strike/live) is
// unreachable — e.g. the static GitHub Pages prototype, which has no backend.
// Every message this module produces is labeled provider: 'simulation' and
// the war room displays a permanent SIMULATION badge in that mode.
//
// Simulation output must NEVER be presented as live battalion output.

import { COMMANDER, XO, SQUADS } from './roster';

const DIRECTIVES = [
  'Push the outbound wedge — Alpha opens forty new conversations before the next tick. No lead left cold.',
  'Bravo converts warm inbound inside the hour. Speed is the weapon; hesitation is the casualty.',
  'Charlie locks renewals — every account gets a human touch this cycle. Nobody drifts.',
  'Delta delivers pipeline truth by the next tick. If the numbers lie, we fix the numbers.',
  'Echo sharpens the message — every proposal that leaves today leaves flawless.',
];

const DEBATE_PAIRINGS = [
  ['alpha', 'bravo', 'cold outbound volume vs warm inbound precision'],
  ['charlie', 'delta', 'relationship instinct vs data-driven targeting'],
  ['echo', 'alpha', 'message craft vs raw outreach volume'],
  ['bravo', 'delta', 'speed-to-lead vs scored prioritization'],
  ['charlie', 'echo', 'retention storytelling vs acquisition firepower'],
];

function stablePick(key, n) {
  let h = 0;
  for (let i = 0; i < key.length; i++) {
    h = (h * 31 + key.charCodeAt(i)) >>> 0;
  }
  return h % Math.max(n, 1);
}

function squadById(id) {
  return SQUADS.find((s) => s.squad_id === id) || SQUADS[0];
}

let simTick = 0;

export function simulateTick() {
  simTick += 1;
  const tick = simTick;
  const now = new Date().toISOString();
  const messages = [];
  const push = (kind, author, text, squad) =>
    messages.push({
      id: `SIM-T${tick}-${kind}-${messages.length}`,
      tick, kind, author, squad: squad || null, text,
      ts: now, provider: 'simulation',
    });

  const directiveText = `Tick ${tick} — ${DIRECTIVES[(tick - 1) % DIRECTIVES.length]} (simulated)`;
  push('directive', COMMANDER.name, directiveText);
  push('relay', XO.name,
    `XO copies tick ${tick} (simulated). Squads, you heard the commander: Alpha and Bravo take point, Charlie holds the line, Delta watches the numbers, Echo arms the message.`);

  for (const squad of SQUADS) {
    const lead = squad.members[0];
    const n = stablePick(`${squad.squad_id}:${tick}`, 12) + 3;
    push('report', `${lead.name} (${lead.callsign})`,
      `${squad.name} reporting (simulated) — ${n} active threads this tick, zero dropped. Standing by for tasking.`,
      squad.name);
  }

  for (let i = 0; i < 2; i++) {
    const [aId, bId, topic] = DEBATE_PAIRINGS[(tick - 1 + i) % DEBATE_PAIRINGS.length];
    const a = squadById(aId);
    const b = squadById(bId);
    push('tactic', `${a.name} vs ${b.name}`,
      `Tactic debate (simulated) — ${a.members[0].callsign} argues for pressure, ${b.members[0].callsign} argues for precision on: ${topic}.`);
  }

  return {
    tick,
    messages,
    provider: 'simulation',
    ts: now,
    directive: { tick, text: directiveText, ts: now, provider: 'simulation' },
  };
}

export function resetSimulation() {
  simTick = 0;
}
