/**
 * EmporiumBooking.jsx — "Search Command Center".
 * Form (kind, origin, destination, dates, passengers, tier)
 * → POST /api/emporium/travel/search → results grid
 * → book → POST /api/emporium/travel/book → confirmation + coin-burst.
 */
import React, { useState } from 'react';
import { apiPost, asArray, pick } from './emporiumApi';
import { Rivets, LoadingState, EmptyState, ErrorState, CoinBurst, Kv } from './montiff-ui';

const KINDS = ['flight', 'hotel', 'cruise', 'car', 'event'];
const TIERS = ['BRONZE', 'GOLD', 'PLATINUM'];

const AIRPORTS = ['JFK', 'LHR', 'CDG', 'NRT', 'DXB', 'SIN', 'LAX', 'MIA', 'HND', 'AMS', 'SYD', 'GRU', 'JNB'];

function Field({ label, testid, children }) {
  return (
    <div className="montiff-field" data-testid={testid}>
      <label className="montiff-label">{label}</label>
      {children}
    </div>
  );
}

export default function EmporiumBooking() {
  const [form, setForm] = useState({
    kind: 'flight',
    origin: 'JFK',
    destination: 'LHR',
    depart: '',
    ret: '',
    passengers: 1,
    tier: 'BRONZE',
  });
  const [results, setResults] = useState(null);
  const [searching, setSearching] = useState(false);
  const [searchError, setSearchError] = useState(null);
  const [booking, setBooking] = useState(null); // in-flight booking target
  const [bookingBusy, setBookingBusy] = useState(false);
  const [bookingError, setBookingError] = useState(null);
  const [confirmation, setConfirmation] = useState(null);
  const [coinBurst, setCoinBurst] = useState(false);

  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));

  async function runSearch(e) {
    e.preventDefault();
    setSearching(true);
    setSearchError(null);
    setResults(null);
    setConfirmation(null);
    const r = await apiPost('/api/emporium/travel/search', {
      kind: form.kind,
      origin: form.origin,
      destination: form.destination,
      depart_date: form.depart,
      return_date: form.ret,
      passengers: Number(form.passengers) || 1,
      tier: form.tier,
    });
    setSearching(false);
    if (r.ok) setResults(asArray(r.data));
    else setSearchError(r.error);
  }

  async function bookResult(item) {
    setBooking(item);
    setBookingBusy(true);
    setBookingError(null);
    const r = await apiPost('/api/emporium/travel/book', {
      kind: form.kind,
      tier: form.tier,
      passengers: Number(form.passengers) || 1,
      selection: item,
    });
    setBookingBusy(false);
    if (r.ok) {
      setConfirmation(r.data);
      setCoinBurst(true);
    } else {
      setBookingError(r.error);
    }
    setBooking(null);
  }

  return (
    <div className="montiff-page montiff-stack" data-testid="emporium-booking">
      <CoinBurst burst={coinBurst} onDone={() => setCoinBurst(false)} />

      <section className="montiff-panel" data-testid="search-command-center">
        <Rivets />
        <div className="montiff-brand" style={{ color: 'var(--montiff-cobalt)' }}>SEARCH COMMAND CENTER</div>
        <h1 className="montiff-h">PLOT YOUR COURSE</h1>

        <form onSubmit={runSearch} data-testid="booking-search-form">
          <div className="montiff-form-row">
            <Field label="KIND" testid="booking-field-kind">
              <select className="montiff-select" data-testid="booking-kind-select" value={form.kind} onChange={set('kind')}>
                {KINDS.map((k) => <option key={k} value={k}>{k.toUpperCase()}</option>)}
              </select>
            </Field>
            <Field label="ORIGIN" testid="booking-field-origin">
              <select className="montiff-select" data-testid="booking-origin-select" value={form.origin} onChange={set('origin')}>
                {AIRPORTS.map((a) => <option key={a} value={a}>{a}</option>)}
              </select>
            </Field>
            <Field label="DESTINATION" testid="booking-field-destination">
              <select className="montiff-select" data-testid="booking-destination-select" value={form.destination} onChange={set('destination')}>
                {AIRPORTS.map((a) => <option key={a} value={a}>{a}</option>)}
              </select>
            </Field>
            <Field label="DEPART" testid="booking-field-depart">
              <input type="date" className="montiff-input" data-testid="booking-depart-input" value={form.depart} onChange={set('depart')} />
            </Field>
            <Field label="RETURN" testid="booking-field-return">
              <input type="date" className="montiff-input" data-testid="booking-return-input" value={form.ret} onChange={set('ret')} />
            </Field>
            <Field label="PASSENGERS" testid="booking-field-passengers">
              <input type="number" min="1" max="12" className="montiff-input" data-testid="booking-passengers-input" value={form.passengers} onChange={set('passengers')} />
            </Field>
            <Field label="TIER" testid="booking-field-tier">
              <select className="montiff-select" data-testid="booking-tier-select" value={form.tier} onChange={set('tier')}>
                {TIERS.map((t) => <option key={t} value={t}>{t}</option>)}
              </select>
            </Field>
          </div>
          <button type="submit" className="montiff-btn" data-testid="booking-search-button" disabled={searching}>
            {searching ? 'SCANNING…' : 'SEARCH THE WIRE'}
          </button>
        </form>
      </section>

      {/* Results */}
      <section data-testid="booking-results-section">
        {searching && <LoadingState label="SCANNING THE WIRE FOR FARES…" />}
        {searchError && <ErrorState message={searchError} onRetry={runSearch} testid="booking-search-error" />}
        {results && results.length === 0 && (
          <EmptyState label="NO RESULTS — TRY WIDENING THE NET" testid="booking-results-empty" />
        )}
        {results && results.length > 0 && (
          <div className="montiff-grid" data-testid="booking-results-grid">
            {results.map((item, i) => {
              const id = pick(item, ['id', 'fare_id', 'offer_id'], i);
              const title = pick(item, ['title', 'name', 'airline', 'hotel', 'summary'], `OFFER ${i + 1}`);
              const price = pick(item, ['price', 'total', 'fare', 'amount'], '—');
              return (
                <div className="montiff-card" key={id} data-testid={`booking-result-${i}`}>
                  <div className="montiff-h-sm" style={{ margin: 0 }}>{title}</div>
                  <div>
                    <Kv k="ROUTE" v={`${pick(item, ['origin', 'from'], form.origin)} → ${pick(item, ['destination', 'to'], form.destination)}`} />
                    <Kv k="CLASS" v={pick(item, ['fare_class', 'class', 'cabin'], 'ECO')} />
                    <Kv k="CARRIER" v={pick(item, ['carrier', 'vendor', 'provider'], '—')} />
                  </div>
                  <div className="montiff-row" style={{ justifyContent: 'space-between', marginTop: 'auto' }}>
                    <span className="montiff-price" data-testid={`booking-result-price-${i}`}>{typeof price === 'number' ? `$${price.toLocaleString()}` : price}</span>
                    <button
                      className="montiff-btn small"
                      data-testid={`booking-book-button-${i}`}
                      disabled={bookingBusy}
                      onClick={() => bookResult(item)}
                    >
                      {bookingBusy ? 'WELDING…' : 'BOOK IT'}
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        )}
        {bookingError && <ErrorState message={bookingError} testid="booking-book-error" />}
      </section>

      {/* Confirmation */}
      {confirmation && (
        <section className="montiff-panel-blue" data-testid="booking-confirmation">
          <Rivets />
          <div className="montiff-brand" style={{ color: 'var(--montiff-green)' }}>✓ BOOKING WELDED</div>
          <h2 className="montiff-h" style={{ color: '#fff' }}>CONFIRMATION</h2>
          <div style={{ maxWidth: 560 }}>
            <Kv k="CONFIRMATION #" v={pick(confirmation, ['confirmation_id', 'booking_id', 'id'], '—')} />
            <Kv k="KIND" v={pick(confirmation, ['kind'], form.kind)} />
            <Kv k="TOTAL" v={pick(confirmation, ['total', 'price', 'amount'], '—')} />
            <Kv k="COMMISSION" v={pick(confirmation, ['commission', 'commission_earned'], '—')} />
            <Kv k="STATUS" v={pick(confirmation, ['status'], 'CONFIRMED')} />
          </div>
          <div className="montiff-row" style={{ marginTop: 14 }}>
            <button className="montiff-btn ghost" data-testid="booking-new-search-button" onClick={() => { setConfirmation(null); setResults(null); }}>
              NEW SEARCH
            </button>
          </div>
        </section>
      )}
    </div>
  );
}
