import * as React from 'react';
import { Slot } from '@radix-ui/react-slot';
import { cva } from 'class-variance-authority';
import { cn } from '@/lib/utils';

const buttonVariants = cva(
  'inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-svmd text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-gold-400 disabled:pointer-events-none disabled:opacity-50 [&_svg]:size-4 [&_svg]:shrink-0',
  {
    variants: {
      variant: {
        // Canon: DESIGN ← AMETHYST + RUBY — primary CTAs burn ruby.
        default: 'bg-ruby-500 text-white hover:bg-ruby-600 shadow-svsm',
        gold: 'bg-gold-500 text-obsidian-950 hover:bg-gold-400 shadow-svsm',
        ruby: 'bg-ruby-500 text-white hover:bg-ruby-600 shadow-svsm',
        secondary: 'bg-obsidian-700 text-ink hover:bg-obsidian-800 border border-line',
        ghost: 'text-ink-dim hover:text-ink hover:bg-obsidian-800',
        outline: 'border border-line bg-transparent text-ink hover:border-gold-500/60 hover:text-gold-300',
      },
      size: {
        default: 'h-10 px-5 py-2',
        sm: 'h-8 px-3 text-xs',
        lg: 'h-12 px-8 text-base',
        icon: 'h-10 w-10',
      },
    },
    defaultVariants: { variant: 'default', size: 'default' },
  }
);

const Button = React.forwardRef(({ className, variant, size, asChild = false, ...props }, ref) => {
  const Comp = asChild ? Slot : 'button';
  return <Comp className={cn(buttonVariants({ variant, size, className }))} ref={ref} {...props} />;
});
Button.displayName = 'Button';

export { Button, buttonVariants };
