/**
 * emporiumApi.js — defensive fetch layer for the Emporium commerce realm.
 * Backend APIs under /api/emporium/* are built in parallel; every call here
 * NEVER throws — it resolves { ok, data, error } so pages can render
 * friendly empty/error states instead of crashing.
 */
import { useEffect, useRef, useState, useCallback } from 'react';

const API_URL = process.env.REACT_APP_BACKEND_URL || '';

async function request(path, options = {}) {
  const url = `${API_URL}${path}`;
  try {
    const res = await fetch(url, {
      headers: { 'Content-Type': 'application/json' },
      ...options,
    });
    const text = await res.text();
    let data = null;
    try {
      data = text ? JSON.parse(text) : null;
    } catch {
      data = text;
    }
    if (!res.ok) {
      const detail = data && typeof data === 'object' ? data.detail || data.error || data.message : null;
      return { ok: false, data: null, error: detail || `Emporium core answered ${res.status}. Try again shortly.` };
    }
    return { ok: true, data, error: null };
  } catch {
    return { ok: false, data: null, error: 'Emporium core unreachable. The backend may be offline — showing standby state.' };
  }
}

export const apiGet = (path) => request(path);
export const apiPost = (path, body) => request(path, { method: 'POST', body: JSON.stringify(body || {}) });
export const apiPatch = (path, body) => request(path, { method: 'PATCH', body: JSON.stringify(body || {}) });
export const apiDelete = (path) => request(path, { method: 'DELETE' });

/** Normalize the many shapes a mock endpoint may return into an array. */
export function asArray(payload, keys = ['items', 'results', 'data', 'vendors', 'entries', 'positions', 'hotels', 'flights', 'cruises', 'cars', 'events', 'airports', 'apps', 'journeys', 'notes']) {
  if (!payload) return [];
  if (Array.isArray(payload)) return payload;
  if (typeof payload === 'object') {
    for (const k of keys) {
      if (Array.isArray(payload[k])) return payload[k];
    }
  }
  return [];
}

/** Pull a readable scalar out of an object trying several candidate keys. */
export function pick(obj, keys, fallback = '—') {
  if (!obj || typeof obj !== 'object') return fallback;
  for (const k of keys) {
    const v = obj[k];
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return fallback;
}

/** GET hook with loading/error states baked in. */
export function useApiGet(path, deps = []) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const alive = useRef(true);

  const load = useCallback(async () => {
    if (!path) {
      setLoading(false);
      return;
    }
    setLoading(true);
    setError(null);
    const r = await apiGet(path);
    if (!alive.current) return;
    setLoading(false);
    if (r.ok) setData(r.data);
    else setError(r.error);
  }, [path, ...deps]);

  useEffect(() => {
    alive.current = true;
    load();
    return () => { alive.current = false; };
  }, [load]);

  return { data, loading, error, reload: load };
}

export { API_URL };
