import React, { useState, useEffect } from 'react';
import { Store, KeyRound, ShoppingBag } from 'lucide-react';
import ModuleShell from '@/components/ModuleShell';

const API = process.env.REACT_APP_BACKEND_URL || '';

// Real Persona Marketplace: browse active listings, purchase a persona license.
// Purchases record a real 5% marketplace commission in the Emporium ledger.
function MarketplacePanel() {
  const [listings, setListings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [buyer, setBuyer] = useState('');
  const [buying, setBuying] = useState(null);
  const [receipt, setReceipt] = useState(null);

  const load = async () => {
    setLoading(true);
    setError('');
    try {
      const res = await fetch(`${API}/api/marketplace/listings`);
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Failed to load listings');
      setListings(data.listings || []);
    } catch (e) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, []);

  const purchase = async (listing) => {
    if (!buyer.trim()) { setError('Enter a buyer name to purchase.'); return; }
    setBuying(listing.id);
    setError('');
    setReceipt(null);
    try {
      const res = await fetch(`${API}/api/marketplace/purchase`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ listing_id: listing.id, buyer: buyer.trim() }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Purchase failed');
      setReceipt(data);
      load();
    } catch (e) {
      setError(e.message);
    } finally {
      setBuying(null);
    }
  };

  return (
    <div className="rounded-xl border border-amber-500/25 bg-black/40 p-5" data-testid="marketplace-panel">
      <div className="flex items-center gap-3 mb-1">
        <span className="inline-flex h-9 w-9 items-center justify-center rounded-lg bg-amber-500/15 text-amber-300 ring-1 ring-amber-500/30">
          <Store className="h-4 w-4" aria-hidden />
        </span>
        <h3 className="text-sm font-bold text-white">Persona Marketplace</h3>
        <span className="text-[9px] font-bold px-2 py-0.5 rounded-full bg-emerald-500/15 text-emerald-300 uppercase tracking-wider">Live</span>
      </div>
      <p className="text-xs text-gray-500 leading-relaxed mb-3">
        License a council persona. Purchases post a real 5% marketplace commission to the Emporium ledger.
      </p>
      <div className="flex gap-2 mb-3">
        <input
          value={buyer}
          onChange={(e) => setBuyer(e.target.value)}
          placeholder="Buyer name"
          data-testid="marketplace-buyer"
          className="flex-1 text-xs bg-black/60 border border-white/15 rounded-lg px-2 py-1.5 text-white"
        />
        <button onClick={load} data-testid="marketplace-refresh"
          className="text-xs font-bold px-3 py-1.5 rounded-lg border border-white/15 text-gray-300 hover:border-white/30">
          Refresh
        </button>
      </div>
      {loading && <p className="text-xs text-gray-500">Loading listings…</p>}
      {error && <p className="text-xs text-red-400 mb-2" data-testid="marketplace-error">{error}</p>}
      {receipt && (
        <div className="mb-3 rounded-lg border border-emerald-500/30 bg-emerald-500/10 p-3" data-testid="marketplace-receipt">
          <p className="text-xs font-bold text-emerald-300 flex items-center gap-1.5"><ShoppingBag className="h-3.5 w-3.5" /> License issued</p>
          <p className="text-[11px] text-gray-400 mt-1">
            {receipt.persona_id} · {receipt.license} · ${receipt.price_usd.toFixed(2)} — ledger commission ${receipt.commission_usd.toFixed(2)}
          </p>
          <p className="text-[10px] text-gray-600 mt-0.5 font-mono">entry {receipt.ledger_entry_hash?.slice(0, 16)}…</p>
        </div>
      )}
      {!loading && listings.length === 0 && (
        <p className="text-xs text-gray-600">No active listings yet. The owner can list personas via the API.</p>
      )}
      <div className="grid gap-2">
        {listings.map((l) => (
          <div key={l.id} className="rounded-lg border border-white/10 bg-white/[0.02] p-3 flex items-center justify-between gap-3" data-testid={`marketplace-listing-${l.persona_id}`}>
            <div className="min-w-0">
              <p className="text-xs font-bold text-white capitalize">{l.persona_id} <span className="ml-1 text-[9px] px-1.5 py-0.5 rounded bg-white/10 text-gray-400 uppercase">{l.license}</span></p>
              {l.description && <p className="text-[11px] text-gray-500 mt-0.5 leading-snug">{l.description}</p>}
            </div>
            <div className="flex items-center gap-2 flex-shrink-0">
              <span className="text-sm font-bold text-amber-300">${l.price_usd.toFixed(2)}</span>
              <button
                onClick={() => purchase(l)}
                disabled={buying === l.id}
                data-testid={`marketplace-buy-${l.persona_id}`}
                className="text-xs font-bold px-3 py-1.5 rounded-lg bg-amber-500/80 text-black hover:bg-amber-400 disabled:opacity-50"
              >
                {buying === l.id ? 'Issuing…' : 'Purchase'}
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

// Persona Marketplace is real (browse + ledger-wired purchases).
// BYOA remains a labeled holding — real OAuth needs provider credentials that don't exist.
function HoldingCard({ icon: Icon, title, blurb }) {
  return (
    <div className="rounded-xl border border-white/10 bg-black/40 p-5 opacity-90">
      <div className="flex items-center gap-3 mb-2">
        <span className="inline-flex h-9 w-9 items-center justify-center rounded-lg bg-white/5 text-gray-400 ring-1 ring-white/10">
          <Icon className="h-4 w-4" aria-hidden />
        </span>
        <h3 className="text-sm font-bold text-white">{title}</h3>
        <span className="text-[9px] font-bold px-2 py-0.5 rounded-full bg-white/10 text-gray-400 uppercase tracking-wider">
          Coming soon
        </span>
      </div>
      <p className="text-xs text-gray-500 leading-relaxed">{blurb}</p>
      <button
        disabled
        className="mt-3 text-xs font-bold px-3 py-1.5 rounded-lg border border-white/10 text-gray-600 cursor-not-allowed"
      >
        Not yet available
      </button>
    </div>
  );
}

export default function CouncilChamber() {
  return (
    <div>
      <ModuleShell sectionId="council" title="Council Chamber" blurb="Gather the Constructs — counsel, craft, and create together." />
      <div className="max-w-7xl mx-auto px-4 pb-10 mt-6 grid grid-cols-1 md:grid-cols-2 gap-4">
        <MarketplacePanel />
        <HoldingCard
          icon={KeyRound}
          title="Bring Your Own Agent (BYOA)"
          blurb="Connect an external agent via OAuth and seat it at the table. Provider OAuth flows are on the roadmap — not wired up yet."
        />
      </div>
    </div>
  );
}
