/**
 * EmporiumHotelDetail.jsx — detail + booking manifest
 * from /api/emporium/travel/hotels/:hotelId.
 */
import React, { useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import { useApiGet, apiPost, apiGet, asArray, pick } from './emporiumApi';
import { Rivets, LoadingState, EmptyState, ErrorState, CoinBurst, Kv } from './montiff-ui';

export default function EmporiumHotelDetail() {
  const { hotelId } = useParams();
  const { data, loading, error, reload } = useApiGet(`/api/emporium/travel/hotels/${hotelId}`, [hotelId]);
  const [manifest, setManifest] = useState(null);
  const [manifestState, setManifestState] = useState('idle'); // idle|loading|error
  const [booking, setBooking] = useState(null);
  const [bookingBusy, setBookingBusy] = useState(false);
  const [bookingError, setBookingError] = useState(null);
  const [coinBurst, setCoinBurst] = useState(false);

  const h = data && typeof data === 'object' && !Array.isArray(data) ? data : {};

  async function loadManifest() {
    setManifestState('loading');
    const embedded = h.manifest || h.booking_manifest;
    if (embedded) {
      setManifest(embedded);
      setManifestState('idle');
      return;
    }
    const r = await apiGet(`/api/emporium/travel/manifests?hotel_id=${encodeURIComponent(hotelId)}`);
    if (r.ok) {
      const list = asArray(r.data);
      setManifest(list[0] || r.data);
      setManifestState('idle');
    } else {
      setManifestState('error');
    }
  }

  async function bookStay() {
    setBookingBusy(true);
    setBookingError(null);
    const r = await apiPost('/api/emporium/travel/book', {
      kind: 'hotel',
      hotel_id: hotelId,
      selection: h,
    });
    setBookingBusy(false);
    if (r.ok) {
      setBooking(r.data);
      setCoinBurst(true);
    } else {
      setBookingError(r.error);
    }
  }

  return (
    <div className="montiff-page montiff-stack" data-testid="emporium-hotel-detail">
      <CoinBurst burst={coinBurst} onDone={() => setCoinBurst(false)} />
      <Link className="montiff-btn small ghost" data-testid="hotel-detail-back-link" to="/emporium/hotels">← HOTELS GRID</Link>

      {loading && <LoadingState label="PULLING HOTEL DOSSIER…" />}
      {error && <ErrorState message={error} onRetry={reload} testid="hotel-detail-error" />}
      {!loading && !error && (
        <>
          <section className="montiff-panel" data-testid="hotel-detail-panel">
            <Rivets />
            <div className="montiff-brand" style={{ color: 'var(--montiff-cobalt)' }}>HOTEL DOSSIER</div>
            <h1 className="montiff-h">{pick(h, ['name', 'title'], `HOTEL ${hotelId}`)}</h1>
            <div className="montiff-grid-2">
              <div>
                <Kv k="CITY" v={pick(h, ['city', 'location'], '—')} />
                <Kv k="ADDRESS" v={pick(h, ['address'], '—')} />
                <Kv k="STARS" v={pick(h, ['stars', 'rating'], '—')} />
                <Kv k="CHAIN" v={pick(h, ['chain', 'brand', 'vendor'], '—')} />
              </div>
              <div>
                <Kv k="NIGHTLY RATE" v={pick(h, ['nightly_rate', 'price', 'rate'], '—')} />
                <Kv k="ROOMS" v={pick(h, ['rooms', 'room_count'], '—')} />
                <Kv k="AMENITIES" v={Array.isArray(h.amenities) ? h.amenities.join(', ') : pick(h, ['amenities'], '—')} />
                <Kv k="POLICY" v={pick(h, ['cancellation', 'policy'], '—')} />
              </div>
            </div>
            {pick(h, ['description', 'blurb'], '') !== '' && (
              <p style={{ marginTop: 12 }}>{pick(h, ['description', 'blurb'], '')}</p>
            )}
            <div className="montiff-row" style={{ marginTop: 14 }}>
              <button className="montiff-btn" data-testid="hotel-detail-book-button" onClick={bookStay} disabled={bookingBusy}>
                {bookingBusy ? 'WELDING…' : 'BOOK THIS STAY'}
              </button>
              <button className="montiff-btn secondary" data-testid="hotel-detail-manifest-button" onClick={loadManifest}>
                BOOKING MANIFEST
              </button>
            </div>
            {bookingError && <ErrorState message={bookingError} testid="hotel-detail-book-error" />}
          </section>

          {booking && (
            <section className="montiff-panel-blue" data-testid="hotel-detail-confirmation">
              <Rivets />
              <div className="montiff-brand" style={{ color: 'var(--montiff-green)' }}>✓ STAY WELDED</div>
              <Kv k="CONFIRMATION #" v={pick(booking, ['confirmation_id', 'booking_id', 'id'], '—')} />
              <Kv k="TOTAL" v={pick(booking, ['total', 'price', 'amount'], '—')} />
              <Kv k="STATUS" v={pick(booking, ['status'], 'CONFIRMED')} />
            </section>
          )}

          {(manifestState !== 'idle' || manifest) && (
            <section className="montiff-panel-flat" data-testid="hotel-detail-manifest">
              <div className="montiff-h-sm">BOOKING MANIFEST</div>
              {manifestState === 'loading' && <LoadingState label="FETCHING MANIFEST…" />}
              {manifestState === 'error' && <ErrorState message="Manifest endpoint unreachable." testid="hotel-detail-manifest-error" />}
              {manifestState === 'idle' && manifest && (
                <pre className="montiff-readout" data-testid="hotel-detail-manifest-body" style={{ whiteSpace: 'pre-wrap', fontSize: 12 }}>
                  {typeof manifest === 'string' ? manifest : JSON.stringify(manifest, null, 2)}
                </pre>
              )}
              {manifestState === 'idle' && !manifest && (
                <EmptyState label="NO MANIFEST FILED FOR THIS STAY" testid="hotel-detail-manifest-empty" />
              )}
            </section>
          )}
        </>
      )}
    </div>
  );
}
