// ═══════════════════════════════════════════════════════════════════════════
// MODULE SHELL — a dignified placeholder for Forge modules whose full studio
// is still migrating into the new Sovereign Shell. Every module gets the
// Sigil PageHeader, a warm (rose quartz) holding state, and doors onward —
// never a dead end, never a blank page.
// ═══════════════════════════════════════════════════════════════════════════

import React from 'react';
import { Link } from 'react-router-dom';
import { ArrowRight, House } from 'lucide-react';
import { PageHeader, SECTIONS, jewelStyle } from '@/components/Sigil';
import { Button } from '@/components/ui/button';
import { motion } from 'framer-motion';
import { omina } from '@/motion/omina';

export default function ModuleShell({ sectionId, title, blurb }) {
  const section = SECTIONS.find((s) => s.id === sectionId) || SECTIONS[0];
  const Icon = section.icon;
  const seal = jewelStyle('amethyst'); // holding state is structural → DESIGN amethyst

  return (
    <motion.div variants={omina.stagger} initial="initial" animate="animate" className="mx-auto max-w-3xl">
      <PageHeader
        icon={Icon}
        kicker={section.label}
        title={title}
        description={blurb}
        jewel={section.jewel}
      />
      <motion.div
        variants={omina.rise}
        className={`rounded-svxl border border-line bg-obsidian-900 p-8 text-center shadow-svmd ring-1 ${seal.ring}`}
      >
        <p
          className="text-xl font-semibold text-amethyst-400"
          style={{ fontFamily: 'var(--sv-font-display)' }}
        >
          This chamber is being prepared.
        </p>
        <p className="mx-auto mt-3 max-w-md text-sm leading-relaxed text-ink-dim">
          {title} is moving into the new Sovereign Shell. Its full studio arrives
          with the migration — nothing here is a dead end in the meantime.
        </p>
        <div className="mt-6 flex flex-wrap items-center justify-center gap-3">
          <Button asChild variant="ruby">
            <Link to="/">
              <House aria-hidden /> Return home
            </Link>
          </Button>
          <Button asChild variant="outline">
            <Link to="/radio">
              Visit a live module <ArrowRight aria-hidden />
            </Link>
          </Button>
        </div>
      </motion.div>
    </motion.div>
  );
}
