// ═══════════════════════════════════════════════════════════════════════════════
// COLOSSUS — Motion & Video Geometry Engine
// Sovereign Core Matrix pillar. Owner canon: COLOSSUS is a stateless
// motion-geometry compiler — it generates video from motion math, not pixel
// rendering. Movement is treated as geometry, not raster frames.
//
// Architecture (honest for a website): "video from motion math, no GPU" is
// implemented as real-time vector-field synthesis on canvas 2D (no WebGL).
// Every frame is a PURE function of (seed, time) — there are no retained
// frame buffers anywhere in this file. That is what "stateless" means here.
//
// Pipeline:  motion seed → geometry compiler → frame synthesizer → canvas
//   • Motion Seeds: atomic motion units {id, source_type, fidelity_mode}
//   • Geometry Compiler: seeds → spatial geometry (vector fields, motion
//     curves, temporal geometry)
//   • Frame Synthesizer: frames from geometry (adaptive density, unlimited
//     FPS — not frame-bound; CLYDE virtual-HDMI timing via shared clock)
//
// Fidelity modes: biological (eased organic curves), stylized (snapped
// geometric forms), abstract (flow-field particles).
// Input types: camera (opt-in getUserMedia, user gesture only), synthetic,
// render.
//
// Module scope is DOM-free: importing this file never touches document,
// window, or navigator, so the pure core is node-testable. All DOM/camera
// access happens inside called functions only.
// No new npm dependencies.
// ═══════════════════════════════════════════════════════════════════════════════

export const COLOSSUS_SOURCE_TYPES = ['camera', 'synthetic', 'render'];
export const COLOSSUS_FIDELITY_MODES = ['biological', 'stylized', 'abstract'];
export const COLOSSUS_VERSION = '1.0.0';

// ── Deterministic PRNG (mulberry32) + string hash ────────────────────────────

function hashStr(s) {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function mulberry32(a) {
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

let seedCounter = 0;
function newSeedId() {
  seedCounter += 1;
  const rand = Math.floor(Math.random() * 0xffffff).toString(16).padStart(6, '0').toUpperCase();
  return `SEED-${rand}${String(seedCounter).padStart(4, '0')}`;
}

// ── Pure core: seeds ─────────────────────────────────────────────────────────

function assertSourceType(source_type) {
  if (!COLOSSUS_SOURCE_TYPES.includes(source_type)) {
    throw new RangeError(
      `source_type must be one of ${COLOSSUS_SOURCE_TYPES.join(', ')} (got ${JSON.stringify(source_type)})`
    );
  }
}

function assertFidelityMode(fidelity_mode) {
  if (!COLOSSUS_FIDELITY_MODES.includes(fidelity_mode)) {
    throw new RangeError(
      `fidelity_mode must be one of ${COLOSSUS_FIDELITY_MODES.join(', ')} (got ${JSON.stringify(fidelity_mode)})`
    );
  }
}

/**
 * Create a motion seed — an atomic motion unit.
 * {source_type: camera|synthetic|render, fidelity_mode: biological|stylized|abstract, params}
 */
export function createSeed({ source_type = 'synthetic', fidelity_mode = 'stylized', params = {} } = {}) {
  assertSourceType(source_type);
  assertFidelityMode(fidelity_mode);
  if (params === null || typeof params !== 'object' || Array.isArray(params)) {
    throw new TypeError('params must be a plain object');
  }
  return {
    id: newSeedId(),
    source_type,
    fidelity_mode,
    params: { ...params },
  };
}

// ── Pure core: geometry compiler ─────────────────────────────────────────────
// Deterministic: same seed → identical geometry (PRNG keyed on seed identity).

const VECTORS_PER_SEED = 64;

function compileVectorFields(rng, fidelity_mode) {
  const fields = [];
  for (let i = 0; i < VECTORS_PER_SEED; i++) {
    fields.push({
      // origin in normalized 0..1 stage coords
      x: rng(),
      y: rng(),
      angle: rng() * Math.PI * 2, // radians
      magnitude: 0.02 + rng() * 0.10,
      freq: 0.3 + rng() * 1.7, // temporal frequency multiplier
      phase: rng() * Math.PI * 2,
      // stylized mode snaps to bold geometric bearings at synthesis time
    });
  }
  return fields;
}

function compileMotionCurves(rng, fidelity_mode) {
  const curves = [];
  const nCurves = fidelity_mode === 'abstract' ? 2 : 4;
  for (let c = 0; c < nCurves; c++) {
    const pts = [];
    const nPts = 5;
    for (let p = 0; p < nPts; p++) {
      pts.push({ x: rng(), y: rng() });
    }
    curves.push({ points: pts, closed: rng() > 0.5, speed: 0.2 + rng() * 0.8, phase: rng() * Math.PI * 2 });
  }
  return curves;
}

/**
 * Compile a seed into spatial geometry.
 * Pure + deterministic: identical seed → identical geometry.
 */
export function compileSeed(seed) {
  if (!seed || typeof seed.id !== 'string') throw new TypeError('compileSeed requires a seed object');
  assertSourceType(seed.source_type);
  assertFidelityMode(seed.fidelity_mode);
  const rng = mulberry32(hashStr(`${seed.id}|${seed.source_type}|${seed.fidelity_mode}`));
  return {
    seed_id: seed.id,
    source_type: seed.source_type,
    fidelity_mode: seed.fidelity_mode,
    vectorFields: compileVectorFields(rng, seed.fidelity_mode),
    motionCurves: compileMotionCurves(rng, seed.fidelity_mode),
    temporal: {
      period: 4 + rng() * 8, // seconds per full motion cycle
      speed: 0.5 + rng() * 1.5,
    },
  };
}

// ── Pure core: frame synthesizer ─────────────────────────────────────────────
// motionAt(geometry, t, energy) — the stateless heart of COLOSSUS.
// Same (geometry, t, energy) → byte-identical vector list. No memory.

function biologicalOffset(v, wt) {
  // Eased organic curves: layered sine composites, smooth and breathing.
  const sway = Math.sin(wt * v.freq + v.phase) * 0.5 + Math.sin(wt * v.freq * 0.37 + v.phase * 1.7) * 0.5;
  const lift = Math.cos(wt * v.freq * 0.63 + v.phase * 0.6);
  return { dx: Math.cos(v.angle + sway * 0.9), dy: Math.sin(v.angle + sway * 0.9), lift };
}

function stylizedOffset(v, wt) {
  // Snapped geometric forms: bearings quantized to 45°, magnitudes stepped.
  const raw = v.angle + Math.sin(wt * v.freq + v.phase) * 0.6;
  const snapped = Math.round(raw / (Math.PI / 4)) * (Math.PI / 4);
  const stepped = Math.round((0.5 + 0.5 * Math.sin(wt * v.freq * 0.5 + v.phase)) * 3) / 3;
  return { dx: Math.cos(snapped), dy: Math.sin(snapped), lift: stepped };
}

function abstractOffset(v, wt, x, y) {
  // Flow-field particles: closed-form pseudo-curl noise, advected by time.
  const n1 = Math.sin(x * 6.3 + wt * 0.9) + Math.sin(y * 4.1 - wt * 0.7);
  const n2 = Math.cos(x * 3.7 - wt * 0.6) + Math.cos(y * 5.9 + wt * 1.1);
  const ang = Math.atan2(n2, n1) + v.phase * 0.05;
  return { dx: Math.cos(ang), dy: Math.sin(ang), lift: 0.5 + 0.5 * Math.sin(n1 + n2) };
}

/**
 * Synthesize one frame of motion vectors from geometry at time t (seconds).
 * @param {object} geometry — from compileSeed
 * @param {number} t — time in seconds (use the CLYDE clock timestamp)
 * @param {number} energy — 0..2 scalar (audio-reactive drive from KITSUNE)
 * @returns {Array<{x,y,dx,dy,energy}>} — positions/velocities in 0..1 stage coords
 */
export function motionAt(geometry, t, energy = 1) {
  if (!geometry || !Array.isArray(geometry.vectorFields)) {
    throw new TypeError('motionAt requires compiled geometry');
  }
  if (!Number.isFinite(t)) throw new TypeError('t must be a finite number');
  const e = Math.max(0, Math.min(2, Number(energy) || 0));
  const wt = (t * geometry.temporal.speed * Math.PI * 2) / geometry.temporal.period;
  const mode = geometry.fidelity_mode;
  return geometry.vectorFields.map((v) => {
    let o;
    if (mode === 'biological') o = biologicalOffset(v, wt);
    else if (mode === 'stylized') o = stylizedOffset(v, wt);
    else o = abstractOffset(v, wt, v.x, v.y);
    const mag = v.magnitude * e * (mode === 'stylized' ? 1.15 : 1);
    return {
      x: v.x,
      y: v.y,
      dx: o.dx * mag,
      dy: o.dy * mag,
      energy: Math.max(0, Math.min(1, e * (0.35 + 0.65 * Math.abs(o.lift)))),
    };
  });
}

// ── Camera input (user gesture only) ─────────────────────────────────────────
// Optical-flow-lite: downsampled luminance deltas → coarse motion vectors.
// Everything DOM/camera lives inside these functions — never at module scope.

export function isCameraSupported() {
  return (
    typeof navigator !== 'undefined' &&
    !!(navigator.mediaDevices && navigator.mediaDevices.getUserMedia)
  );
}

/**
 * Start a camera motion feed. MUST be called from a user gesture (click).
 * Returns { sample() → [{x,y,dx,dy}], stop() }. sample() is cheap (32×24 px).
 */
export async function startCameraFeed() {
  if (!isCameraSupported()) throw new Error('Camera not supported in this browser');
  const stream = await navigator.mediaDevices.getUserMedia({ video: { width: 160, height: 120 } });
  const video = document.createElement('video');
  video.muted = true;
  video.playsInline = true;
  video.srcObject = stream;
  await video.play();
  const W = 32;
  const H = 24;
  const canvas = document.createElement('canvas');
  canvas.width = W;
  canvas.height = H;
  const g = canvas.getContext('2d', { willReadFrequently: true });
  let prev = null;
  return {
    kind: 'camera-feed',
    sample() {
      if (video.readyState < 2) return [];
      g.drawImage(video, 0, 0, W, H);
      const data = g.getImageData(0, 0, W, H).data;
      const lum = new Float32Array(W * H);
      for (let i = 0; i < W * H; i++) {
        lum[i] = (data[i * 4] + data[i * 4 + 1] + data[i * 4 + 2]) / 765;
      }
      const out = [];
      if (prev) {
        // 8×6 coarse blocks → dominant local motion direction
        for (let by = 0; by < 6; by++) {
          for (let bx = 0; bx < 8; bx++) {
            let sx = 0;
            let sy = 0;
            let mag = 0;
            for (let y = 0; y < 4; y++) {
              for (let x = 0; x < 4; x++) {
                const px = bx * 4 + x;
                const py = by * 4 + y;
                const idx = py * W + px;
                const d = lum[idx] - prev[idx];
                // crude gradient: compare with right/left and down/up neighbors
                const gx = (lum[py * W + Math.min(W - 1, px + 1)] || 0) - (lum[py * W + Math.max(0, px - 1)] || 0);
                const gy = (lum[Math.min(H - 1, py + 1) * W + px] || 0) - (lum[Math.max(0, py - 1) * W + px] || 0);
                sx += gx * d;
                sy += gy * d;
                mag += Math.abs(d);
              }
            }
            if (mag > 0.6) {
              const n = Math.hypot(sx, sy) || 1;
              out.push({
                x: (bx + 0.5) / 8,
                y: (by + 0.5) / 6,
                dx: (sx / n) * Math.min(0.2, mag * 0.05),
                dy: (sy / n) * Math.min(0.2, mag * 0.05),
              });
            }
          }
        }
      }
      prev = lum;
      return out;
    },
    stop() {
      try { stream.getTracks().forEach((tr) => tr.stop()); } catch (err) { /* noop */ }
      try { video.pause(); video.srcObject = null; } catch (err) { /* noop */ }
    },
  };
}

// ── Renderer: pure core bound to canvas 2D ───────────────────────────────────
// Honest labeling: this is real-time vector geometry synthesis on canvas —
// NOT GPU rendering, NOT video encoding.

const DENSITY_STEPS = [24, 48, 96, 192]; // vectors drawn per frame (adaptive)
const FIDELITY_COLORS = {
  biological: '#34d399', // organic green
  stylized: '#fbbf24',   // geometric amber
  abstract: '#c084fc',   // flow violet
};

/**
 * Bind the pure core to a canvas 2D stage.
 * @param {HTMLCanvasElement} canvas
 */
export function createRenderer(canvas) {
  if (!canvas || typeof canvas.getContext !== 'function') {
    throw new TypeError('createRenderer requires a canvas element');
  }
  const ctx2d = canvas.getContext('2d');
  const seeds = new Map(); // id → { seed, geometry }
  let quality = 'auto';
  let densityIdx = 2; // start at 96
  let frameEMA = 16;
  let frames = 0;
  let lastFpsAt = 0;
  let fps = 0;
  let lastT = 0;
  let clydeClock = null; // { getTimestamp() } — CLYDE virtual-HDMI timing port
  let cameraFeed = null;
  let energyOverride = 1;
  let destroyed = false;

  function drawStage(w, h) {
    ctx2d.fillStyle = '#060609';
    ctx2d.fillRect(0, 0, w, h);
  }

  function drawVectors(vectors, color, w, h, scale) {
    ctx2d.strokeStyle = color;
    ctx2d.lineWidth = 1.4;
    ctx2d.shadowColor = color;
    ctx2d.shadowBlur = 6;
    ctx2d.beginPath();
    for (const v of vectors) {
      const x0 = v.x * w;
      const y0 = v.y * h;
      const x1 = x0 + v.dx * scale * w;
      const y1 = y0 + v.dy * scale * h;
      ctx2d.moveTo(x0, y0);
      ctx2d.lineTo(x1, y1);
      // arrowhead
      const ang = Math.atan2(y1 - y0, x1 - x0);
      const ah = 4;
      ctx2d.moveTo(x1, y1);
      ctx2d.lineTo(x1 - ah * Math.cos(ang - 0.5), y1 - ah * Math.sin(ang - 0.5));
      ctx2d.moveTo(x1, y1);
      ctx2d.lineTo(x1 - ah * Math.cos(ang + 0.5), y1 - ah * Math.sin(ang + 0.5));
    }
    ctx2d.stroke();
    ctx2d.shadowBlur = 0;
  }

  function drawCurves(geometry, t, w, h) {
    ctx2d.strokeStyle = 'rgba(148,163,184,0.25)';
    ctx2d.lineWidth = 1;
    ctx2d.beginPath();
    for (const c of geometry.motionCurves) {
      const pts = c.points;
      const off = Math.sin((t * c.speed + c.phase) * Math.PI * 2) * 0.02;
      pts.forEach((p, i) => {
        const x = (p.x + off * (i % 2 === 0 ? 1 : -1)) * w;
        const y = p.y * h;
        if (i === 0) ctx2d.moveTo(x, y);
        else ctx2d.lineTo(x, y);
      });
      if (c.closed) ctx2d.closePath();
    }
    ctx2d.stroke();
  }

  function adapt(now) {
    if (quality !== 'auto' || lastT === 0) return;
    const dt = now - lastT;
    frameEMA = frameEMA * 0.92 + dt * 0.08;
    // Adaptive density: shed vectors when slow, add back when fast.
    // Timing is never dropped — only vector count.
    if (frameEMA > 26 && densityIdx > 0) densityIdx -= 1;
    else if (frameEMA < 13 && densityIdx < DENSITY_STEPS.length - 1) densityIdx += 1;
  }

  const api = {
    addSeed(seed) {
      const geometry = compileSeed(seed);
      seeds.set(seed.id, { seed, geometry });
      return seed.id;
    },
    removeSeed(id) {
      return seeds.delete(id);
    },
    clearSeeds() {
      seeds.clear();
    },
    seedIds() {
      return [...seeds.keys()];
    },
    setQuality(q) {
      if (!['auto', 'high', 'low'].includes(q)) throw new RangeError('quality must be auto|high|low');
      quality = q;
      densityIdx = q === 'high' ? DENSITY_STEPS.length - 1 : q === 'low' ? 0 : 2;
    },
    /** Attach a CLYDE-compatible clock { getTimestamp() } for virtual-HDMI timing. */
    attachClydeClock(clock) {
      if (!clock || typeof clock.getTimestamp !== 'function') {
        throw new TypeError('clock must expose getTimestamp()');
      }
      clydeClock = clock;
    },
    detachClydeClock() {
      clydeClock = null;
    },
    setCameraFeed(feed) {
      cameraFeed = feed;
    },
    setEnergy(e) {
      energyOverride = Math.max(0, Math.min(2, Number(e) || 0));
    },
    /**
     * Render one frame. t defaults to the CLYDE clock (or performance.now).
     * Returns { fps, vectorsDrawn, timestamp, clyde }.
     */
    renderFrame(t, { energy } = {}) {
      if (destroyed) return null;
      const now = typeof performance !== 'undefined' ? performance.now() : Date.now();
      adapt(now);
      const ts = t !== undefined ? t : clydeClock ? clydeClock.getTimestamp() : now / 1000;
      const w = canvas.width;
      const h = canvas.height;
      drawStage(w, h);
      const density = DENSITY_STEPS[densityIdx];
      const e = energy !== undefined ? energy : energyOverride;
      let drawn = 0;
      for (const { seed, geometry } of seeds.values()) {
        const vectors = motionAt(geometry, ts, e);
        const sub = vectors.filter((_, i) => i % Math.ceil(vectors.length / density) === 0);
        drawCurves(geometry, ts, w, h);
        drawVectors(sub, FIDELITY_COLORS[seed.fidelity_mode] || '#94a3b8', w, h, 3);
        drawn += sub.length;
      }
      if (cameraFeed) {
        const cam = cameraFeed.sample();
        drawVectors(cam, '#22d3ee', w, h, 2.5);
        drawn += cam.length;
      }
      frames += 1;
      if (now - lastFpsAt >= 500) {
        fps = Math.round((frames * 1000) / Math.max(1, now - lastFpsAt));
        frames = 0;
        lastFpsAt = now;
      }
      lastT = now;
      return { fps, vectorsDrawn: drawn, timestamp: ts, clyde: clydeClock ? 'locked' : 'free' };
    },
    getFps() {
      return fps;
    },
    getDensity() {
      return DENSITY_STEPS[densityIdx];
    },
    destroy() {
      destroyed = true;
      seeds.clear();
      if (cameraFeed) {
        try { cameraFeed.stop(); } catch (err) { /* noop */ }
        cameraFeed = null;
      }
    },
  };
  return api;
}

// ── Engine status ────────────────────────────────────────────────────────────

export function engineStatus() {
  return {
    name: 'COLOSSUS',
    version: COLOSSUS_VERSION,
    stateless: true,
    gpu: 'none', // canvas 2D vector synthesis — no GPU, no video encoding
    fidelity_modes: [...COLOSSUS_FIDELITY_MODES],
    input_types: [...COLOSSUS_SOURCE_TYPES],
    pipeline: ['geometry', 'synthesis', 'output'],
    clyde: { port: 'ready', spec: 'pending' }, // CLYDE internals not invented — port labeled
  };
}
