// ═══════════════════════════════════════════════════════════════════════════
// HOME — the front door of the Forge. A stranger must understand the studio
// in ten seconds: what it is, what it does, where to go. Six doors, one per
// section, staggered in by Omina. A live status strip shows whether the
// Forge API answers — with loading and unreachable states, honestly shown.
// ═══════════════════════════════════════════════════════════════════════════

import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import { ArrowRight, ArrowUpRight } from 'lucide-react';
import { SECTIONS, Wordmark, jewelStyle } from '@/components/Sigil';
import { omina } from '@/motion/omina';
import { cn } from '@/lib/utils';

const API_URL = process.env.REACT_APP_BACKEND_URL || '';

function StatusStrip() {
  const [status, setStatus] = useState('loading'); // loading | online | unreachable

  useEffect(() => {
    let live = true;
    fetch(`${API_URL}/api/health`, { method: 'GET' })
      .then((r) => { if (live) setStatus(r.ok ? 'online' : 'unreachable'); })
      .catch(() => { if (live) setStatus('unreachable'); });
    return () => { live = false; };
  }, []);

  return (
    <div
      className="inline-flex items-center gap-2 rounded-full border border-line bg-obsidian-900 px-4 py-1.5 text-xs text-ink-dim"
      role="status"
      aria-live="polite"
    >
      {status === 'loading' && (
        <>
          <motion.span variants={omina.pulse} animate="animate" className="h-2 w-2 rounded-full bg-gold-400" aria-hidden />
          <span>Contacting the Forge…</span>
        </>
      )}
      {status === 'online' && (
        <>
          <span className="h-2 w-2 rounded-full bg-sapphire-400 shadow-svsapphire" aria-hidden />
          <span className="text-ink">Forge online</span>
        </>
      )}
      {status === 'unreachable' && (
        <>
          <span className="h-2 w-2 rounded-full bg-ink-mute" aria-hidden />
          <span>The Forge API is quiet right now — the studio still browses.</span>
        </>
      )}
    </div>
  );
}

function SectionDoor({ section, index }) {
  const Icon = section.icon;
  const j = jewelStyle(section.jewel);
  return (
    <motion.div variants={omina.rise}>
      <motion.div {...omina.hoverLift} {...omina.tap}>
        <Link
          to={section.home}
          className="group flex h-full flex-col rounded-svxl border border-line bg-obsidian-900 p-6 shadow-svmd transition-all hover:border-sapphire-500/50 hover:shadow-svsapphire"
          aria-label={`Enter ${section.label}: ${section.blurb}`}
        >
          <span className={cn('inline-flex h-11 w-11 items-center justify-center rounded-svlg ring-1', j.bg, j.ring, j.text)}>
            <Icon className="h-5 w-5" aria-hidden />
          </span>
          <span
            className="mt-4 text-xl font-bold text-ink"
            style={{ fontFamily: 'var(--sv-font-display)' }}
          >
            {section.label}
          </span>
          <span className="mt-2 flex-1 text-sm leading-relaxed text-ink-dim">{section.blurb}</span>
          <span className="mt-4 inline-flex items-center gap-1 text-sm font-semibold text-amethyst-400">
            Enter
            <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-1" aria-hidden />
          </span>
        </Link>
      </motion.div>
    </motion.div>
  );
}

export default function HomePage() {
  return (
    <motion.div variants={omina.stagger} initial="initial" animate="animate">
      {/* ── Hero ─────────────────────────────────────────────────────── */}
      <motion.section variants={omina.rise} className="pt-6 text-center md:pt-12">
        <div className="flex justify-center">
          <StatusStrip />
        </div>
        <div className="mt-8 flex justify-center">
          <span
            className="font-display text-5xl font-bold tracking-wide text-gold-400 md:text-7xl"
            style={{ fontFamily: 'var(--sv-font-display)', textShadow: '0 0 48px rgba(212,164,55,0.25)' }}
          >
            Benny&rsquo;s Studio
          </span>
        </div>
        <p className="mt-4 text-xs font-semibold uppercase tracking-[0.34em] text-ink-mute">
          Sovereign AI Creative Studio — Forge 66
        </p>
        <p className="mx-auto mt-6 max-w-2xl text-base leading-relaxed text-ink-dim md:text-lg">
          A sovereign creative studio on the web. Forge <span className="text-ink">stories and comics</span>,
          compose <span className="text-ink">music</span>, gather a <span className="text-amethyst-400">council of
          AI constructs</span>, broadcast <span className="text-ink">radio</span> — then publish it all to the world.
        </p>
        <p className="mx-auto mt-4 max-w-xl text-sm italic leading-relaxed text-gold-300">
          Write it. Score it. Screen it. Publish it.
        </p>
        <div className="mt-8 flex flex-wrap items-center justify-center gap-3">
          <Link
            to="/forge"
            className="inline-flex h-12 items-center gap-2 rounded-svmd bg-ruby-500 px-8 text-base font-semibold text-white shadow-svmd transition-colors hover:bg-ruby-600"
          >
            Start creating <ArrowRight className="h-4 w-4" aria-hidden />
          </Link>
          <Link
            to="/council-chamber"
            className="inline-flex h-12 items-center gap-2 rounded-svmd border border-line bg-transparent px-8 text-base font-semibold text-ink transition-colors hover:border-amethyst-500/60 hover:text-amethyst-400"
          >
            Meet the Council
          </Link>
        </div>
      </motion.section>

      {/* ── Six doors ────────────────────────────────────────────────── */}
      <motion.section variants={omina.rise} className="mt-14 md:mt-20" aria-label="Forge sections">
        <div className="mb-6 flex items-end justify-between">
          <h2
            className="text-2xl font-bold text-ink"
            style={{ fontFamily: 'var(--sv-font-display)' }}
          >
            The six chambers
          </h2>
          <span className="hidden text-xs uppercase tracking-[0.22em] text-ink-mute md:inline">
            Choose a door
          </span>
        </div>
        <motion.div
          variants={omina.stagger}
          initial="initial"
          animate="animate"
          className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3"
        >
          {SECTIONS.map((s, i) => (
            <SectionDoor key={s.id} section={s} index={i} />
          ))}
        </motion.div>
      </motion.section>

      {/* ── Footnote ─────────────────────────────────────────────────── */}
      <motion.section variants={omina.rise} className="mt-14 pb-4 text-center md:mt-20">
        <p className="text-xs leading-relaxed text-ink-mute">
          The Forge is a website — every chamber above runs in your browser.
          <Link to="/economy" className="ml-1 inline-flex items-center gap-0.5 text-gold-400 hover:text-gold-300">
            See the machinery <ArrowUpRight className="h-3 w-3" aria-hidden />
          </Link>
        </p>
        <div className="mt-6 flex justify-center opacity-60">
          <Wordmark compact />
        </div>
      </motion.section>
    </motion.div>
  );
}
