/**
 * ClaudetteCockpit.jsx — Claudette's vendor-acquisition cockpit.
 *
 * Claudette is a HUMAN (Vendor Acquisition Lead · Jamaica · SST-CLAUDETTE).
 * This cockpit is her working tool: kanban pipeline, note stream, credential
 * metadata. It NEVER sends messages, emails, or outreach anywhere — human
 * vendor outreach is Claudette's own work, outside this screen.
 */
import React, { useState } from 'react';
import { useApiGet, apiPost, apiPatch, asArray, pick } from './emporiumApi';
import { Rivets, LoadingState, EmptyState, ErrorState, Kv } from './montiff-ui';
import { PipelineBoard } from './EmporiumVendors';

const PIPELINE_STATES = ['LEAD', 'CONTACTED', 'NEGOTIATING', 'SIGNED', 'LIVE'];

function allVendors(board) {
  // Reuse the same normalization tolerance as the vendor console.
  const list = [];
  if (!board) return list;
  const src = board.columns || board.board || board.states || null;
  if (src && typeof src === 'object') {
    for (const s of PIPELINE_STATES) {
      const arr = src[s] || src[s.toLowerCase()];
      if (Array.isArray(arr)) list.push(...arr.map((v) => ({ ...v, __state: s })));
    }
    return list;
  }
  return asArray(board, ['vendors', 'items', 'results', 'data']).map((v) => ({
    ...v,
    __state: String(pick(v, ['pipeline_state', 'state', 'status'], 'LEAD')).toUpperCase(),
  }));
}

export default function ClaudetteCockpit() {
  const board = useApiGet('/api/emporium/vendors/pipeline/board');
  const [selectedId, setSelectedId] = useState(null);
  const [noteText, setNoteText] = useState('');
  const [noteBusy, setNoteBusy] = useState(false);
  const [noteError, setNoteError] = useState(null);
  const [noteOk, setNoteOk] = useState(false);
  const [moving, setMoving] = useState(null);
  const [moveError, setMoveError] = useState(null);
  const [cred, setCred] = useState({ vendor_id: '', credential_type: 'IATA', reference: '', notes: '' });
  const [credBusy, setCredBusy] = useState(false);
  const [credError, setCredError] = useState(null);
  const [credOk, setCredOk] = useState(false);

  const vendors = allVendors(board.data);
  const selected = vendors.find((v) => String(pick(v, ['id', 'vendor_id'])) === String(selectedId)) || null;
  const selectedNotes = selected ? asArray(selected.notes || selected.note_stream) : [];

  async function moveVendor(vendor, toState) {
    const id = pick(vendor, ['id', 'vendor_id'], null);
    if (!id) return;
    setMoving(id);
    setMoveError(null);
    const r = await apiPatch(`/api/emporium/vendors/vendor/${id}`, { pipeline_state: toState });
    setMoving(null);
    if (r.ok) board.reload();
    else setMoveError(r.error);
  }

  async function addNote(e) {
    e.preventDefault();
    if (!selectedId || !noteText.trim()) return;
    setNoteBusy(true);
    setNoteError(null);
    setNoteOk(false);
    const r = await apiPost(`/api/emporium/vendors/vendor/${selectedId}/note`, {
      note: noteText.trim(),
      author: 'Claudette',
    });
    setNoteBusy(false);
    if (r.ok) {
      setNoteText('');
      setNoteOk(true);
      board.reload();
    } else {
      setNoteError(r.error);
    }
  }

  async function uploadCredentialMeta(e) {
    e.preventDefault();
    if (!cred.vendor_id || !cred.reference.trim()) return;
    setCredBusy(true);
    setCredError(null);
    setCredOk(false);
    // Metadata only — no files, no secrets leave this form as raw uploads.
    const r = await apiPost(`/api/emporium/vendors/vendor/${cred.vendor_id}/credential-upload`, {
      credential_type: cred.credential_type,
      reference: cred.reference.trim(),
      notes: cred.notes.trim(),
      recorded_by: 'Claudette',
    });
    setCredBusy(false);
    if (r.ok) {
      setCred({ vendor_id: '', credential_type: 'IATA', reference: '', notes: '' });
      setCredOk(true);
      board.reload();
    } else {
      setCredError(r.error);
    }
  }

  return (
    <div className="montiff-page montiff-stack" data-testid="claudette-cockpit">
      <section className="montiff-panel-blue" data-testid="claudette-header">
        <Rivets />
        <div className="montiff-brand" style={{ color: 'var(--montiff-orange)' }}>SST-CLAUDETTE · JAMAICA</div>
        <h1 className="montiff-h" style={{ color: '#fff' }}>VENDOR ACQUISITION COCKPIT</h1>
        <p className="montiff-readout" style={{ fontSize: 13, color: 'var(--montiff-steel-300)', maxWidth: 680 }}>
          Claudette's working desk. She runs the human side — calls, handshakes, relationships.
          This screen tracks her pipeline, notes, and credential paperwork. It sends nothing anywhere.
        </p>
      </section>

      {board.loading && <LoadingState label="OPENING CLAUDETTE'S DESK…" />}
      {board.error && <ErrorState message={board.error} onRetry={board.reload} testid="claudette-board-error" />}
      {moveError && <ErrorState message={moveError} testid="claudette-move-error" />}

      {!board.loading && !board.error && (
        <>
          {/* Kanban with move controls */}
          <section data-testid="claudette-kanban-section">
            <PipelineBoard board={board.data} />
            <div className="montiff-panel" style={{ marginTop: 14 }} data-testid="claudette-move-panel">
              <Rivets />
              <div className="montiff-h-sm">MOVE VENDORS BETWEEN STAGES</div>
              {vendors.length === 0 && <EmptyState label="NO VENDORS IN THE PIPELINE YET" testid="claudette-vendors-empty" />}
              <div className="montiff-stack" style={{ gap: 10 }}>
                {vendors.map((v, i) => {
                  const id = String(pick(v, ['id', 'vendor_id'], i));
                  const cur = PIPELINE_STATES.indexOf(v.__state);
                  return (
                    <div className="montiff-row" key={id} data-testid={`claudette-move-row-${i}`} style={{ justifyContent: 'space-between', border: '2px solid var(--montiff-steel-100)', padding: 8 }}>
                      <div>
                        <strong style={{ fontSize: 14 }}>{pick(v, ['name', 'title'], `VENDOR ${i + 1}`)}</strong>
                        <span className="montiff-chip" style={{ marginLeft: 8 }}>{v.__state}</span>
                      </div>
                      <div className="montiff-row">
                        <button
                          className="montiff-btn small ghost"
                          data-testid={`claudette-move-back-${i}`}
                          disabled={moving === id || cur <= 0}
                          onClick={() => moveVendor(v, PIPELINE_STATES[cur - 1])}
                        >
                          ← BACK
                        </button>
                        <button
                          className="montiff-btn small secondary"
                          data-testid={`claudette-move-forward-${i}`}
                          disabled={moving === id || cur >= PIPELINE_STATES.length - 1}
                          onClick={() => moveVendor(v, PIPELINE_STATES[cur + 1])}
                        >
                          {moving === id ? '…' : `FORWARD →`}
                        </button>
                        <button
                          className={`montiff-btn small${selectedId === id ? '' : ' ghost'}`}
                          data-testid={`claudette-select-vendor-${i}`}
                          onClick={() => { setSelectedId(id); setNoteOk(false); }}
                        >
                          NOTES
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          </section>

          {/* Notes stream */}
          <section className="montiff-grid-2" data-testid="claudette-notes-section">
            <div className="montiff-panel" data-testid="claudette-notes-panel">
              <Rivets />
              <div className="montiff-h-sm">NOTE STREAM</div>
              {!selected && <EmptyState label="PICK A VENDOR ABOVE TO READ / FILE NOTES" testid="claudette-notes-empty" />}
              {selected && (
                <>
                  <div className="montiff-readout" style={{ fontWeight: 700, marginBottom: 8 }} data-testid="claudette-notes-vendor">
                    {pick(selected, ['name', 'title'], selectedId)}
                  </div>
                  {selectedNotes.length === 0 && (
                    <EmptyState label="NO NOTES FILED YET" testid="claudette-notes-none" />
                  )}
                  <div className="montiff-stack" style={{ gap: 8, marginBottom: 12 }}>
                    {selectedNotes.map((n, i) => (
                      <div className="montiff-kanban-card" key={i} data-testid={`claudette-note-${i}`}>
                        <div className="montiff-readout" style={{ fontSize: 11, color: 'var(--montiff-steel-600)' }}>
                          {pick(n, ['created_at', 'timestamp', 'date'], '')} · {pick(n, ['author', 'by'], 'Claudette')}
                        </div>
                        <div style={{ fontSize: 14 }}>{typeof n === 'string' ? n : pick(n, ['note', 'text', 'body'], '')}</div>
                      </div>
                    ))}
                  </div>
                  <form onSubmit={addNote} data-testid="claudette-note-form">
                    <div className="montiff-field">
                      <label className="montiff-label">FILE A NOTE</label>
                      <textarea
                        className="montiff-textarea"
                        data-testid="claudette-note-input"
                        value={noteText}
                        onChange={(e) => setNoteText(e.target.value)}
                        placeholder="Call outcome, handshake status, paperwork chase…"
                      />
                    </div>
                    <button type="submit" className="montiff-btn small" data-testid="claudette-note-submit" disabled={noteBusy || !noteText.trim()}>
                      {noteBusy ? 'FILING…' : 'FILE NOTE'}
                    </button>
                    {noteOk && <div className="montiff-readout" style={{ color: 'var(--montiff-green)', marginTop: 8 }} data-testid="claudette-note-ok">✓ NOTE FILED</div>}
                    {noteError && <ErrorState message={noteError} testid="claudette-note-error" />}
                  </form>
                </>
              )}
            </div>

            {/* Credential metadata */}
            <div className="montiff-panel" data-testid="claudette-credential-panel">
              <Rivets />
              <div className="montiff-h-sm">CREDENTIAL PAPERWORK</div>
              <p className="montiff-muted" style={{ fontSize: 13 }}>
                Record IATA / ARC / CLIA credential metadata here. Reference numbers only —
                Claudette keeps the actual documents.
              </p>
              <form onSubmit={uploadCredentialMeta} data-testid="claudette-credential-form">
                <div className="montiff-field">
                  <label className="montiff-label">VENDOR</label>
                  <select
                    className="montiff-select"
                    data-testid="claudette-credential-vendor-select"
                    value={cred.vendor_id}
                    onChange={(e) => setCred({ ...cred, vendor_id: e.target.value })}
                  >
                    <option value="">— SELECT —</option>
                    {vendors.map((v, i) => {
                      const id = String(pick(v, ['id', 'vendor_id'], i));
                      return <option key={id} value={id}>{pick(v, ['name', 'title'], id)}</option>;
                    })}
                  </select>
                </div>
                <div className="montiff-form-row">
                  <div className="montiff-field">
                    <label className="montiff-label">CREDENTIAL TYPE</label>
                    <select
                      className="montiff-select"
                      data-testid="claudette-credential-type-select"
                      value={cred.credential_type}
                      onChange={(e) => setCred({ ...cred, credential_type: e.target.value })}
                    >
                      {['IATA', 'ARC', 'CLIA', 'OTHER'].map((t) => <option key={t} value={t}>{t}</option>)}
                    </select>
                  </div>
                  <div className="montiff-field">
                    <label className="montiff-label">REFERENCE #</label>
                    <input
                      className="montiff-input"
                      data-testid="claudette-credential-reference-input"
                      value={cred.reference}
                      onChange={(e) => setCred({ ...cred, reference: e.target.value })}
                      placeholder="Accreditation reference"
                    />
                  </div>
                </div>
                <div className="montiff-field">
                  <label className="montiff-label">NOTES</label>
                  <input
                    className="montiff-input"
                    data-testid="claudette-credential-notes-input"
                    value={cred.notes}
                    onChange={(e) => setCred({ ...cred, notes: e.target.value })}
                    placeholder="Expiry, scope, paperwork status…"
                  />
                </div>
                <button type="submit" className="montiff-btn small secondary" data-testid="claudette-credential-submit" disabled={credBusy || !cred.vendor_id || !cred.reference.trim()}>
                  {credBusy ? 'RECORDING…' : 'RECORD CREDENTIAL'}
                </button>
                {credOk && <div className="montiff-readout" style={{ color: 'var(--montiff-green)', marginTop: 8 }} data-testid="claudette-credential-ok">✓ CREDENTIAL RECORDED</div>}
                {credError && <ErrorState message={credError} testid="claudette-credential-error" />}
              </form>
              <hr className="montiff-divider" />
              <Kv k="DESK OWNER" v="Claudette · Vendor Acquisition Lead · Jamaica" />
              <Kv k="OUTREACH" v="Human only — this screen sends nothing" />
            </div>
          </section>
        </>
      )}
    </div>
  );
}
