/**
 * montiff-ui.jsx — shared presentational primitives for the Emporium.
 * All markup assumes it renders inside .montiff-scope (EmporiumShell).
 */
import React, { useEffect, useState } from 'react';

export function Rivets() {
  return (
    <>
      <span className="montiff-rivet tl" aria-hidden="true" />
      <span className="montiff-rivet tr" aria-hidden="true" />
      <span className="montiff-rivet bl" aria-hidden="true" />
      <span className="montiff-rivet br" aria-hidden="true" />
    </>
  );
}

export function LoadingState({ label = 'CONTACTING EMPORIUM CORE…' }) {
  return (
    <div className="montiff-loading" data-testid="emporium-loading">
      <div>{label}</div>
      <div className="montiff-progress montiff-loader-bar">
        <div style={{ width: '65%' }} />
      </div>
    </div>
  );
}

export function EmptyState({ label = 'NOTHING ON THE WIRE YET', testid = 'emporium-empty' }) {
  return (
    <div className="montiff-empty" data-testid={testid}>
      {label}
    </div>
  );
}

export function ErrorState({ message = 'Something jammed the gears.', onRetry, testid = 'emporium-error' }) {
  return (
    <div className="montiff-error" data-testid={testid}>
      <div>⚠ {message}</div>
      {onRetry && (
        <div style={{ marginTop: 12 }}>
          <button className="montiff-btn small ghost" data-testid="emporium-retry-button" onClick={onRetry}>
            RETRY
          </button>
        </div>
      )}
    </div>
  );
}

/** Little labeled readout: label above, mono value below. */
export function Readout({ label, value, testid }) {
  return (
    <div data-testid={testid}>
      <div className="montiff-readout montiff-muted" style={{ fontSize: 11, letterSpacing: 1 }}>{label}</div>
      <div className="montiff-readout" style={{ fontSize: 22, fontWeight: 700 }}>{value}</div>
    </div>
  );
}

/** Key/value ledger-style row. */
export function Kv({ k, v }) {
  return (
    <div className="montiff-kv">
      <span className="k">{k}</span>
      <span className="v">{v}</span>
    </div>
  );
}

/** Coin-burst confetti overlay. Render when `burst` is true; auto-clears. */
export function CoinBurst({ burst, onDone }) {
  const [coins, setCoins] = useState([]);
  useEffect(() => {
    if (!burst) return;
    const batch = Array.from({ length: 46 }, (_, i) => ({
      id: `${Date.now()}-${i}`,
      left: Math.random() * 100,
      delay: Math.random() * 0.5,
      duration: 1.6 + Math.random() * 1.4,
      size: 10 + Math.random() * 10,
    }));
    setCoins(batch);
    const t = setTimeout(() => {
      setCoins([]);
      if (onDone) onDone();
    }, 3600);
    return () => clearTimeout(t);
  }, [burst, onDone]);

  if (!coins.length) return null;
  return (
    <div className="montiff-confetti-layer" data-testid="coin-burst-confetti" aria-hidden="true">
      {coins.map((c) => (
        <span
          key={c.id}
          className="montiff-coin"
          style={{
            left: `${c.left}%`,
            width: c.size,
            height: c.size,
            animationDelay: `${c.delay}s`,
            animationDuration: `${c.duration}s`,
          }}
        />
      ))}
    </div>
  );
}

/** Segmented progress bar. */
export function MontiffProgress({ pct, orange = false, testid }) {
  const clamped = Math.max(0, Math.min(100, Number(pct) || 0));
  return (
    <div className={`montiff-progress${orange ? ' orange' : ''}`} data-testid={testid}>
      <div style={{ width: `${clamped}%` }} />
    </div>
  );
}

/** Status dot with label for the shell status bar. */
export function StatusDot({ state = 'down', label, testid }) {
  return (
    <span className="montiff-status-item" data-testid={testid}>
      <span className={`montiff-status-dot ${state}`} aria-hidden="true" />
      <span>{label}</span>
    </span>
  );
}
