import React, { useState, useEffect } from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import { Toaster } from '@/components/ui/sonner';
import { ThemeProvider } from '@/context/ThemeContext';
import SovereignShell from '@/components/SovereignShell';
import HomePage from '@/pages/HomePage';
import MusicStudio from '@/pages/MusicStudio';
import StoryGallery from '@/pages/StoryGallery';
import StoryEditor from '@/pages/StoryEditor';
import StoryForge from '@/pages/StoryForge';
import StoryReader from '@/pages/StoryReader';
import Reader from '@/pages/Reader';
import Archive from '@/pages/Archive';
import PublishPage from '@/pages/PublishPage';
import BrowsePage from '@/pages/BrowsePage';
import RadioPage from '@/pages/RadioPage';
import ConnectPage from '@/pages/ConnectPage';
import CouncilChamber from '@/pages/CouncilChamber';
import OwnerDashboard from '@/pages/OwnerDashboard';
import SpatialVerification from '@/pages/SpatialVerification';
import GatewayTwo from '@/pages/GatewayTwo';
import ForgeEconomy from '@/pages/ForgeEconomy';
import PortraitForge from '@/pages/PortraitForge';
import VideoForge from '@/pages/VideoForge';
import SovereignDAWPage from '@/pages/SovereignDAWPage';
import UnifierPage from '@/pages/UnifierPage';
import SerpentStrikeWarRoom from '@/pages/battalion/SerpentStrikeWarRoom';
import EmpireShell from '@/pages/empire/EmpireShell';
import MeryleAssistant from '@/components/MeryleAssistant';
import '@/App.css';
// ── Emporium commerce realm (separate Montiff shell, outside SovereignShell) ──
import EmporiumShell from '@/pages/emporium/EmporiumShell';
import EmporiumDashboard from '@/pages/emporium/EmporiumDashboard';
import EmporiumBooking from '@/pages/emporium/EmporiumBooking';
import EmporiumHotels from '@/pages/emporium/EmporiumHotels';
import EmporiumHotelDetail from '@/pages/emporium/EmporiumHotelDetail';
import EmporiumCruisesCarsEvents from '@/pages/emporium/EmporiumCruisesCarsEvents';
import EmporiumRouteAssembly from '@/pages/emporium/EmporiumRouteAssembly';
import EmporiumVendors, { EmporiumVendorCategory, EmporiumVendorDossier } from '@/pages/emporium/EmporiumVendors';
import EmporiumLedger from '@/pages/emporium/EmporiumLedger';
import EmporiumTradingDesk from '@/pages/emporium/EmporiumTradingDesk';
import ClaudetteCockpit from '@/pages/emporium/ClaudetteCockpit';
import SovereignFoundation from '@/pages/emporium/SovereignFoundation';

function App() {
  const [stories, setStories] = useState([]);

  // Load stories from localStorage on mount
  useEffect(() => {
    const savedStories = localStorage.getItem('stories');
    if (savedStories) {
      setStories(JSON.parse(savedStories));
    } else {
      // Initialize with sample stories
      const sampleStories = [
        {
          id: '1',
          title: 'The Last Library',
          author: 'Elena Rodriguez',
          excerpt: 'In a world where books are forbidden, one librarian risks everything to preserve the stories of humanity...',
          content: '<h2>Chapter One: The Discovery</h2><p>The dusty tome fell open in her hands, revealing secrets long forgotten by the world above...</p>',
          coverImage: 'https://images.unsplash.com/photo-1481627834876-b7833e8f5570?w=800&q=80',
          category: 'Fiction',
          readTime: 12,
          createdAt: new Date('2024-01-15').toISOString(),
          published: true
        },
        {
          id: '2',
          title: 'Echoes of Tomorrow',
          author: 'Marcus Chen',
          excerpt: 'A scientist discovers messages from the future, but each one changes the timeline in unexpected ways...',
          content: '<h2>The First Message</h2><p>The quantum receiver hummed to life at exactly 3:33 AM, displaying a message that would change everything...</p>',
          coverImage: 'https://images.unsplash.com/photo-1419242902214-272b3f66ee7a?w=800&q=80',
          category: 'Sci-Fi',
          readTime: 15,
          createdAt: new Date('2024-01-20').toISOString(),
          published: true
        },
        {
          id: '3',
          title: 'The Art of Remembering',
          author: 'Sophia Williams',
          excerpt: 'A memoir about finding beauty in the everyday moments that shape our lives and define who we become...',
          content: '<h2>Morning Light</h2><p>There is a particular quality to morning light in August that I have never quite been able to capture in words...</p>',
          coverImage: 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=800&q=80',
          category: 'Memoir',
          readTime: 8,
          createdAt: new Date('2024-01-20').toISOString(),
          published: true
        }
      ];
      setStories(sampleStories);
      localStorage.setItem('stories', JSON.stringify(sampleStories));
    }
  }, []);

  // Save story function
  const saveStory = (story) => {
    const updatedStories = story.id 
      ? stories.map(s => s.id === story.id ? story : s)
      : [...stories, { ...story, id: Date.now().toString(), createdAt: new Date().toISOString() }];
    
    setStories(updatedStories);
    localStorage.setItem('stories', JSON.stringify(savedStories));
    return story.id || Date.now().toString();
  };

  // Delete story function
  const deleteStory = (id) => {
    const updatedStories = stories.filter(s => s.id === id);
    setStories(updatedStories);
    localStorage.setItem('stories', JSON.stringify(updatedStories));
  };

  return (
    <ThemeProvider>
      <div className="App min-h-screen">
        <BrowserRouter basename={process.env.PUBLIC_URL}>
          <Routes>
            {/* Every route lives inside the Sovereign Shell (DESIGN layer) */}
            <Route element={<SovereignShell />}>
              <Route path="/" element={<HomePage />} />
              <Route path="/music" element={<MusicStudio />} />
              <Route path="/story" element={<StoryGallery stories={stories} />} />
              <Route path="/forge" element={<StoryForge saveStory={saveStory} stories={stories} />} />
              <Route path="/forge/:id" element={<StoryForge saveStory={saveStory} stories={stories} />} />
              <Route path="/editor" element={<StoryEditor saveStory={saveStory} />} />
              <Route path="/editor/:id" element={<StoryEditor saveStory={saveStory} stories={stories} />} />
              <Route path="/story/:id" element={<StoryReader stories={stories} />} />
              <Route path="/reader/:workId" element={<Reader />} />
              <Route path="/archive" element={<Archive stories={stories} />} />
              <Route path="/publish" element={<PublishPage stories={stories} />} />
              <Route path="/browse" element={<BrowsePage />} />
              <Route path="/radio" element={<RadioPage />} />
              <Route path="/connect" element={<ConnectPage />} />
              <Route path="/council-chamber" element={<CouncilChamber />} />
              <Route path="/owner" element={<OwnerDashboard />} />
              <Route path="/spatial" element={<SpatialVerification />} />
              <Route path="/gateway" element={<GatewayTwo />} />
              <Route path="/economy" element={<ForgeEconomy />} />
              <Route path="/portrait-forge" element={<PortraitForge />} />
              <Route path="/video-forge" element={<VideoForge />} />
              <Route path="/sovereign-daw" element={<SovereignDAWPage />} />
              <Route path="/unifier" element={<UnifierPage />} />
            </Route>
            {/* The Emporium — commerce realm, own Montiff shell, no SovereignShell */}
            <Route path="/emporium/*" element={<EmporiumShell />}>
              <Route index element={<EmporiumDashboard />} />
              <Route path="foundation" element={<SovereignFoundation />} />
              <Route path="booking" element={<EmporiumBooking />} />
              <Route path="hotels" element={<EmporiumHotels />} />
              <Route path="hotels/:hotelId" element={<EmporiumHotelDetail />} />
              <Route path="cruises" element={<EmporiumCruisesCarsEvents />} />
              <Route path="cars" element={<EmporiumCruisesCarsEvents />} />
              <Route path="events" element={<EmporiumCruisesCarsEvents />} />
              <Route path="route" element={<EmporiumRouteAssembly />} />
              <Route path="vendors" element={<EmporiumVendors />} />
              <Route path="vendors/:category" element={<EmporiumVendorCategory />} />
              <Route path="vendors/:category/:vendorId" element={<EmporiumVendorDossier />} />
              <Route path="claudette" element={<ClaudetteCockpit />} />
              <Route path="ledger" element={<EmporiumLedger />} />
              <Route path="trading" element={<EmporiumTradingDesk />} />
            </Route>
            {/* Serpent Strike living battalion — Shelby's war room, top-level route */}
            <Route path="/battalion" element={<SerpentStrikeWarRoom />} />
            {/* House Sovereign Empire command — Progenitor-level dashboards */}
            <Route path="/empire-command/*" element={<EmpireShell />} />
          </Routes>
        </BrowserRouter>
        <Toaster position="top-right" />
        <MeryleAssistant />
      </div>
    </ThemeProvider>
  );
}

export default App;
