export function getPianoStyle(id) {
  return PIANO_STYLES.find((s) => s.id === id) || PIANO_STYLES[0];
}

export function pianoStylesByCategory(category) {
  return PIANO_STYLES.filter((s) => s.category === category);
}

// Build a live Tone.js instrument chain from a style recipe.
// Must be called after a user gesture (Tone.start()).
export function createPianoVoice(styleOrId) {
  const style = typeof styleOrId === 'string' ? getPianoStyle(styleOrId) : styleOrId;
  const engineName = style.engine || 'PolySynth';
  let node;
  if (engineName === 'PolySynth') {
    const voice = style.synth === 'MonoSynth' ? Tone.MonoSynth : Tone.Synth;
    node = new Tone.PolySynth(voice, style.options || {});
  } else if (engineName === 'FMSynth') {
    node = new Tone.PolySynth(Tone.FMSynth, style.options || {});
  } else if (engineName === 'AMSynth') {
    node = new Tone.PolySynth(Tone.AMSynth, style.options || {});
  } else if (engineName === 'MetalSynth') {
    node = new Tone.MetalSynth(style.options || {});
  } else if (engineName === 'MembraneSynth') {
    node = new Tone.MembraneSynth(style.options || {});
  } else {
    node = new Tone.PolySynth(Tone.Synth, style.options || {});
  }
  node.volume.value = -8;

  // effect chain
  let tail = node;
  const built = [];
  for (const fx of style.effects || []) {
    let effect = null;
    if (fx.type === 'Reverb') effect = new Tone.Reverb({ decay: fx.decay ?? 2.5, wet: fx.wet ?? 0.25 });
    else if (fx.type === 'Chorus') effect = new Tone.Chorus(fx.frequency ?? 1.5, fx.delayTime ?? 3.5, fx.depth ?? 0.4).start();
    else if (fx.type === 'Delay') effect = new Tone.FeedbackDelay(fx.delayTime ?? 0.3, fx.feedback ?? 0.3);
    else if (fx.type === 'Distortion') effect = new Tone.Distortion(fx.distortion ?? 0.2);
    else if (fx.type === 'Tremolo') effect = new Tone.Tremolo(fx.frequency ?? 5, fx.depth ?? 0.4).start();
    else if (fx.type === 'Filter') effect = new Tone.Filter(fx.frequency ?? 2000, fx.type_ || 'lowpass');
    if (effect) {
      if (fx.wet !== undefined && 'wet' in effect && fx.type !== 'Reverb') {
        try { effect.wet.value = fx.wet; } catch (e) { /* noop */ }
      }
      tail.connect(effect);
      tail = effect;
      built.push(effect);
    }
  }
  tail.toDestination();
  return { style, node, effects: built, dispose() { try { node.dispose(); built.forEach((e) => e.dispose()); } catch (e) { /* noop */ } } };
}

export default PIANO_STYLES;
