// GLOBAL THEME CONTEXT - Light/Dark Mode for Benny's Sovereign Studio
// ═══════════════════════════════════════════════════════════════════════════════

import React, { createContext, useContext, useState, useEffect } from 'react';

// Theme configurations
export const THEMES = {
  dark: {
    name: 'dark',
    // Backgrounds
    bg: 'bg-[#0D1117]',
    bgSecondary: 'bg-[#161B22]',
    bgTertiary: 'bg-[#21262D]',
    bgInput: 'bg-[#0D1117]',
    bgCard: 'bg-[#161B22]',
    bgHover: 'bg-[#21262D]',
    // Borders
    border: 'border-[#30363D]',
    borderLight: 'border-[#30363D]/50',
    // Text
    text: 'text-white',
    textSecondary: 'text-gray-400',
    textMuted: 'text-gray-500',
    textInverse: 'text-gray-900',
    // Accents
    accent: 'text-blue-400',
    accentHover: 'hover:text-blue-300',
    // Interactions
    hover: 'hover:bg-[#21262D]',
    active: 'bg-[#21262D]',
    // Special
    overlay: 'bg-black/60',
    shadow: 'shadow-lg shadow-black/20',
    // Raw values (for inline styles)
    raw: {
      bg: '#0D1117',
      bgSecondary: '#161B22',
      text: '#ffffff',
      border: '#30363D',
    }
  },
  light: {
    name: 'light',
    // Backgrounds
    bg: 'bg-[#F6F8FA]',
    bgSecondary: 'bg-white',
    bgTertiary: 'bg-[#F0F3F6]',
    bgInput: 'bg-white',
    bgCard: 'bg-white',
    bgHover: 'bg-[#F0F3F6]',
    // Borders
    border: 'border-[#D0D7DE]',
    borderLight: 'border-[#D0D7DE]/50',
    // Text
    text: 'text-gray-900',
    textSecondary: 'text-gray-600',
    textMuted: 'text-gray-500',
    textInverse: 'text-white',
    // Accents
    accent: 'text-blue-600',
    accentHover: 'hover:text-blue-700',
    // Interactions
    hover: 'hover:bg-[#F0F3F6]',
    active: 'bg-[#E8EBEF]',
    // Special
    overlay: 'bg-black/40',
    shadow: 'shadow-lg shadow-gray-300/50',
    // Raw values (for inline styles)
    raw: {
      bg: '#F6F8FA',
      bgSecondary: '#ffffff',
      text: '#111827',
      border: '#D0D7DE',
    }
  }
};

// Create context
const ThemeContext = createContext(null);

// Theme provider component
export const ThemeProvider = ({ children }) => {
  const [theme, setTheme] = useState(() => {
    // Check localStorage first
    const saved = localStorage.getItem('storyforge-theme');
    if (saved && THEMES[saved]) return saved;
    
    // Check system preference
    if (window.matchMedia && window.matchMedia('(prefers-color-scheme: light)').matches) {
      return 'light';
    }
    return 'dark';
  });

  // Update localStorage when theme changes
  useEffect(() => {
    localStorage.setItem('storyforge-theme', theme);
    
    // Also update document class for global CSS if needed
    document.documentElement.classList.remove('dark', 'light');
    document.documentElement.classList.add(theme);
  }, [theme]);

  // Listen for system theme changes
  useEffect(() => {
    const mediaQuery = window.matchMedia('(prefers-color-scheme: light)');
    const handleChange = (e) => {
      // Only auto-switch if user hasn't manually set a preference
      const saved = localStorage.getItem('storyforge-theme');
      if (!saved) {
        setTheme(e.matches ? 'light' : 'dark');
      }
    };
    
    mediaQuery.addEventListener('change', handleChange);
    return () => mediaQuery.removeEventListener('change', handleChange);
  }, []);

  const toggleTheme = () => {
    setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  };

  const value = {
    theme,
    setTheme,
    toggleTheme,
    t: THEMES[theme], // Current theme object
    isDark: theme === 'dark',
    isLight: theme === 'light',
  };

  return (
    <ThemeContext.Provider value={value}>
      {children}
    </ThemeContext.Provider>
  );
};

// Custom hook to use theme
export const useTheme = () => {
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error('useTheme must be used within a ThemeProvider');
  }
  return context;
};

// Export default for convenience
export default ThemeContext;
