/**
 * EmporiumTradingDesk.jsx — the Montiff Bourse (revenue floor).
 * GET /api/emporium/trading/market · /positions · /tape, with a scrolling
 * wire tape rendered in pure CSS.
 */
import React from 'react';
import { useApiGet, asArray, pick } from './emporiumApi';
import { Rivets, LoadingState, EmptyState, ErrorState, Readout, Kv } from './montiff-ui';

function TapeItem({ tick, i }) {
  const sym = pick(tick, ['symbol', 'pair', 'asset'], `T${i}`);
  const price = pick(tick, ['price', 'last', 'value'], '—');
  const chg = Number(pick(tick, ['change', 'change_pct', 'delta'], 0));
  const cls = chg > 0 ? '' : chg < 0 ? 'down' : 'flat';
  const arrow = chg > 0 ? '▲' : chg < 0 ? '▼' : '■';
  return (
    <span className="montiff-tape-item" data-testid={`trading-tape-item-${i}`}>
      <span className={cls}>{arrow} {sym} {typeof price === 'number' ? price.toFixed(2) : price} ({chg > 0 ? '+' : ''}{Number.isFinite(chg) ? chg.toFixed(2) : '0.00'}%)</span>
    </span>
  );
}

export default function EmporiumTradingDesk() {
  const market = useApiGet('/api/emporium/trading/market');
  const positions = useApiGet('/api/emporium/trading/positions');
  const tape = useApiGet('/api/emporium/trading/tape');

  const m = market.data || {};
  const posRows = asArray(positions.data);
  const ticks = asArray(tape.data);

  const board = [
    { label: 'FLOOR STATUS', value: pick(m, ['status', 'floor_status', 'state'], '—'), testid: 'trading-stat-status' },
    { label: 'INDEX', value: pick(m, ['index', 'bourse_index', 'value'], '—'), testid: 'trading-stat-index' },
    { label: 'VOLATILITY', value: pick(m, ['volatility', 'vol'], '—'), testid: 'trading-stat-volatility' },
    { label: 'VOLUME', value: pick(m, ['volume', 'turnover'], '—'), testid: 'trading-stat-volume' },
  ];

  return (
    <div className="montiff-page montiff-stack" data-testid="emporium-trading">
      <section className="montiff-panel" data-testid="trading-header">
        <Rivets />
        <div className="montiff-brand" style={{ color: 'var(--montiff-cobalt)' }}>MONTIFF BOURSE</div>
        <h1 className="montiff-h">TRADING DESK · REVENUE FLOOR</h1>
        <p className="montiff-muted" style={{ margin: 0 }}>
          Ledger signals feed the floor. Positions below are house paper — no real funds move until live welds.
        </p>
      </section>

      {/* Wire tape */}
      <section data-testid="trading-tape-section">
        <div className="montiff-readout montiff-muted" style={{ fontSize: 11, marginBottom: 6 }}>WIRE TAPE · LIVE FEED</div>
        {tape.loading && <LoadingState label="STRINGING THE WIRE…" />}
        {tape.error && <ErrorState message={tape.error} onRetry={tape.reload} testid="trading-tape-error" />}
        {!tape.loading && !tape.error && ticks.length === 0 && (
          <EmptyState label="TAPE IS QUIET — NO TICKS ON THE WIRE" testid="trading-tape-empty" />
        )}
        {!tape.loading && !tape.error && ticks.length > 0 && (
          <div className="montiff-tape-viewport" data-testid="trading-tape">
            <div className="montiff-tape" aria-label="Market wire tape">
              {ticks.map((t, i) => <TapeItem key={i} tick={t} i={i} />)}
              {ticks.map((t, i) => <TapeItem key={`dup-${i}`} tick={t} i={i} />)}
            </div>
          </div>
        )}
      </section>

      {/* Market board */}
      {market.loading ? (
        <LoadingState label="READING THE FLOOR…" />
      ) : market.error ? (
        <ErrorState message={market.error} onRetry={market.reload} testid="trading-market-error" />
      ) : (
        <section className="montiff-grid" data-testid="trading-market-board" style={{ gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))' }}>
          {board.map((b) => (
            <div className="montiff-panel-blue" key={b.label} data-testid={b.testid}>
              <Readout label={b.label} value={String(b.value)} />
            </div>
          ))}
        </section>
      )}

      {/* Positions */}
      <section className="montiff-panel" data-testid="trading-positions-panel">
        <Rivets />
        <div className="montiff-h-sm">OPEN POSITIONS</div>
        {positions.loading && <LoadingState label="COUNTING POSITIONS…" />}
        {positions.error && <ErrorState message={positions.error} onRetry={positions.reload} testid="trading-positions-error" />}
        {!positions.loading && !positions.error && posRows.length === 0 && (
          <EmptyState label="FLAT BOOK — NO OPEN POSITIONS" testid="trading-positions-empty" />
        )}
        {!positions.loading && !positions.error && posRows.length > 0 && (
          <div className="montiff-table-wrap" data-testid="trading-positions-table-wrap">
            <table className="montiff-table" data-testid="trading-positions-table">
              <thead><tr><th>SYMBOL</th><th>SIDE</th><th>SIZE</th><th>ENTRY</th><th>MARK</th><th>P&amp;L</th></tr></thead>
              <tbody>
                {posRows.map((p, i) => {
                  const pnl = Number(pick(p, ['pnl', 'p_l', 'profit'], 0));
                  return (
                    <tr key={pick(p, ['id', 'symbol'], i)} data-testid={`trading-position-${i}`}>
                      <td className="montiff-readout" style={{ fontWeight: 700 }}>{pick(p, ['symbol', 'asset', 'pair'], '—')}</td>
                      <td>{pick(p, ['side', 'direction'], '—')}</td>
                      <td className="montiff-readout">{pick(p, ['size', 'qty', 'quantity'], '—')}</td>
                      <td className="montiff-readout">{pick(p, ['entry', 'entry_price'], '—')}</td>
                      <td className="montiff-readout">{pick(p, ['mark', 'mark_price', 'last'], '—')}</td>
                      <td className="montiff-readout" style={{ fontWeight: 700, color: pnl >= 0 ? 'var(--montiff-green)' : 'var(--montiff-red)' }}>
                        {Number.isFinite(pnl) ? (pnl >= 0 ? '+' : '') + pnl.toFixed(2) : '—'}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </section>

      {/* Market movers */}
      {!market.loading && !market.error && (
        <section className="montiff-panel-flat" data-testid="trading-movers">
          <div className="montiff-h-sm">FLOOR NOTES</div>
          <Kv k="SIGNAL SOURCE" v={pick(m, ['signal_source', 'source'], 'emporium_ledger → market signals')} />
          <Kv k="SETTLEMENT" v={pick(m, ['settlement', 'settle'], 'T+1 sovereign')} />
          <Kv k="RISK NOTE" v="Paper floor until vendor live-flips land." />
        </section>
      )}
    </div>
  );
}
