export function allAgents() {
  const agents = [
    { ...COMMANDER, squad: 'Command' },
    { ...XO, squad: 'Command' },
  ];
  for (const s of SQUADS) {
    for (const m of s.members) agents.push({ ...m, squad: s.name });
  }
  return agents;
}
