// ═══════════════════════════════════════════════════════════════════════════════
// UNIFIED SENSORY ENGINE — KITSUNE + COLOSSUS, synchronized by CLYDE
// Owner canon: KITSUNE generates 48-channel spatial audio, COLOSSUS generates
// geometry-based video, CLYDE synchronizes both with virtual HDMI timing.
// Together they form the Unified Sensory Engine.
//
// Honest architecture: both engines run in the browser (Web Audio for audio,
// canvas 2D for video). This module binds them to ONE shared CLYDE-compatible
// clock so audio and video share virtual-HDMI timing, and wires the
// audio-reactive path: KITSUNE ring levels drive COLOSSUS seed energy.
//
// CLYDE port: LIVE — src/lib/clyde.js ("Crystallized Loop Yarn Desolation
// Emergence"). The shared clock below delegates to the real engine; the port
// shape is unchanged so KITSUNE/COLOSSUS consumers keep working.
// ═══════════════════════════════════════════════════════════════════════════════

import * as kitsune from './kitsune.js';
import { createRenderer, createSeed, COLOSSUS_FIDELITY_MODES } from './colossus.js';
import {
  init as clydeInit,
  now as clydeNow,
  setAvOffsetMs as clydeSetAv,
  getAvOffsetMs as clydeGetAv,
  engineStatus as clydeStatus,
  // Session-Negotiated Timing Contract (Option 2, Variation 3):
  // Base negotiates+seals the timeline, Active ignites the long run,
  // Recovery stays armed for the whole session.
  negotiateTiming as clydeNegotiate,
  sealTimeline as clydeSeal,
  ignitePulse as clydeIgnite,
  senseRupture as clydeSense,
  renegotiate as clydeRenegotiate,
  realignEngines as clydeRealign,
  resumeTimeline as clydeResume,
  getTimeline as clydeGetTimeline,
} from './clyde.js';

// ── Shared CLYDE clock ───────────────────────────────────────────────────────
// One REAL CLYDE engine clock for both engines = virtual-HDMI A/V sync.
// Same port shape as before ({protocol, avOffsetMs, getTimestamp(),
// setAvOffset}) so every consumer keeps working; the internals are now the
// live CLYDE engine (src/lib/clyde.js) instead of a performance.now stub.

const sharedClock = {
  protocol: 'CLYDE-1',
  get avOffsetMs() { return clydeGetAv(); },
  set avOffsetMs(ms) { clydeSetAv(ms); },
  getTimestamp() {
    return clydeNow();
  },
  setAvOffset(ms) {
    return clydeSetAv(ms);
  },
};

export function getClydeClock() {
  return sharedClock;
}

// ── Engine binding ───────────────────────────────────────────────────────────

let renderer = null;
let rafId = 0;
let running = false;
let audioReactive = false;
let lastStatus = null;
let contractTimelineId = null; // sealed+ignited CLYDE timeline (contract lifecycle)

/**
 * Audio-reactive mapping (documented):
 *   KITSUNE ring levels (4 RMS values 0..1, updated ~7×/s by the engine)
 *     → COLOSSUS seed energy 0..2 per frame.
 *   Mapping: energy = 0.35 + 1.65 × mean(ringLevels), smoothed per frame.
 *   Ring 1 (core) dominates low-frequency seeds, ring 4 (ultra) adds shimmer
 *   to abstract seeds — implemented as a per-seed weight by index.
 */
function ringLevelsToEnergy(levels, seedIndex) {
  const mean = levels.reduce((a, b) => a + b, 0) / Math.max(1, levels.length);
  const ringBias = levels.length > 0 ? levels[seedIndex % levels.length] : mean;
  return Math.max(0, Math.min(2, 0.35 + 1.3 * mean + 0.35 * ringBias));
}

/**
 * Init the unified engine. Call from a user gesture (starts AudioContext).
 * @param {object} opts — { canvas, audioContext }
 */
export async function init({ canvas, audioContext } = {}) {
  if (renderer) return lastStatus;
  if (!canvas) throw new TypeError('init requires a canvas for COLOSSUS');
  // The real CLYDE engine is the shared master clock from here on.
  clydeInit({ audioContext });
  // ── Contract lifecycle: Base (negotiate + seal) → Active (ignite) ──
  // Recovery stays armed for the whole session via serviceContracts().
  const negotiation = clydeNegotiate({
    frameRates: [60],
    granularityMs: 1000 / 60,
    useAudioClock: !!audioContext,
    hdmiProfile: '1080p60',
    target: 'internal',
  });
  const base = clydeSeal(negotiation);
  clydeIgnite(base.timelineId);
  contractTimelineId = base.timelineId;
  await kitsune.init({ context: audioContext });
  renderer = createRenderer(canvas);
  renderer.attachClydeClock(sharedClock);
  // Default seeds: one per fidelity mode so the field is alive immediately.
  for (const mode of COLOSSUS_FIDELITY_MODES) {
    renderer.addSeed(createSeed({ source_type: 'synthetic', fidelity_mode: mode }));
  }
  lastStatus = engineStatus();
  return lastStatus;
}

function loop() {
  if (!running || !renderer) return;
  const t = sharedClock.getTimestamp();
  let energy;
  if (audioReactive) {
    try {
      const levels = kitsune.getRingLevels();
      energy = ringLevelsToEnergy(levels, 0);
      renderer.setEnergy(energy);
    } catch (err) { /* audio not ready — render silent */ }
  }
  renderer.renderFrame(t, energy !== undefined ? { energy } : {});
  rafId = requestAnimationFrame(loop);
}

export function start() {
  if (!renderer || running) return false;
  running = true;
  loop();
  return true;
}

export function stop() {
  running = false;
  if (rafId) {
    cancelAnimationFrame(rafId);
    rafId = 0;
  }
}

export function setAudioReactive(on) {
  audioReactive = !!on;
  return audioReactive;
}

export function isAudioReactive() {
  return audioReactive;
}

/** Timeline ID of the sealed+ignited CLYDE contract (null before init). */
export function getContractTimelineId() {
  return contractTimelineId;
}

/**
 * Service the Recovery Contract: sense rupture, and if ruptured run the
 * full self-healing chain — renegotiate (same timeline ID) → realign the
 * engines (re-attach the CLYDE clock to both consumers) → resume.
 * Safe to call on a poll loop; no-ops when the timeline is healthy.
 */
export function serviceContracts() {
  if (!contractTimelineId) return null;
  let sensed;
  try {
    sensed = clydeSense(contractTimelineId);
  } catch (err) {
    return { error: String(err && err.message || err) };
  }
  if (!sensed.ruptured) return { ruptured: false, timelineId: contractTimelineId };
  const healed = { ruptured: true, trigger: sensed.trigger, timelineId: contractTimelineId };
  try {
    healed.renegotiated = clydeRenegotiate(contractTimelineId, sensed.trigger);
    healed.realignment = clydeRealign(contractTimelineId);
    // Real consumer re-attach: both engines re-anchor to the CLYDE master.
    if (renderer) renderer.attachClydeClock(sharedClock);
    healed.resumed = clydeResume(contractTimelineId);
    healed.healed = true;
  } catch (err) {
    healed.healed = false;
    healed.error = String(err && err.message || err);
  }
  return healed;
}

/** Live contract triple for the console. */
export function getContractStatus() {
  if (!contractTimelineId) return null;
  try {
    return clydeGetTimeline(contractTimelineId);
  } catch (err) {
    return null;
  }
}

export function getRenderer() {
  return renderer;
}

export async function shutdown() {
  stop();
  if (renderer) {
    renderer.destroy();
    renderer = null;
  }
  try { await kitsune.shutdown(); } catch (err) { /* noop */ }
  lastStatus = null;
}

export function engineStatus() {
  const k = kitsune.engineStatus();
  return {
    name: 'UNIFIED-SENSORY-ENGINE',
    audio: { engine: 'KITSUNE', running: k.running, channels: k.channels },
    video: { engine: 'COLOSSUS', seeds: renderer ? renderer.seedIds().length : 0 },
    sync: {
      engine: 'CLYDE',
      protocol: sharedClock.protocol,
      avOffsetMs: sharedClock.avOffsetMs,
      port: 'live',
      spec: 'CLYDE-1',
      contracts: 'Option 2 Variation 3 (base/active/recovery)',
      timelineId: contractTimelineId,
      status: clydeStatus(),
    },
    audioReactive,
    running,
  };
}
