import React from 'react';
import { empireStyles as s } from './EmpireShell';
import { KPIS, BATTALIONS, EMPIRE_SQUADS, TOP_SQUADS, LEADERBOARD } from './empireData';

function KpiCard({ kpi }) {
  return (
    <div style={s.panel}>
      <div style={{ fontSize: 11, letterSpacing: 2, color: '#8b98a9' }}>{kpi.label}</div>
      <div style={{ display: 'flex', alignItems: 'baseline', gap: 10, marginTop: 6 }}>
        <span style={{ fontSize: 30, fontWeight: 800, color: '#e8b34b' }}>{kpi.value}</span>
        <span style={{
          fontSize: 12, fontWeight: 700, padding: '3px 8px', borderRadius: 10,
          background: kpi.up ? '#12351f' : '#3a1414', color: kpi.up ? '#4ade80' : '#f87171',
        }}>
          {kpi.up ? '↑' : '↓'} {kpi.delta}
        </span>
      </div>
    </div>
  );
}

function BattalionBars() {
  const max = Math.max(...BATTALIONS.map((b) => b.target));
  return (
    <div style={s.panel}>
      <div style={s.panelTitle}>BATTALION PERFORMANCE — ACTUAL VS TARGET (SAMPLE)</div>
      {BATTALIONS.map((b) => (
        <div key={b.id} style={{ marginBottom: 12 }}>
          <div style={{ fontSize: 12, marginBottom: 4 }}>
            <b style={{ color: '#7dd3fc' }}>{b.name} ({b.code})</b>
            <span style={{ color: '#8b98a9' }}> — €{b.actual.toFixed(1)}M / €{b.target.toFixed(1)}M</span>
          </div>
          <div style={{ height: 14, background: '#141b26', borderRadius: 7, position: 'relative' }}>
            <div style={{ width: `${(b.target / max) * 100}%`, height: '100%', background: '#1c2530', borderRadius: 7 }} />
            <div style={{
              width: `${(b.actual / max) * 100}%`, height: '100%', background: '#4ade80',
              borderRadius: 7, position: 'absolute', top: 0, left: 0,
            }} />
          </div>
        </div>
      ))}
      <div style={{ fontSize: 10, color: '#5b6b7f' }}>■ actual &nbsp; ■ target</div>
    </div>
  );
}

function HierarchyMap() {
  return (
    <div style={s.panel}>
      <div style={s.panelTitle}>SALES HIERARCHY MAP — 3 BATTALIONS · 18 SQUADS</div>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 10 }}>
        {BATTALIONS.map((b) => (
          <div key={b.id} style={{ background: '#141b26', borderRadius: 6, padding: 10 }}>
            <div style={{ fontSize: 13, fontWeight: 800, color: '#7dd3fc', marginBottom: 8 }}>
              BATTALION: {b.name}
            </div>
            {EMPIRE_SQUADS.filter((q) => q.battalionCode === b.code).map((q) => (
              <div key={q.squad_id} style={{
                display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                background: '#0a0e14', borderRadius: 4, padding: '6px 8px', marginBottom: 6, fontSize: 11,
              }}>
                <span>{q.name}</span>
                <button style={{
                  fontSize: 10, padding: '3px 8px', borderRadius: 3, cursor: 'pointer',
                  background: '#1c2530', color: '#e8b34b', border: '1px solid #e8b34b', fontFamily: 'inherit',
                }}>
                  QUICK ACTION
                </button>
              </div>
            ))}
          </div>
        ))}
      </div>
    </div>
  );
}

function TopSquads() {
  const max = Math.max(...TOP_SQUADS.map((t) => t.volume));
  return (
    <div style={s.panel}>
      <div style={s.panelTitle}>TOP PERFORMING SQUADS</div>
      {TOP_SQUADS.map((t, i) => (
        <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6, fontSize: 11 }}>
          <span style={{ width: 150, color: '#c3cedd' }}>{t.name}</span>
          <div style={{ flex: 1, height: 10, background: '#141b26', borderRadius: 5 }}>
            <div style={{
              width: `${(t.volume / max) * 100}%`, height: '100%',
              background: i === 0 ? '#e8b34b' : '#3b82f6', borderRadius: 5,
            }} />
          </div>
        </div>
      ))}
    </div>
  );
}

function Leaderboard() {
  return (
    <div style={s.panel}>
      <div style={s.panelTitle}>AGENT LEADERBOARD — TOP 15 (SAMPLE IDENTITIES)</div>
      <div style={{ maxHeight: 320, overflowY: 'auto' }}>
        <table style={{ width: '100%', fontSize: 11, borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ color: '#5b6b7f', textAlign: 'left' }}>
              <th>#</th><th>AGENT</th><th>SQUAD</th><th>BN</th><th>SALES</th><th>QUOTA</th>
            </tr>
          </thead>
          <tbody>
            {LEADERBOARD.map((a) => (
              <tr key={a.rank} style={{ borderTop: '1px solid #1c2530', color: '#c3cedd' }}>
                <td style={{ color: '#e8b34b', fontWeight: 700 }}>{a.rank}</td>
                <td>{a.name}</td><td>{a.squad}</td><td>{a.battalion}</td>
                <td>{a.sales}</td><td>{a.quota}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

export default function EmpireDashboard() {
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
      <div style={s.grid4}>
        {KPIS.map((k) => <KpiCard key={k.id} kpi={k} />)}
      </div>
      <div style={s.grid2}>
        <BattalionBars />
        <HierarchyMap />
      </div>
      <div style={s.grid2}>
        <TopSquads />
        <Leaderboard />
      </div>
    </div>
  );
}
