// ═══════════════════════════════════════════════════════════════════════════════
// COVENANT STUDIO FORGE 66 — RADIO PAGE
// Gateway Two Integration | Persona DJ Mode | Global Stations
// ═══════════════════════════════════════════════════════════════════════════════

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Radio, Play, Pause, SkipForward, SkipBack, Volume2, VolumeX,
  Search, Heart, Globe, Music, Mic, Sparkles, Users, Clock,
  ChevronRight, Star, Headphones, Waves, Key, RefreshCw, Shield,
  AlertCircle, CheckCircle, Zap
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Slider } from '@/components/ui/slider';
import { useTheme } from '@/context/ThemeContext';
import { toast } from 'sonner';

const API_URL = process.env.REACT_APP_BACKEND_URL || '';

// ═══════════════════════════════════════════════════════════════════════════════
// GATEWAY TWO SERVICE CONFIG
// ═══════════════════════════════════════════════════════════════════════════════

const GATEWAY_SERVICES = {
  spotify: { name: 'Spotify', icon: '🎵', color: '#1DB954', service: 'spotify' },
  tunein: { name: 'TuneIn', icon: '📻', color: '#14D8CC', service: 'tunein' },
  pandora: { name: 'Pandora', icon: '🎧', color: '#00A0EE', service: 'pandora' }
};

// ═══════════════════════════════════════════════════════════════════════════════
// STATION COLOR MAPPING
// ═══════════════════════════════════════════════════════════════════════════════

const GENRE_COLORS = {
  lofi: 'from-purple-600 to-indigo-800',
  jpop: 'from-pink-500 to-red-500',
  kpop: 'from-blue-500 to-purple-500',
  synthwave: 'from-purple-500 to-pink-500',
  jazz: 'from-amber-600 to-amber-800',
  classical: 'from-amber-400 to-yellow-600',
  techno: 'from-green-500 to-teal-600',
  electronic: 'from-cyan-500 to-blue-600',
  ambient: 'from-blue-400 to-purple-400',
  metal: 'from-gray-700 to-red-900',
  afrobeats: 'from-green-600 to-yellow-500',
  rnb: 'from-purple-500 to-pink-500',
  hiphop: 'from-gray-800 to-gray-900',
  latin: 'from-yellow-500 to-green-500',
  world: 'from-orange-500 to-red-600',
  default: 'from-gray-600 to-gray-800'
};

const PERSONA_COLORS = {
  olga: 'from-purple-600 to-indigo-800',
  kayura: 'from-violet-600 to-purple-800',
  yumiko: 'from-red-600 to-rose-800',
  meryle: 'from-amber-600 to-orange-700',
  larry: 'from-amber-500 to-yellow-600',
  lisa: 'from-pink-500 to-rose-600',
  ajikko: 'from-orange-500 to-red-600'
};

const getStationColor = (station) => {
  if (station.host_persona && PERSONA_COLORS[station.host_persona]) {
    return PERSONA_COLORS[station.host_persona];
  }
  const genre = (station.genres?.[0] || '').toLowerCase();
  return GENRE_COLORS[genre] || GENRE_COLORS.default;
};

const GENRES = ['All', 'Sovereign', 'lofi', 'electronic', 'jazz', 'classical', 'world', 'jpop', 'kpop', 'metal', 'ambient', 'synthwave'];
const REGIONS = ['All', 'SOVEREIGN', 'JP', 'KR', 'US', 'UK', 'DE', 'BR', 'Global'];

// ═══════════════════════════════════════════════════════════════════════════════
// RADIO PAGE COMPONENT — GATEWAY TWO INTEGRATED
// ═══════════════════════════════════════════════════════════════════════════════

const RadioPage = () => {
  const { isDark, t } = useTheme();
  const [stations, setStations] = useState([]);
  const [sovereignStations, setSovereignStations] = useState([]);
  const [currentStation, setCurrentStation] = useState(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [volume, setVolume] = useState(75);
  const [isMuted, setIsMuted] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedGenre, setSelectedGenre] = useState('All');
  const [selectedRegion, setSelectedRegion] = useState('All');
  const [favorites, setFavorites] = useState([]);
  const [showPlayer, setShowPlayer] = useState(false);
  const [isLoadingStations, setIsLoadingStations] = useState(true);
  const [nowPlaying, setNowPlaying] = useState(null);
  const [wsConnection, setWsConnection] = useState(null);
  
  // Gateway Two State
  const [gatewayStatus, setGatewayStatus] = useState({});
  const [activeService, setActiveService] = useState(null);
  const [skeletonKeyStatus, setSkeletonKeyStatus] = useState({});
  const [isConnecting, setIsConnecting] = useState(false);
  const [showGatewayPanel, setShowGatewayPanel] = useState(false);
  const userId = 'forge_radio_user';
  
  // ═══════════════════════════════════════════════════════════════════════════════
  // FETCH STATIONS FROM RADIO GATEWAY API
  // ═══════════════════════════════════════════════════════════════════════════════
  
  const fetchStations = useCallback(async () => {
    setIsLoadingStations(true);
    try {
      // Fetch all stations
      const response = await fetch(`${API_URL}/api/radio/stations?limit=100`);
      if (response.ok) {
        const data = await response.json();
        setStations(data);
        
        // Filter sovereign stations
        const sovereign = data.filter(s => s.country === 'SOVEREIGN' || s.host_persona);
        setSovereignStations(sovereign);
      }
    } catch (err) {
      console.error('Error fetching stations:', err);
      toast.error('Failed to load radio stations');
    } finally {
      setIsLoadingStations(false);
    }
  }, []);
  
  useEffect(() => {
    fetchStations();
  }, [fetchStations]);
  
  // ═══════════════════════════════════════════════════════════════════════════════
  // GATEWAY TWO - FETCH SERVICE STATUS
  // ═══════════════════════════════════════════════════════════════════════════════
  
  const fetchGatewayStatus = useCallback(async () => {
    try {
      const response = await fetch(`${API_URL}/api/gateway/stats`);
      if (response.ok) {
        const data = await response.json();
        setGatewayStatus(data);
      }
    } catch (err) {
      console.error('Gateway status fetch error:', err);
    }
  }, []);
  
  const fetchSkeletonKeyStatus = useCallback(async (service) => {
    try {
      const response = await fetch(`${API_URL}/api/gateway/key/status/${userId}/${service}`);
      if (response.ok) {
        const data = await response.json();
        setSkeletonKeyStatus(prev => ({ ...prev, [service]: data }));
        return data;
      }
    } catch (err) {
      console.error(`Skeleton key status error for ${service}:`, err);
    }
    return null;
  }, [userId]);
  
  useEffect(() => {
    fetchGatewayStatus();
    // Check skeleton key status for audio services
    ['spotify', 'tunein', 'pandora'].forEach(service => fetchSkeletonKeyStatus(service));
  }, [fetchGatewayStatus, fetchSkeletonKeyStatus]);
  
  // ═══════════════════════════════════════════════════════════════════════════════
  // GATEWAY TWO - CONNECT TO SERVICE
  // ═══════════════════════════════════════════════════════════════════════════════
  
  const connectToService = async (service) => {
    setIsConnecting(true);
    try {
      const response = await fetch(`${API_URL}/api/gateway/shadow/create`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ user_id: userId, service })
      });
      
      const data = await response.json();
      
      if (response.ok) {
        toast.success(`Shadow identity created for ${GATEWAY_SERVICES[service]?.name || service}`);
        setActiveService(service);
        fetchSkeletonKeyStatus(service);
      } else if (response.status === 400 && data.detail?.includes('already exists')) {
        // Shadow exists, just refresh the key
        await refreshSkeletonKey(service);
      } else {
        toast.error(data.detail || 'Connection failed');
      }
    } catch (err) {
      toast.error('Gateway connection error');
      console.error(err);
    } finally {
      setIsConnecting(false);
    }
  };
  
  const refreshSkeletonKey = async (service) => {
    try {
      const response = await fetch(`${API_URL}/api/gateway/key/refresh`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ user_id: userId, service })
      });
      
      const data = await response.json();
      
      if (response.ok) {
        toast.success(`Skeleton key refreshed for ${GATEWAY_SERVICES[service]?.name || service}`);
        setActiveService(service);
        fetchSkeletonKeyStatus(service);
        return true;
      } else {
        toast.error(data.detail || 'Key refresh failed');
      }
    } catch (err) {
      toast.error('Key refresh error');
      console.error(err);
    }
    return false;
  };
  
  // ═══════════════════════════════════════════════════════════════════════════════
  // GATEWAY TWO - ACCESS SERVICE FOR PLAYBACK
  // ═══════════════════════════════════════════════════════════════════════════════
  
  const accessServiceForPlayback = async (service, action) => {
    try {
      const response = await fetch(`${API_URL}/api/gateway/access/${service}?user_id=${userId}&action=${action}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' }
      });
      
      const data = await response.json();
      
      if (response.ok) {
        if (data.status === 'fallback') {
          toast.info(`Using fallback: ${data.fallback_service}`);
          return { ...data, useFallback: true };
        }
        return { ...data, authorized: true };
      } else if (response.status === 401) {
        toast.warning('Skeleton key expired. Refreshing...');
        const refreshed = await refreshSkeletonKey(service);
        if (refreshed) {
          return accessServiceForPlayback(service, action);
        }
      } else {
        toast.error(data.detail || 'Access denied');
      }
    } catch (err) {
      console.error('Service access error:', err);
    }
    return { authorized: false };
  };

  // Filter stations
  const filteredStations = stations.filter(station => {
    const matchesSearch = station.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                         (station.genres || []).some(g => g.toLowerCase().includes(searchQuery.toLowerCase()));
    const matchesGenre = selectedGenre === 'All' || 
                        (station.genres || []).some(g => g.toLowerCase() === selectedGenre.toLowerCase()) || 
                        (selectedGenre === 'Sovereign' && (station.country === 'SOVEREIGN' || station.host_persona));
    const matchesRegion = selectedRegion === 'All' || station.country === selectedRegion;
    return matchesSearch && matchesGenre && matchesRegion;
  });

  // Play station - now with Gateway Two integration + WebSocket
  const playStation = async (station) => {
    // Close existing WebSocket if any
    if (wsConnection) {
      wsConnection.close();
      setWsConnection(null);
    }
    
    // Determine which service to use based on station type
    const service = station.country === 'SOVEREIGN' || station.host_persona ? 'spotify' : 
                   (station.genres || []).some(g => g.toLowerCase().includes('lofi')) ? 'spotify' :
                   ['JP', 'KR'].includes(station.country) ? 'tunein' : 'pandora';
    
    // Check if we have an active skeleton key for this service
    const keyStatus = skeletonKeyStatus[service];
    
    if (!keyStatus?.has_key || keyStatus?.status === 'expired') {
      toast.info(`Connecting to ${GATEWAY_SERVICES[service]?.name || service} via Gateway Two...`);
      await connectToService(service);
    }
    
    // Access the service for playback
    const access = await accessServiceForPlayback(service, `play_station_${station.id}`);
    
    if (access.authorized || access.useFallback) {
      const stationWithColor = {
        ...station,
        color: getStationColor(station),
        gatewayService: access.useFallback ? access.fallback_service : service
      };
      
      setCurrentStation(stationWithColor);
      setIsPlaying(true);
      setShowPlayer(true);
      setActiveService(access.useFallback ? access.fallback_service : service);
      setNowPlaying(`Now Playing on ${station.name}`);
      
      // Connect to WebSocket for metadata
      try {
        const wsProtocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
        const wsHost = API_URL.replace('https://', '').replace('http://', '');
        const ws = new WebSocket(`${wsProtocol}//${wsHost}/api/radio/ws?stationId=${station.id}`);
        
        ws.onmessage = (event) => {
          try {
            const data = JSON.parse(event.data);
            if (data.type === 'metadata') {
              setNowPlaying(data.payload);
            }
          } catch (e) {
            // Binary audio data - would be processed by audio player
          }
        };
        
        ws.onerror = (err) => console.error('WebSocket error:', err);
        ws.onclose = () => console.log('WebSocket closed');
        
        setWsConnection(ws);
      } catch (err) {
        console.error('WebSocket connection failed:', err);
      }
      
      toast.success(`Now playing: ${station.name} via Gateway Two`);
    }
  };

  // Toggle favorite
  const toggleFavorite = (stationId) => {
    setFavorites(prev => 
      prev.includes(stationId) 
        ? prev.filter(id => id !== stationId)
        : [...prev, stationId]
    );
  };

  return (
    <div className={`min-h-screen ${isDark ? 'bg-gray-950' : 'bg-gray-100'}`}>
      {/* Header */}
      <div className={`sticky top-0 z-40 ${isDark ? 'bg-gray-950/95' : 'bg-white/95'} backdrop-blur-xl border-b ${isDark ? 'border-gray-800' : 'border-gray-200'}`}>
        <div className="max-w-7xl mx-auto px-6 py-4">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-xl bg-gradient-to-br from-amber-500 to-orange-600">
                <Radio className="w-6 h-6 text-white" />
              </div>
              <div>
                <h1 className={`text-2xl font-bold ${isDark ? 'text-white' : 'text-gray-900'}`}>
                  Forge Radio
                </h1>
                <p className={`text-sm ${isDark ? 'text-gray-400' : 'text-gray-600'}`}>
                  100,000+ stations • Gateway Two Enabled
                </p>
              </div>
            </div>
            
            <div className="flex items-center gap-3">
              {/* Gateway Two Status Toggle */}
              <Button
                variant="outline"
                size="sm"
                onClick={() => setShowGatewayPanel(!showGatewayPanel)}
                className={`flex items-center gap-2 ${activeService ? 'border-green-500 text-green-500' : ''}`}
                data-testid="gateway-toggle-btn"
              >
                <Shield className="w-4 h-4" />
                Gateway Two
                {activeService && <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse" />}
              </Button>
              
              {/* Search */}
              <div className="relative w-80">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
                <Input
                  placeholder="Search stations, genres..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className={`pl-10 ${isDark ? 'bg-gray-800 border-gray-700' : 'bg-gray-100 border-gray-300'}`}
                  data-testid="radio-search"
                />
              </div>
            </div>
          </div>

          {/* Gateway Two Status Panel */}
          <AnimatePresence>
            {showGatewayPanel && (
              <motion.div
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: 'auto' }}
                exit={{ opacity: 0, height: 0 }}
                className={`mb-4 p-4 rounded-xl ${isDark ? 'bg-gray-800/50' : 'bg-white'} border ${isDark ? 'border-gray-700' : 'border-gray-200'}`}
                data-testid="gateway-panel"
              >
                <div className="flex items-center gap-2 mb-3">
                  <Key className="w-4 h-4 text-amber-500" />
                  <span className={`font-semibold ${isDark ? 'text-white' : 'text-gray-900'}`}>Shadow Access Layer</span>
                </div>
                
                <div className="grid grid-cols-3 gap-3">
                  {Object.entries(GATEWAY_SERVICES).map(([key, svc]) => {
                    const status = skeletonKeyStatus[key];
                    const isActive = status?.has_key && status?.status === 'active';
                    const isExpired = status?.status === 'expired';
                    
                    return (
                      <div 
                        key={key}
                        className={`p-3 rounded-lg ${isDark ? 'bg-gray-900' : 'bg-gray-100'} border ${
                          isActive ? 'border-green-500/50' : isExpired ? 'border-yellow-500/50' : 'border-gray-600'
                        }`}
                      >
                        <div className="flex items-center justify-between mb-2">
                          <span className="text-lg">{svc.icon}</span>
                          {isActive ? (
                            <CheckCircle className="w-4 h-4 text-green-500" />
                          ) : isExpired ? (
                            <AlertCircle className="w-4 h-4 text-yellow-500" />
                          ) : (
                            <div className="w-4 h-4 rounded-full border-2 border-gray-500" />
                          )}
                        </div>
                        <p className={`text-sm font-medium ${isDark ? 'text-white' : 'text-gray-900'}`}>{svc.name}</p>
                        {isActive && status?.hours_remaining && (
                          <p className="text-xs text-green-500">{status.hours_remaining}h remaining</p>
                        )}
                        {!isActive && (
                          <Button 
                            size="sm" 
                            variant="ghost" 
                            className="mt-2 w-full text-xs"
                            onClick={() => isExpired ? refreshSkeletonKey(key) : connectToService(key)}
                            disabled={isConnecting}
                          >
                            {isConnecting ? <RefreshCw className="w-3 h-3 animate-spin" /> : isExpired ? 'Refresh Key' : 'Connect'}
                          </Button>
                        )}
                      </div>
                    );
                  })}
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          {/* Filters */}
          <div className="flex gap-4">
            {/* Genre Filter */}
            <div className="flex gap-2 overflow-x-auto pb-2">
              {GENRES.map(genre => (
                <Button
                  key={genre}
                  variant={selectedGenre === genre ? 'default' : 'outline'}
                  size="sm"
                  onClick={() => setSelectedGenre(genre)}
                  className={selectedGenre === genre ? 'bg-amber-500 hover:bg-amber-600' : ''}
                >
                  {genre}
                </Button>
              ))}
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-6 py-8">
        {/* Sovereign Radio Section */}
        <section className="mb-12">
          <div className="flex items-center gap-3 mb-6">
            <Sparkles className="w-5 h-5 text-amber-500" />
            <h2 className={`text-xl font-bold ${isDark ? 'text-white' : 'text-gray-900'}`}>
              Sovereign Radio — Council DJ Mode
            </h2>
          </div>
          
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
            {isLoadingStations ? (
              <div className="col-span-full flex justify-center py-8">
                <RefreshCw className="w-6 h-6 animate-spin text-amber-500" />
              </div>
            ) : sovereignStations.map((station, i) => (
              <motion.div
                key={station.id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: i * 0.05 }}
                whileHover={{ scale: 1.02 }}
                onClick={() => playStation(station)}
                className={`cursor-pointer p-4 rounded-xl bg-gradient-to-br ${getStationColor(station)} relative overflow-hidden group`}
                data-testid={`station-${station.id}`}
              >
                {/* Live indicator */}
                <div className="absolute top-3 right-3 flex items-center gap-1.5 px-2 py-1 rounded-full bg-black/30 backdrop-blur-sm">
                  <span className="w-2 h-2 rounded-full bg-red-500 animate-pulse" />
                  <span className="text-white text-xs font-medium">LIVE</span>
                </div>

                <div className="flex items-center gap-3 mb-3">
                  <div className="w-12 h-12 rounded-full bg-white/20 flex items-center justify-center">
                    <Mic className="w-6 h-6 text-white" />
                  </div>
                  <div>
                    <h3 className="text-white font-bold">{station.name}</h3>
                    <p className="text-white/70 text-sm">
                      {station.host_persona ? `Hosted by ${station.host_persona.charAt(0).toUpperCase() + station.host_persona.slice(1)}` : station.city}
                    </p>
                  </div>
                </div>

                <div className="flex items-center justify-between">
                  <span className="text-white/60 text-xs flex items-center gap-1">
                    <Headphones className="w-3 h-3" />
                    {station.bitrate || 128}kbps
                  </span>
                  <div className="opacity-0 group-hover:opacity-100 transition-opacity">
                    <div className="p-2 rounded-full bg-white/20">
                      <Play className="w-4 h-4 text-white" />
                    </div>
                  </div>
                </div>
              </motion.div>
            ))}
          </div>
        </section>

        {/* All Stations */}
        <section>
          <div className="flex items-center gap-3 mb-6">
            <Globe className="w-5 h-5 text-amber-500" />
            <h2 className={`text-xl font-bold ${isDark ? 'text-white' : 'text-gray-900'}`}>
              Global Stations
            </h2>
            <span className={`text-sm ${isDark ? 'text-gray-500' : 'text-gray-600'}`}>
              {filteredStations.length} stations
            </span>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {isLoadingStations ? (
              <div className="col-span-full flex justify-center py-8">
                <RefreshCw className="w-6 h-6 animate-spin text-amber-500" />
              </div>
            ) : filteredStations.filter(s => s.country !== 'SOVEREIGN' && !s.host_persona).map((station, i) => (
              <motion.div
                key={station.id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: i * 0.03 }}
                className={`p-4 rounded-xl ${isDark ? 'bg-gray-800/50 hover:bg-gray-800' : 'bg-white hover:bg-gray-50'} border ${isDark ? 'border-gray-700' : 'border-gray-200'} transition-all cursor-pointer group`}
                onClick={() => playStation(station)}
              >
                <div className="flex items-center gap-4">
                  <div className={`w-14 h-14 rounded-xl bg-gradient-to-br ${getStationColor(station)} flex items-center justify-center flex-shrink-0`}>
                    {station.logoUrl ? (
                      <img src={station.logoUrl} alt={station.name} className="w-10 h-10 rounded-lg object-cover" />
                    ) : (
                      <Radio className="w-6 h-6 text-white" />
                    )}
                  </div>
                  <div className="flex-1 min-w-0">
                    <h3 className={`font-semibold truncate ${isDark ? 'text-white' : 'text-gray-900'}`}>
                      {station.name}
                    </h3>
                    <p className={`text-sm ${isDark ? 'text-gray-400' : 'text-gray-600'}`}>
                      {(station.genres || []).slice(0, 2).join(', ')} • {station.country}
                    </p>
                    <p className={`text-xs ${isDark ? 'text-gray-500' : 'text-gray-500'} flex items-center gap-1`}>
                      <Waves className="w-3 h-3" />
                      {station.bitrate || 128}kbps
                    </p>
                  </div>
                  <div className="flex items-center gap-2">
                    <button
                      onClick={(e) => { e.stopPropagation(); toggleFavorite(station.id); }}
                      className={`p-2 rounded-full transition-colors ${favorites.includes(station.id) ? 'text-red-500' : isDark ? 'text-gray-600 hover:text-white' : 'text-gray-400 hover:text-gray-900'}`}
                    >
                      <Heart className={`w-4 h-4 ${favorites.includes(station.id) ? 'fill-current' : ''}`} />
                    </button>
                    <div className={`p-2 rounded-full opacity-0 group-hover:opacity-100 transition-opacity ${isDark ? 'bg-amber-500' : 'bg-amber-500'}`}>
                      <Play className="w-4 h-4 text-white" />
                    </div>
                  </div>
                </div>
              </motion.div>
            ))}
          </div>
        </section>
      </div>

      {/* Bottom Player with Gateway Two Status */}
      <AnimatePresence>
        {showPlayer && currentStation && (
          <motion.div
            initial={{ y: 100 }}
            animate={{ y: 0 }}
            exit={{ y: 100 }}
            className={`fixed bottom-0 left-0 right-0 ${isDark ? 'bg-gray-900/95' : 'bg-white/95'} backdrop-blur-xl border-t ${isDark ? 'border-gray-800' : 'border-gray-200'} p-4`}
            data-testid="radio-player"
          >
            <div className="max-w-7xl mx-auto flex items-center justify-between">
              {/* Station Info */}
              <div className="flex items-center gap-4">
                <div className={`w-12 h-12 rounded-lg bg-gradient-to-br ${currentStation.color || 'from-amber-500 to-orange-600'} flex items-center justify-center`}>
                  <Waves className="w-5 h-5 text-white animate-pulse" />
                </div>
                <div>
                  <h4 className={`font-semibold ${isDark ? 'text-white' : 'text-gray-900'}`}>
                    {currentStation.name}
                  </h4>
                  <p className={`text-sm ${isDark ? 'text-gray-400' : 'text-gray-600'}`}>
                    {nowPlaying || (currentStation.host_persona ? `Hosted by ${currentStation.host_persona}` : (currentStation.genres || []).join(', '))}
                  </p>
                </div>
                
                {/* Gateway Two Badge */}
                {currentStation.gatewayService && (
                  <div className={`flex items-center gap-1.5 px-2 py-1 rounded-full ${isDark ? 'bg-green-500/20' : 'bg-green-100'}`}>
                    <Zap className="w-3 h-3 text-green-500" />
                    <span className="text-xs text-green-500 font-medium">
                      via {GATEWAY_SERVICES[currentStation.gatewayService]?.name || currentStation.gatewayService}
                    </span>
                  </div>
                )}
              </div>

              {/* Controls */}
              <div className="flex items-center gap-4">
                <Button variant="ghost" size="icon">
                  <SkipBack className="w-5 h-5" />
                </Button>
                <Button 
                  onClick={() => setIsPlaying(!isPlaying)}
                  className="w-12 h-12 rounded-full bg-amber-500 hover:bg-amber-600"
                  data-testid="play-pause-btn"
                >
                  {isPlaying ? <Pause className="w-5 h-5" /> : <Play className="w-5 h-5 ml-0.5" />}
                </Button>
                <Button variant="ghost" size="icon">
                  <SkipForward className="w-5 h-5" />
                </Button>
              </div>

              {/* Volume */}
              <div className="flex items-center gap-3 w-40">
                <button onClick={() => setIsMuted(!isMuted)}>
                  {isMuted ? <VolumeX className="w-5 h-5 text-gray-500" /> : <Volume2 className="w-5 h-5 text-gray-500" />}
                </button>
                <Slider
                  value={[isMuted ? 0 : volume]}
                  onValueChange={(val) => { setVolume(val[0]); setIsMuted(false); }}
                  max={100}
                  step={1}
                  className="flex-1"
                />
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default RadioPage;
