// ═══════════════════════════════════════════════════════════════════════════
// SOVEREIGN SHELL — the DESIGN layer. Proportion canon, layout architecture,
// skeleton. One persistent shell for the whole Forge:
//
//   Mobile-first  → top bar + bottom tab bar (thumb reach, safe-area aware)
//   Desktop       → fixed sidebar + top context bar
//   Every route  → Omina page transition on navigation
//
// All styling welds to the Obsidian tokens. Nothing here invents color.
// ═══════════════════════════════════════════════════════════════════════════

import React from 'react';
import { NavLink, Outlet, useLocation } from 'react-router-dom';
import { AnimatePresence, motion, MotionConfig } from 'framer-motion';
import { SECTIONS, HOME_SEAL, Wordmark } from '@/components/Sigil';
import { omina } from '@/motion/omina';
import { cn } from '@/lib/utils';

function sectionForPath(pathname) {
  if (pathname === '/') return HOME_SEAL.id;
  const hit = SECTIONS.find((s) =>
    s.routes.some((r) => pathname === r || pathname.startsWith(r + '/'))
  );
  return hit ? hit.id : null;
}

// Canon: DESIGN ← AMETHYST + RUBY. Nav is structural — active states burn ruby.
function NavItem({ section, active, layout }) {
  const Icon = section.icon;
  const isActive = active === section.id;
  return (
    <motion.div {...omina.tap}>
      <NavLink
        to={section.home}
        className={cn(
          'group flex items-center gap-3 rounded-svmd px-3 py-2.5 text-sm font-medium transition-colors',
          layout === 'tab'
            ? 'flex-col gap-1 px-1 py-2 text-[10px] leading-none'
            : '',
          isActive
            ? 'bg-obsidian-700 text-ink'
            : 'text-ink-dim hover:bg-obsidian-800 hover:text-ink'
        )}
        aria-current={isActive ? 'page' : undefined}
      >
        <Icon
          className={cn('h-5 w-5 shrink-0 transition-colors', isActive ? 'text-ruby-500' : 'text-ink-mute group-hover:text-ink-dim')}
          aria-hidden
        />
        <span className={layout === 'tab' ? '' : 'truncate'}>{section.label}</span>
        {layout === 'side' && isActive && (
          <span className="ml-auto h-1.5 w-1.5 rounded-full bg-ruby-500" aria-hidden />
        )}
      </NavLink>
    </motion.div>
  );
}

export default function SovereignShell() {
  const location = useLocation();
  const active = sectionForPath(location.pathname);
  const tabs = [HOME_SEAL, ...SECTIONS];

  return (
    <MotionConfig reducedMotion="user">
      <div className="min-h-screen min-h-dvh bg-obsidian-950 text-ink">
        {/* ── Desktop sidebar ─────────────────────────────────────────── */}
        <aside className="fixed inset-y-0 left-0 z-40 hidden w-60 flex-col border-r border-line bg-obsidian-900/95 backdrop-blur md:flex">
          <div className="border-b border-line px-5 py-5">
            <NavLink to="/" aria-label="Benny's Studio home">
              <Wordmark />
            </NavLink>
          </div>
          <nav className="flex-1 space-y-1 overflow-y-auto px-3 py-4" aria-label="Forge sections">
            <NavItem section={HOME_SEAL} active={active} layout="side" />
            <div className="px-3 pb-1 pt-3 text-[10px] font-semibold uppercase tracking-[0.22em] text-ink-mute">
              The Forge
            </div>
            {SECTIONS.map((s) => (
              <NavItem key={s.id} section={s} active={active} layout="side" />
            ))}
          </nav>
          <div className="border-t border-line px-5 py-4">
            <p className="text-[10px] uppercase tracking-[0.22em] text-ink-mute">Welded with Obsidian</p>
            <p className="mt-1 text-xs text-ink-dim">Sovereign AI Creative Studio</p>
          </div>
        </aside>

        {/* ── Mobile top bar ──────────────────────────────────────────── */}
        <header className="sticky top-0 z-40 border-b border-line bg-obsidian-950/90 backdrop-blur md:hidden">
          <div className="flex items-center justify-between px-4 py-3">
            <NavLink to="/" aria-label="Benny's Studio home">
              <Wordmark compact />
            </NavLink>
            <span className="text-[10px] font-semibold uppercase tracking-[0.22em] text-ink-mute">
              Forge 66
            </span>
          </div>
        </header>

        {/* ── Main ────────────────────────────────────────────────────── */}
        <div className="md:pl-60">
          <AnimatePresence mode="wait">
            <motion.main
              key={location.pathname}
              variants={omina.page}
              initial="initial"
              animate="animate"
              exit="exit"
              className="mx-auto w-full max-w-6xl px-4 pb-28 pt-6 md:px-8 md:pb-16 md:pt-10"
            >
              <Outlet />
            </motion.main>
          </AnimatePresence>

          <footer className="border-t border-line px-4 py-8 md:px-8">
            <div className="mx-auto flex max-w-6xl flex-col gap-2 md:flex-row md:items-center md:justify-between">
              <p className="text-xs text-ink-mute">
                <span className="font-semibold text-gold-400" style={{ fontFamily: 'var(--sv-font-display)' }}>
                  Benny&rsquo;s Studio
                </span>{' '}
                — Sovereign Creative Forge
              </p>
              <p className="text-xs text-ink-mute">
                Write it. Score it. Screen it. Publish it.
              </p>
            </div>
          </footer>
        </div>

        {/* ── Mobile bottom tab bar ───────────────────────────────────── */}
        <nav
          aria-label="Forge sections"
          className="fixed inset-x-0 bottom-0 z-40 border-t border-line bg-obsidian-900/95 backdrop-blur md:hidden"
          style={{ paddingBottom: 'env(safe-area-inset-bottom)' }}
        >
          <div className="grid grid-cols-7 px-1">
            {tabs.map((s) => (
              <NavItem key={s.id} section={s} active={active} layout="tab" />
            ))}
          </div>
        </nav>
      </div>
    </MotionConfig>
  );
}
