import React, { useCallback, useEffect, useRef, useState } from 'react';
import { COMMANDER, XO, SQUADS, allAgents } from './roster';
import { simulateTick } from './simulation';

const API = '/api/serpent-strike/live';

const KIND_STYLE = {
  directive: { border: '#e8b34b', label: 'DIRECTIVE', color: '#e8b34b' },
  relay: { border: '#7dd3fc', label: 'XO RELAY', color: '#7dd3fc' },
  report: { border: '#4ade80', label: 'SQUAD REPORT', color: '#4ade80' },
  tactic: { border: '#c084fc', label: 'TACTIC DEBATE', color: '#c084fc' },
};

async function apiGet(path) {
  const r = await fetch(`${API}${path}`);
  if (!r.ok) throw new Error(`GET ${path} -> ${r.status}`);
  return r.json();
}

async function apiPost(path) {
  const r = await fetch(`${API}${path}`, { method: 'POST' });
  if (!r.ok) throw new Error(`POST ${path} -> ${r.status}`);
  return r.json();
}

export default function SerpentStrikeWarRoom() {
  const [mode, setMode] = useState('connecting'); // connecting | live | simulation
  const [feed, setFeed] = useState([]);
  const [tick, setTick] = useState(0);
  const [directive, setDirective] = useState(null);
  const [squads, setSquads] = useState(SQUADS);
  const [agents] = useState(allAgents());
  const [busy, setBusy] = useState(false);
  const feedRef = useRef(null);

  const loadLive = useCallback(async () => {
    const [state, feedRes, squadsRes, dirRes] = await Promise.all([
      apiGet('/state'), apiGet('/feed?limit=50'), apiGet('/squads'), apiGet('/directive'),
    ]);
    setTick(state.tick);
    setFeed(feedRes.messages || []);
    if (squadsRes.squads && squadsRes.squads.length) {
      setSquads(squadsRes.squads.map((s) => {
        const canon = SQUADS.find((c) => c.name === s.name);
        return { ...s, members: canon ? canon.members : [] };
      }));
    }
    setDirective(dirRes.directive);
    setMode('live');
  }, []);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        await loadLive();
      } catch (e) {
        if (!cancelled) {
          // No backend reachable (static prototype) — clearly-labeled simulation.
          const sim = simulateTick();
          setTick(sim.tick);
          setFeed(sim.messages);
          setDirective(sim.directive);
          setMode('simulation');
        }
      }
    })();
    return () => { cancelled = true; };
  }, [loadLive]);

  useEffect(() => {
    if (feedRef.current) feedRef.current.scrollTop = feedRef.current.scrollHeight;
  }, [feed]);

  const runTick = useCallback(async () => {
    if (busy) return;
    setBusy(true);
    try {
      if (mode === 'live') {
        const rec = await apiPost('/tick');
        setTick(rec.tick);
        setFeed((f) => [...f, ...rec.messages].slice(-200));
        const dirRes = await apiGet('/directive');
        setDirective(dirRes.directive);
      } else {
        const sim = simulateTick();
        setTick(sim.tick);
        setFeed((f) => [...f, ...sim.messages].slice(-200));
        setDirective(sim.directive);
      }
    } catch (e) {
      if (mode === 'live') {
        // Backend dropped mid-session — fall back honestly.
        const sim = simulateTick();
        setTick(sim.tick);
        setFeed((f) => [...f, ...sim.messages].slice(-200));
        setDirective(sim.directive);
        setMode('simulation');
      }
    } finally {
      setBusy(false);
    }
  }, [busy, mode]);

  const sim = mode === 'simulation';

  return (
    <div style={styles.shell}>
      <header style={styles.header}>
        <div>
          <div style={styles.title}>SERPENT STRIKE — WAR ROOM</div>
          <div style={styles.subtitle}>
            {COMMANDER.name} commanding · {XO.name} executive officer · {agents.length} agents live
          </div>
        </div>
        <div style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
          <span style={{ ...styles.badge, ...(sim ? styles.badgeSim : styles.badgeLive) }}>
            {mode === 'connecting' ? 'CONNECTING…' : sim ? 'SIMULATION — NOT LIVE BATTALION OUTPUT' : 'LIVE BATTALION FEED'}
          </span>
          <span style={styles.tick}>TICK {tick}</span>
        </div>
      </header>

      {sim && (
        <div style={styles.simNotice}>
          Backend unreachable — running in clearly-labeled simulation mode. No real leads are touched;
          no vendors are provisioned. Connect the Forge 66 backend for the live battalion.
        </div>
      )}

      <div style={styles.grid}>
        {/* Comms feed */}
        <section style={styles.panel}>
          <div style={styles.panelTitle}>LIVE COMMS FEED</div>
          <div ref={feedRef} style={styles.feed}>
            {feed.map((m) => {
              const ks = KIND_STYLE[m.kind] || KIND_STYLE.report;
              return (
                <div key={m.id} style={{ ...styles.msg, borderLeftColor: ks.border }}>
                  <div style={styles.msgHead}>
                    <span style={{ ...styles.kind, color: ks.color }}>{ks.label}</span>
                    <span style={styles.author}>{m.author}</span>
                    <span style={styles.ts}>{new Date(m.ts).toLocaleTimeString()}</span>
                  </div>
                  <div style={styles.msgText}>{m.text}</div>
                </div>
              );
            })}
            {feed.length === 0 && <div style={styles.empty}>No traffic yet. Run a tick.</div>}
          </div>
        </section>

        {/* Squad board */}
        <section style={styles.panel}>
          <div style={styles.panelTitle}>SQUAD BOARD</div>
          <div style={styles.squads}>
            {squads.map((s) => (
              <div key={s.squad_id || s.name} style={styles.squad}>
                <div style={styles.squadName}>{s.name}</div>
                <div style={styles.squadFocus}>{s.focus}</div>
                <div style={styles.squadMeta}>
                  {(s.members || []).length || s.agents || 6} agents · lead {(s.members && s.members[0] && s.members[0].callsign) || s.lead}
                </div>
              </div>
            ))}
          </div>
          <div style={styles.panelTitle}>PIPELINE (READ-ONLY)</div>
          <div style={styles.pipeline}>
            {sim ? (
              <span>Standby — pipeline observation requires the live backend. Ticks never mutate leads.</span>
            ) : (
              <span>Observing live pipeline. Ticks never mutate leads or provision vendors.</span>
            )}
          </div>
        </section>

        {/* Directive console */}
        <section style={styles.panel}>
          <div style={styles.panelTitle}>DIRECTIVE CONSOLE</div>
          <div style={styles.directiveBox}>
            {directive ? directive.text : 'No directive issued yet.'}
          </div>
          <button style={styles.tickBtn} onClick={runTick} disabled={busy}>
            {busy ? 'RUNNING…' : 'RUN TICK'}
          </button>
          <div style={styles.consoleNote}>
            One tick = Shelby directive → Merle relay → 5 squad reports → 2 tactic debates.
            {sim ? ' (simulated)' : ''}
          </div>
          <div style={styles.panelTitle}>COMMAND</div>
          <div style={styles.cmdRow}><b>{COMMANDER.callsign}</b> — {COMMANDER.role}</div>
          <div style={styles.cmdRow}><b>{XO.callsign}</b> — {XO.role}</div>
        </section>
      </div>
    </div>
  );
}

const styles = {
  shell: { minHeight: '100vh', background: '#0a0e14', color: '#d7dee9', fontFamily: 'JetBrains Mono, monospace', padding: 20 },
  header: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '2px solid #1c2530', paddingBottom: 14, marginBottom: 14 },
  title: { fontSize: 22, fontWeight: 800, letterSpacing: 2, color: '#e8b34b' },
  subtitle: { fontSize: 12, color: '#8b98a9', marginTop: 4 },
  badge: { fontSize: 11, fontWeight: 700, padding: '6px 10px', borderRadius: 4, letterSpacing: 1 },
  badgeLive: { background: '#12351f', color: '#4ade80', border: '1px solid #4ade80' },
  badgeSim: { background: '#3a2a10', color: '#e8b34b', border: '1px solid #e8b34b' },
  tick: { fontSize: 14, fontWeight: 700, color: '#7dd3fc' },
  simNotice: { background: '#2a1f08', border: '1px solid #e8b34b', color: '#f0d089', padding: 10, borderRadius: 6, fontSize: 12, marginBottom: 14 },
  grid: { display: 'grid', gridTemplateColumns: '1.4fr 1fr 1fr', gap: 14 },
  panel: { background: '#10161f', border: '1px solid #1c2530', borderRadius: 8, padding: 14 },
  panelTitle: { fontSize: 12, fontWeight: 700, letterSpacing: 2, color: '#8b98a9', marginBottom: 10, marginTop: 6 },
  feed: { maxHeight: 560, overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: 8 },
  msg: { background: '#141b26', borderLeft: '3px solid #4ade80', borderRadius: 4, padding: 8 },
  msgHead: { display: 'flex', gap: 8, fontSize: 10, marginBottom: 4, alignItems: 'baseline' },
  kind: { fontWeight: 800, letterSpacing: 1 },
  author: { color: '#d7dee9', fontWeight: 600 },
  ts: { color: '#5b6b7f', marginLeft: 'auto' },
  msgText: { fontSize: 12, lineHeight: 1.5, color: '#c3cedd' },
  empty: { color: '#5b6b7f', fontSize: 12, padding: 20, textAlign: 'center' },
  squads: { display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 8 },
  squad: { background: '#141b26', borderRadius: 4, padding: 8 },
  squadName: { fontSize: 13, fontWeight: 700, color: '#e8b34b' },
  squadFocus: { fontSize: 11, color: '#8b98a9' },
  squadMeta: { fontSize: 11, color: '#5b6b7f', marginTop: 4 },
  pipeline: { background: '#141b26', borderRadius: 4, padding: 10, fontSize: 12, color: '#8b98a9' },
  directiveBox: { background: '#141b26', border: '1px solid #e8b34b', borderRadius: 4, padding: 12, fontSize: 13, lineHeight: 1.6, minHeight: 90, color: '#f0d089' },
  tickBtn: { marginTop: 12, width: '100%', padding: 12, background: '#e8b34b', color: '#0a0e14', border: 'none', borderRadius: 4, fontWeight: 800, letterSpacing: 2, cursor: 'pointer', fontFamily: 'inherit' },
  consoleNote: { fontSize: 11, color: '#5b6b7f', marginTop: 8, lineHeight: 1.5 },
  cmdRow: { fontSize: 12, color: '#c3cedd', padding: '4px 0' },
};
