/**
 * EmporiumRouteAssembly.jsx — itinerary matrix from /api/emporium/foundation.
 * Route builder → POST /foundation/route and /foundation/price.
 * Mach dial + fuel gauge are pure styled divs (no external libs).
 */
import React, { useState } from 'react';
import { useApiGet, apiPost, asArray, pick } from './emporiumApi';
import { Rivets, LoadingState, EmptyState, ErrorState, Readout, Kv, MontiffProgress } from './montiff-ui';

const AIRPORTS = ['JFK', 'LHR', 'CDG', 'NRT', 'DXB', 'SIN', 'LAX', 'MIA', 'HND', 'AMS', 'SYD', 'GRU', 'JNB'];
const HUBS = ['JFK', 'LHR', 'DXB', 'SIN'];
const FARE_CLASSES = [
  { key: 'ECO', mult: 1.0 },
  { key: 'BUS', mult: 2.6 },
  { key: 'FIRST', mult: 4.2 },
  { key: 'VIP', mult: 7.5 },
];
const MACH_BASELINE = 2.04;

function MachDial({ mach, testid }) {
  const m = Number(mach);
  const pct = Number.isFinite(m) ? Math.max(0, Math.min(1, m / 3)) : 0;
  const deg = -90 + pct * 180;
  return (
    <div className="montiff-gauge" data-testid={testid}>
      <div className="montiff-readout" style={{ fontSize: 12, color: 'var(--montiff-steel-400)', marginBottom: 6 }}>MACH DIAL</div>
      <div className="montiff-dial" aria-hidden="true">
        <div className="montiff-dial-arc" />
        <div className="montiff-dial-needle" style={{ transform: `rotate(${deg}deg)` }} />
        <div className="montiff-dial-hub" />
      </div>
      <div className="montiff-readout" style={{ textAlign: 'center', fontSize: 26, fontWeight: 700, marginTop: 4 }}>
        M {Number.isFinite(m) ? m.toFixed(2) : '—'}
      </div>
      <div className="montiff-gauge-ticks"><span>0</span><span>1.5</span><span>3.0</span></div>
    </div>
  );
}

function FuelGauge({ pct, testid }) {
  const p = Math.max(0, Math.min(100, Number(pct) || 0));
  const color = p > 60 ? 'var(--montiff-green)' : p > 25 ? 'var(--montiff-yellow)' : 'var(--montiff-red)';
  return (
    <div className="montiff-gauge" data-testid={testid}>
      <div className="montiff-readout" style={{ fontSize: 12, color: 'var(--montiff-steel-400)', marginBottom: 6 }}>FUEL RESERVE</div>
      <div className="montiff-gauge-track">
        <div className="montiff-gauge-fill" style={{ width: `${p}%`, background: color }} />
      </div>
      <div className="montiff-gauge-ticks"><span>EMPTY</span><span>{p.toFixed(0)}%</span><span>FULL</span></div>
    </div>
  );
}

export default function EmporiumRouteAssembly() {
  const atlas = useApiGet('/api/emporium/foundation/atlas');
  const [origin, setOrigin] = useState('JFK');
  const [destination, setDestination] = useState('DXB');
  const [fareClass, setFareClass] = useState('ECO');
  const [route, setRoute] = useState(null);
  const [price, setPrice] = useState(null);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState(null);

  const airports = asArray(atlas.data);
  const airportCodes = airports.length > 0
    ? airports.map((a) => String(pick(a, ['code', 'iata', 'id'], '')).toUpperCase()).filter(Boolean)
    : AIRPORTS;

  async function assemble() {
    setBusy(true);
    setErr(null);
    setRoute(null);
    setPrice(null);
    const [rRoute, rPrice] = await Promise.all([
      apiPost('/api/emporium/foundation/route', { origin, destination, fare_class: fareClass }),
      apiPost('/api/emporium/foundation/price', { origin, destination, fare_class: fareClass }),
    ]);
    setBusy(false);
    if (!rRoute.ok) { setErr(rRoute.error); return; }
    if (!rPrice.ok) { setErr(rPrice.error); return; }
    setRoute(rRoute.data);
    setPrice(rPrice.data);
  }

  const legs = route ? asArray(route, ['legs', 'segments', 'itinerary']) : [];
  const mach = pick(route || {}, ['mach', 'cruise_mach', 'avg_mach'], pick(price || {}, ['mach'], null));
  const fuelPct = pick(route || {}, ['fuel_reserve_pct', 'fuel_pct', 'fuel'], null);

  return (
    <div className="montiff-page montiff-stack" data-testid="emporium-route-assembly">
      <section className="montiff-panel" data-testid="route-builder-panel">
        <Rivets />
        <div className="montiff-brand" style={{ color: 'var(--montiff-cobalt)' }}>ITINERARY MATRIX</div>
        <h1 className="montiff-h">ROUTE ASSEMBLY</h1>

        {/* Airport atlas */}
        <div className="montiff-h-sm">AIRPORT ATLAS</div>
        {atlas.loading && <LoadingState label="CHARTING AIRPORT ATLAS…" />}
        {atlas.error && <ErrorState message={atlas.error} onRetry={atlas.reload} testid="route-atlas-error" />}
        {!atlas.loading && !atlas.error && (
          <div className="montiff-grid" style={{ gridTemplateColumns: 'repeat(auto-fill, minmax(110px, 1fr))', marginBottom: 18 }} data-testid="route-atlas-grid">
            {airportCodes.map((code) => (
              <button
                key={code}
                className={`montiff-source-tile${HUBS.includes(code) ? ' selected' : ''}`}
                data-testid={`route-atlas-airport-${code}`}
                onClick={() => setOrigin(code)}
                title={HUBS.includes(code) ? 'Hub — click to set as origin' : 'Click to set as origin'}
              >
                <div className="montiff-readout" style={{ fontWeight: 700, fontSize: 18 }}>{code}</div>
                <div className="montiff-readout montiff-muted" style={{ fontSize: 10 }}>{HUBS.includes(code) ? '★ HUB' : 'PORT'}</div>
              </button>
            ))}
          </div>
        )}

        {/* Builder form */}
        <div className="montiff-form-row" data-testid="route-builder-form">
          <div className="montiff-field">
            <label className="montiff-label">ORIGIN</label>
            <select className="montiff-select" data-testid="route-origin-select" value={origin} onChange={(e) => setOrigin(e.target.value)}>
              {airportCodes.map((c) => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>
          <div className="montiff-field">
            <label className="montiff-label">DESTINATION</label>
            <select className="montiff-select" data-testid="route-destination-select" value={destination} onChange={(e) => setDestination(e.target.value)}>
              {airportCodes.map((c) => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>
          <div className="montiff-field">
            <label className="montiff-label">FARE CLASS</label>
            <select className="montiff-select" data-testid="route-fare-class-select" value={fareClass} onChange={(e) => setFareClass(e.target.value)}>
              {FARE_CLASSES.map((f) => <option key={f.key} value={f.key}>{f.key} ×{f.mult}</option>)}
            </select>
          </div>
        </div>
        <button className="montiff-btn" data-testid="route-assemble-button" onClick={assemble} disabled={busy}>
          {busy ? 'ASSEMBLING…' : 'ASSEMBLE ROUTE'}
        </button>
      </section>

      {busy && <LoadingState label="WELDING ITINERARY MATRIX…" />}
      {err && <ErrorState message={err} testid="route-assemble-error" />}

      {(route || price) && !busy && (
        <section className="montiff-grid-2" data-testid="route-result">
          <div className="montiff-panel" data-testid="route-itinerary-panel">
            <Rivets />
            <div className="montiff-h-sm">ITINERARY MATRIX</div>
            {legs.length === 0 ? (
              <div>
                <Kv k="ORIGIN" v={pick(route, ['origin', 'from'], origin)} />
                <Kv k="DESTINATION" v={pick(route, ['destination', 'to'], destination)} />
                <Kv k="DISTANCE" v={pick(route, ['distance_km', 'distance', 'km'], '—')} />
                <Kv k="DURATION" v={pick(route, ['duration', 'flight_time', 'eta'], '—')} />
                <Kv k="STOPS" v={pick(route, ['stops', 'connections'], '0')} />
              </div>
            ) : (
              <div className="montiff-table-wrap">
                <table className="montiff-table" data-testid="route-legs-table">
                  <thead><tr><th>LEG</th><th>FROM</th><th>TO</th><th>DIST</th></tr></thead>
                  <tbody>
                    {legs.map((leg, i) => (
                      <tr key={i}>
                        <td>{i + 1}</td>
                        <td>{pick(leg, ['from', 'origin'], '—')}</td>
                        <td>{pick(leg, ['to', 'destination'], '—')}</td>
                        <td>{pick(leg, ['distance_km', 'distance'], '—')}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
            <hr className="montiff-divider" />
            <div className="montiff-h-sm">PRICE LAB</div>
            <div className="montiff-grid-2" style={{ gridTemplateColumns: 'repeat(auto-fit, minmax(140px, 1fr))' }}>
              <Readout label="BASE FARE" value={pick(price, ['base_fare', 'base', 'subtotal'], '—')} testid="route-price-base" />
              <Readout label="TOTAL" value={pick(price, ['total', 'price', 'grand_total'], '—')} testid="route-price-total" />
              <Readout label="COMMISSION" value={pick(price, ['commission', 'commission_earned'], '—')} testid="route-price-commission" />
            </div>
          </div>

          <div className="montiff-stack" data-testid="route-gauges">
            <MachDial mach={mach === null ? MACH_BASELINE : mach} testid="route-mach-dial" />
            <FuelGauge pct={fuelPct === null ? 82 : fuelPct} testid="route-fuel-gauge" />
            <div className="montiff-panel-flat" data-testid="route-telemetry">
              <div className="montiff-h-sm">TELEMETRY</div>
              <Kv k="MACH BASELINE" v={MACH_BASELINE} />
              <Kv k="FARE CLASS" v={fareClass} />
              <Kv k="MULTIPLIER" v={`×${(FARE_CLASSES.find((f) => f.key === fareClass) || {}).mult || 1}`} />
              <div style={{ marginTop: 10 }}>
                <div className="montiff-readout montiff-muted" style={{ fontSize: 11, marginBottom: 4 }}>ROUTE EFFICIENCY</div>
                <MontiffProgress pct={fuelPct === null ? 82 : fuelPct} testid="route-efficiency-bar" />
              </div>
            </div>
          </div>
        </section>
      )}

      {!route && !price && !busy && !err && (
        <EmptyState label="NO ROUTE ASSEMBLED — PICK PORTS AND HIT ASSEMBLE" testid="route-empty" />
      )}
    </div>
  );
}
